import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст преподобному Йосифу, ігумену Волоцькому","e":"Akathist to our Venerable Father Joseph, Abbot of Volokolamsk","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і ди́вний благоче́стія подви́жниче, преподо́бне о́тче Іо́сифе, і́же сугу́бий сви́ше дар приє́мий богові́дінія же і ісціле́ній, я́ко імі́яй дерзнове́ніє ко Святі́й Тро́йці моли́ ізба́витися нам от находя́щих бід і скорбе́й і болі́зней, да любо́вію зове́м ті:","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела во пло́ті тя ві́дуще, преподо́бне Іо́сифе, по́сланна от Бо́га, да яви́ть тобо́ю в челові́ціх о́браз і́стиннаго благоче́стія і до́брих діл, чудя́щеся путе́м Єго́, во вре́меннім житії́ твоє́м явле́нним, і вели́чіє благоутро́бія Єго́ прославля́юще, во умиле́нії серде́чнім взива́єм ті си́це:","Ра́дуйся, до́браго ко́рене о́трасле благоро́дная;","ра́дуйся, лозо́ виногра́да Христо́ва многопло́дная.","Ра́дуйся, ча́до моли́тви роди́телей благочести́вих;","ра́дуйся, наде́ждо і утіше́ніє серде́ць їх боголюби́вих.","Ра́дуйся, ізді́тська страх Госпо́день стяжа́вий;","ра́дуйся, сі́м'я сло́ва Бо́жия от ю́ности восприя́вий.","Ра́дуйся, ізмла́да смире́нія і молча́нія храни́телю;","ра́дуйся, моли́тви і воздержа́нія ревни́телю.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с благо́є се́рдця твоєго́ ізволе́ніє і раче́ніє, я́ко от ю́ности немо́лчно прославля́л єси́ І́м'я Госпо́днє чте́нієм і пі́нієм псалмо́в і пі́сней свяще́нних во святі́м хра́мі Єго́, в ски́нії небе́сній вчини́ тя, преподо́бне, в ли́ці пра́ведник соверше́нних возноси́ти єму́ ку́пно с ни́ми а́нгельськоє пі́ніє: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в от писа́ній оте́чеських благи́х ми́ра сего́ тщету́, ісхо́д же от вре́меннаго сего́ житія́ непреста́нно помишля́я і пребива́я при́сно в сокрове́ннім по́двизі моли́тви, ніка́коже се́рдцем приліпи́лся єси́ к су́щим от ми́ра, ра́зві то́чію к єди́ному достойнейшему от све́рстник твої́х, с ни́мже і путь богоуго́днаго і́ночеськаго житія́ от дній о́трочества предизбрал єси́, преподо́бне. Ті́мже ублажа́єм тя си́це:","Ра́дуйся, цві́те благоуха́нний до́браго воспита́нія;","ра́дуйся, сосу́де Боже́ственнаго ізбра́нія.","Ра́дуйся, в разумі́ Бо́гом просвіще́нний;","ра́дуйся, се́рдцем в Бо́зі утвержде́нний.","Ра́дуйся, о́бразе содру́жества непоро́чнаго і неле́стнаго;","ра́дуйся, вседуше́вні взиска́вий Ца́рствія Небе́снаго.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 3","ps":["Бу́рю помишле́ній мирськи́х препобіжда́я благода́тію Христо́вою, по́мислом лу́чшим восте́кл єси́ к Небе́сним, преподо́бне, в Го́рняя впери́в ум твой безм'ятежний і безстра́стний, і во́лю всеці́ло покори́в под і́го Христо́во, ті́ло же твоє́ соді́лал єси́ жили́щем Ду́ха Свята́го, отню́дуже і в тілесі́, я́ко безпло́тен, со безпло́тними взива́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Ре́вность імі́яй о соверше́ннім житії́ христия́нстім і от писа́ній оте́чеських науче́н, є́же вда́ти себі́ в послуша́ніє іску́сну руководи́телю і наста́внику неле́стну, в ю́ності роди́телі твоя́ оста́вил єси́, преподо́бне, і положи́л єси́ в се́рдці твоє́м вопроси́ти духо́внаго ста́рця Варсоно́фія, да єще́ что рече́ть, бу́ди то тебі́, я́ко сло́во Самаго́ Бо́га, є́же і сверши́ся во благо́є Бо́жиїм устроє́нієм; сего́ ра́ди, толи́коє ві́ри твоєя́ упова́ніє ублажа́юще, взива́єм ті:","Ра́дуйся, я́ко любе́зная і кра́сная ми́ра сего́ презрі́л єси́;","ра́дуйся, я́ко Небе́сних і нетлі́нних жела́нієм вожделі́л єси́.","Ра́дуйся, вну́треннею Креста́ Христо́ва красото́ю восхище́нний;","ра́дуйся, си́лою Сви́ше на труд крестоноше́нія облече́нний.","Ра́дуйся, во́лею тве́рдою во́лі своєя́ отреки́йся;","ра́дуйся, отсіче́нієм страсте́й угоди́вий Бо́гу і спаси́йся.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 4","ps":["Си́лою любве́ Бо́жия влеко́м к вя́щшему житія́ і́ночеськаго соверше́нству і му́дре послі́дуя сові́ту і благослове́нію прозорли́ваго і свята́го ста́рця Варсоно́фія, прише́л єси́ во оби́тель преподо́бнаго Пафну́тія і того́ умоли́л єси́ прия́ти тя в послуша́ніє, да ку́пно с ним в труді́х і по́двизіх ви́ну благоугожда́яй Бо́гу, воспіва́єши: Аллилу́я."]},{"h":"Ікос 4","ps":["Прови́дя ду́хом благо́є проізволе́ніє ю́ноши, чистоту́ же душе́вную і благода́тноє призва́ніє єго́, преподо́бний Пафну́тій а́біє облече́ єго́ во і́ночеський о́браз і возложи́ нань і́го послушаній, я́же со усе́рдієм в простоті́ і в терпі́нії мно́зі ісполня́ше, я́ко би́ти єму́ о́бразом безпрекословнаго повинове́нія, труда́ і благоче́стія; ті́мже ни́ні зове́м єму́ си́це:","Ра́дуйся, ті́сний путь спасе́нія от ю́ности возлюби́вий;","ра́дуйся, яре́м Госпо́день на ви́ю свою́ возложи́вий.","Ра́дуйся, свяще́нними обі́ти во́лю свою́ связа́вий;","ра́дуйся, себе́ і весь живо́т свой Го́сподеві преда́вий.","Ра́дуйся, коєму́ждо во бла́го усе́рдний служи́телю;","ра́дуйся, боля́щих і немощни́х успокоїтелю.","Ра́дуйся, по́мисли плотські́я си́лою моли́тви прогоня́яй;","ра́дуйся, сомня́щихся во ві́рі сло́вом Бо́жиїм утвержда́яй.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 5","ps":["Боже́ственною любо́вію распалаєм і бли́жніх твої́х, і́же в ми́рі, не отве́рглся єси́ се́рдцем, преподо́бне: сли́шав бо ста́рця отця́ твоєго́ в разслабле́нії тіле́снім су́ща, умоли́л єси́ преподо́бнаго Пафну́тія во оби́тель того́ прия́ти і надо́лзі послужи́л єси́ боля́щему роди́телю твоєму́, со вся́ким раче́нієм призира́я єго́ і пита́я тіле́сні рука́ма твої́ма і духо́вні сло́вом Бо́жиїм до са́мия кончи́ни, я́ко тому́ взива́ти к тебі́: Не аз ті оте́ць, но ти мі оте́ць єси́. Сей у́бо труд любве́ твоєя́ сино́внія восхваля́юще, я́ко же́ртву богоприя́тну, поє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Іми́й во оби́телі осмна́десять літ житія́ в послуша́нії, бді́нії, поще́нії і науче́нії писа́нієм святи́х і духоно́сних оте́ць, єгда́ наста́ час блаже́нния кончи́ни преподо́бнаго Пафну́тія, нача́льствовати по нем, а́ще і не хотя́й, при́зван бил єси́ і во пресви́тера поста́влен, да упра́виши до́брі со́бранноє їм ста́до Христо́во; ти же вма́лі начальствовав, па́ки управляєм восхоті́л єси́ би́ти, да приумножиши доброді́телей нетлі́нная сокро́вища. Ті́мже, див'я́щеся ре́вностному добротолюбію і смиренному́дрію твоєму́, вопіє́м ті:","Ра́дуйся, лише́нії тіле́сними мно́га бла́га духо́вная собра́вий;","ра́дуйся, нището́ю дарова́нія Небе́сная стяжа́вий.","Ра́дуйся, молча́нія ізря́дний храни́телю;","ра́дуйся, стро́гий уста́вов і́ночеських блюсти́телю.","Ра́дуйся, боля́щим, я́ко бра́тії Христо́вой, послужи́вий;","ра́дуйся, висо́кий о́браз любве́ сино́внія яви́вий.","Ра́дуйся, вла́сті над други́ми і че́сти уклони́вийся;","ра́дуйся, па́ки, я́ко слуга́ незна́єм, во оби́тель Кириллову всели́вийся.","Ра́дуйся, та́мо бра́шна уготовля́ти опреділе́нний;","ра́дуйся, і в ру́бищі рабстем познанний і обличе́нний.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 6","ps":["Купцю́ уподо́бился єси́, і́щущему до́браго би́сера, Іо́сифе преподо́бне, єгда́ в послуша́нії і вся́цім по́двизі духо́внім благоїску́сен бив, оби́телі і́ночеськия посещал єси́: да іспи́тно позна́єши в тіх лу́чшая і соверше́ннійшая і приусвоїши на по́льзу душ стада́ твоєго́ слове́снаго, є́же ра́достію ве́лією возра́довася возвраще́нію твоєму́, благода́рственні взива́я Пастиренача́льнику Христу́: Аллилу́я."]},{"h":"Ікос 6","ps":["Сли́шав благові́рний князь Бори́с о прише́ствії преподо́бнаго Іо́сифа в єго́ преді́ли, ізше́д усе́рдно моля́ше і, да ізбере́ть в єго́ наслі́дії мі́сто, да соградить на нем святу́ю оби́тель і пребива́єть в ней со і́ноки, є́же і сверши́ся, диха́нію бу́рну указующу мі́сто, і устройся раче́нієм кня́зя, па́че же благослове́нієм Бо́жиїм по моли́твам преподо́бнаго, єму́же с любо́вію взива́єм си́це:","Ра́дуйся, висо́ких по́двигов житія́ христия́нськаго ревни́телю;","ра́дуйся, новонача́льних іску́сний руководи́телю.","Ра́дуйся, неізмі́нноє пра́вило поста́ і покая́нія;","ра́дуйся, храни́телю непреста́ннаго воздержа́нія.","Ра́дуйся, мирськи́м наста́вниче жи́зні богоуго́дния;","ра́дуйся, основа́телю оби́телі благоплодния.","Ра́дуйся, я́ко блага́я начина́нія твоя́ Христо́с благослови́;","ра́дуйся, я́ко сотрудника тебі́ в ли́ці держа́внаго яви́.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 7","ps":["Ве́ліє стяжа́в сокро́вище любве́, преподо́бне, я́коже во дні пе́рвих христия́н, і́мже бі се́рдце і душа́ єди́на і от ни́хже нікто́же от імі́ній глаго́лаше что своє́ би́ти, суди́л єси́ і во і́ноціх оби́телі твоєя́, я́ко ізволе́нієм се́рдця отве́ргшихся ми́ра і єго́ стяжа́ній, уста́вити сицева́го жи́тельства о́браз, да всі вку́пі єди́но взи́щуть стяжа́ніє ві́чноє, Бо́га, Єму́же і да взива́ють ви́ну: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго Феодо́сія, о́бщих житі́й нача́льника, зрить в тебі́ страна́ Россі́йськая, преподо́бне о́тче Іо́сифе, я́коже бо той, і́ночеськия обі́ти восприя́в, всім се́рдцем і душе́ю уста́вом о́бщаго і́ночеськаго житія́ пре́дан бя́ше, си́це і ти, сим ше́ствуяй путе́м, в терпі́нії мно́зі за́повідем общежи́тія святи́х оте́ць неукло́нно послі́довал єси́, ті́мже от чту́щих тя сли́шиши такова́я:","Ра́дуйся, о́бщеє житіє́ мона́шествующих основа́вий;","ра́дуйся, тім всеору́жіє благоче́стія їм пода́вий.","Ра́дуйся, о́бщими труди́ пра́здних помисло́в шата́нія упраздни́вий;","ра́дуйся, ті́ми, я́ко броне́ю, страсте́й разжже́нния стрі́ли отрази́вий.","Ра́дуйся, всели́вий во оби́телі дух о́бщаго воздержа́нія;","ра́дуйся, потреби́вий в ней пле́вели любостяжа́нія.","Ра́дуйся, бодрствованію духо́вному мно́гі і́ноки научи́вий;","ра́дуйся, до конця́ житія́ пе́рвий в тружда́ющихся би́вий.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нник прише́л єси́ в пусти́ню оте́чествія твоєго́, преподо́бне, і а́біє домовлади́ка яви́лся єси́ Бо́гу, преклоньшу се́рдце во вла́сті су́щаго благові́рнаго кня́зя Бори́са є́же послужи́ти от імі́ній свої́х на созида́ніє це́ркве ка́менния на мі́сті сем, благоукрасити же ю боголі́пно, і ке́ллії воздви́гнути множащимся бра́тіям, да і зді си́ми, я́ко на небесі́ святи́ми А́нгели, возно́ситься Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Ви́дяще ревностноє по Бо́зі і жесто́коє житіє́ преподо́бнаго Іо́сифа і бра́тії, непреста́нно в труді́х і поще́нії подвиза́ющихся і ходя́щих в рубищних і худи́х оде́ждах, ні́циї от і́нок і вся́каго чи́на мирськи́х люде́й і князе́й не то́чію сих не отвраща́хуся, но па́че равностію духо́вною горя́ще і во оби́телі ку́пно с ни́ми подвиза́тися жела́юще, приноша́ху ту імі́нія своя́ на по́льзу о́бщую; ті́мже здателю той возглаша́єм та́ко:","Ра́дуйся, му́дре предначертавий оби́тель но́ву;","ра́дуйся, поревнова́вий нищетолюбному житію́ Христо́ву.","Ра́дуйся, святи́я хра́ми во оби́телі создивий;","ра́дуйся, мног собо́р мона́шествующих собра́вий.","Ра́дуйся, я́ко труд твой сви́ше благослови́ся;","ра́дуйся, я́ко свято́є жела́ніє се́рдця твоєго́ соверши́ся.","Ра́дуйся, я́ко во оби́телі твоє́й мно́зі душі́ своя́ спасо́ша;","ра́дуйся, я́ко із нея́ пастиренача́льници ізидо́ша.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 9","ps":["Всім се́рдцем возлюби́вий Бо́га і мно́га дарова́нія духо́вная от Него́ восприє́мий, преподо́бне Іо́сифе, і пред челові́ки толи́ку благода́ть обрі́л єси́, я́ко не то́чію мно́зі от прости́х, но і кня́зі, тре́бующе твої́х наставле́ній, в послуша́ніє тебі́ вдаяху себі́ соверше́нно, і́мже миротво́рець бил єси́, ісхода́тайствовав благоволе́ніє самоде́ржця кня́зю Юрію, і́же неповинне оклевета́н под стра́хом сме́ртним бя́ше, ізба́влен же бив в ра́дості душе́вній возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Благода́ть Боже́ственная, привлекаємая моли́твами преподо́бнаго, я́ві зна́менася в нем дарова́нії чудотворе́ній і ві́дінієм сокрове́нних: уме́рша бо благочести́ваго кня́зя Іоа́нна моли́твою своє́ю возбуди́, да коне́чні предуготовиться покая́нієм і воспри́йметь зало́г жи́зні ві́чния, і та́ко да отидеть ко Го́споду; ті́мже во грісі́х живу́щії і ді́йственнаго возбужде́нія на покая́ніє тре́бующії возопії́м к нему́:","Ра́дуйся, благочести́вих отра́до і утіше́ніє;","ра́дуйся, коле́блющихся во ві́рі тве́рдоє огражде́ніє.","Ра́дуйся, отчаявающихся утвержда́яй во упова́нії;","ра́дуйся, просвіти́вий мно́гих твої́ми писа́нії.","Ра́дуйся, мир посреді́ вражду́ющих устроя́яй;","ра́дуйся, непови́нния от сме́рти ізбавля́яй.","Ра́дуйся, умира́ющия возставля́яй на покая́ніє:","ра́дуйся, всім внушаяй жи́зні ві́чния взиска́ніє.","Ра́дуйся, ше́ствовавий путе́м тру́дним і ті́сним;","ра́дуйся, возводя́й други́х к оби́телем небе́сним.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 10","ps":["Новоустроєнну оби́тель преподо́бнаго Іо́сифа іспита́ Госпо́дь посіще́нієм гні́ва Своєго́, ку́пно же і ми́лости: за гріхи́ бо людські́я глад крі́пок наведе́ на зе́млю Волоколамську і на вся окре́стния ві́си, я́ко мно́гим лю́дем безго́дно погиба́ти. Преподо́бний же, уві́дів сія́, усугу́би во оби́телі моле́ніє і отве́рзе жи́тници тоя́ алчущим; разда́в же вся су́щая і не моги́й ктому́ не то́чію ти́сящ прише́дшаго наро́да, но ніже́ бра́тії своєя́ препита́ти, посла́ заімовати на оби́тель сребро́ і ку́плю ді́яй сі́мен хлебних, ніка́коже оста́ви требующия погиба́ти гла́дом, ді́тем же їх ма́лим осо́б созда́ дом, до́ндеже держа́вний благочести́вий цар Васи́лій, сли́шав сія́, внеза́пу при́йде во оби́тель і дарова́ дово́льная ко призрі́нію бі́дствующих, і́же, ви́дяще в сем милосердующую ру́ку Бо́жию, во умиле́нії серде́ць вознесо́ша хвалебний глас Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Благо́му ізволе́нію держа́внаго послі́дующе, мно́зі от воєнача́льник і князе́й удельних і іни́х христолю́бцев бога́тая дая́нія в оби́тель Іо́сифову приноша́ху, я́ко всім пришедшим к ней гла́да ра́ди безбі́дно в до́ми своя́ возврати́тися і но́вим ізоби́лієм благослови́тися оби́телі преподо́бнаго, к нему́же взива́єм ни́ні:","Ра́дуйся, наде́ждо сві́тлая в ну́жді і обстоя́нії су́щих;","ра́дуйся, покрови́телю си́рих і кро́ва неіму́щих.","Ра́дуйся, гла́дом погиба́ющих пита́телю;","ра́дуйся, ча́дом їх виталища созидателю.","Ра́дуйся, ми́лости істо́чниче неістощи́мий;","ра́дуйся, скорб'я́щих уті́шителю незри́мий.","Ра́дуйся, послі́дняя твоя́ взаї́м Бо́гові да́вий;","ра́дуйся, до́брим расточе́нієм су́щих бога́тая собра́вий.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 11","ps":["Ві́дий от Боже́ственних писа́ній, я́ко єди́н упова́ющий на Го́спода пожене́ть ти́сящи, і два дви́гнета тьми, не убоя́лся єси́, преподо́бне, єди́н со святи́м Генна́дієм со́нмищу си́льних побо́рников су́єтних лжеуче́ній противуста́ти; і ору́жієм і́стини в коне́ць сих порази́л єси́: всі бо разсі́яшася, я́ко прах пред лице́м ві́тра, тебі́ же благода́рственно се́рдцем і усти́ взива́ющу: Аллилу́я."]},{"h":"Ікос 11","ps":["Ві́руяй в М'я,— рече́ Госпо́дь,— ріки́ от чре́ва єго́ істеку́ть води́ жи́ви. Сія́ у́бо в тебі́ оправдишася, досточу́дне Іо́сифе, не бо свяще́нним догма́том богосло́вія во учи́лищі ні́коєм наста́влен бил єси́, но сам живо́ю ві́рою се́рдця взиску́яй Бо́га, і́стину обрі́л єси́ в сло́ві Бо́жії і писа́ніїх оте́чеських і яви́лся єси́ опло́т необори́м Правосла́вія. Ті́мже взива́єм ті:","Ра́дуйся, лжеучи́телей злих лука́вство разори́вий;","ра́дуйся, сомня́щихся в правосла́вній ві́рі утверди́вий.","Ра́дуйся, бо́дрий уче́нія Христо́ва защи́тниче;","ра́дуйся, боголюби́вою ре́вностію возжже́нний світи́льниче.","Ра́дуйся, благопотре́бне во оте́чествії твоє́м возсія́вий;","ра́дуйся, ві́ру в ді́ліх житія́ твоєго́ показа́вий.","Ра́дуйся, разу́мних і препростих благоїску́сний учи́телю;","ра́дуйся, бли́жніх і да́льних россіян просвіти́телю.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 12","ps":["Ми́ру водвори́вшуся в Це́ркві дух зло́би па́ки, па́кості ді́я, подви́гну се́рдце во́лоцькаго владетеля кори́сти ра́ди мно́га смуще́нія і утісне́нія твори́ти оби́телі, єще́ же і осужде́ніє непра́ведно воздви́гнути на преподо́бнаго, є́же і паде́ на главу́ осуди́вшаго; собо́ром бо свяще́нним преподо́бний Іо́сиф с вели́кою че́стію оправда́н бисть, при́сно воспіва́яй Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Тече́ніє житія́ скончава́я в труді́х і моли́твах, і по́двизіх благоче́стія, завіща́ преподо́бний неізмі́нно храни́ти пре́данний їм уста́в знамена́тельні прире́к: а́ще получу́ от Бо́га ми́лость, то оби́тель сія́ ничи́мже скудна́ бу́деть, і та́ко, заві́су пло́ті отложи́в, оти́де ко Го́споду і по сих ісціле́нія подава́ше больни́м, приходящим с моли́твою к єго́ моще́м. Сего́ ра́ди прино́сим єму́ похвале́нія такова́я:","Ра́дуйся, чистоти́ душе́вния храни́телю нелицемі́рний;","ра́дуйся, і́стинний ра́бе Христо́в благи́й і ві́рний.","Ра́дуйся, стріла́ми вра́жиїх наві́т неуязвимий;","ра́дуйся, спаса́ємих вождю́ непобіди́мий.","Ра́дуйся, досточу́дний о́бразе терпі́нія;","ра́дуйся, наста́вниче неле́стнаго благогові́нія.","Ра́дуйся, і по отше́ствії оби́тель твою́ соблюда́яй;","ра́дуйся, молящимся благопотре́бная подава́яй.","Ра́дуйся, от Го́спода віне́ць пра́вди восприя́вий;","ра́дуйся, сла́вою чудотворе́ній просія́вий.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 13","ps":["О, преподо́бне і богоно́сне о́тче Іо́сифе! Воспомина́юще ни́ні по́двиги і труди́ твоя́, я́же о Христі́ соді́янная, ми, грі́шнії і недосто́йнії раби́ твої́, смире́нно про́сим тя: моли́ ми́лостиваго Бо́га, да да́руєть мир жи́тельству на́шему і Це́ркві Своє́й Святі́й, да огради́ть ю от всіх душепа́губних і безбо́жних уче́ній, да пода́сть же нам вся благопотре́бная в житії́ сем, і в бу́дущем ві́ці да сподо́бит нас воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела во пло́ті тя ві́дуще, преподо́бне Іо́сифе, по́сланна от Бо́га, да яви́ть тобо́ю в челові́ціх о́браз і́стиннаго благоче́стія і до́брих діл, чудя́щеся путе́м Єго́, во вре́меннім житії́ твоє́м явле́нним, і вели́чіє благоутро́бія Єго́ прославля́юще, во умиле́нії серде́чнім взива́єм ті си́це:","Ра́дуйся, до́браго ко́рене о́трасле благоро́дная;","ра́дуйся, лозо́ виногра́да Христо́ва многопло́дная.","Ра́дуйся, ча́до моли́тви роди́телей благочести́вих;","ра́дуйся, наде́ждо і утіше́ніє серде́ць їх боголюби́вих.","Ра́дуйся, ізді́тська страх Госпо́день стяжа́вий;","ра́дуйся, сі́м'я сло́ва Бо́жия от ю́ности восприя́вий.","Ра́дуйся, ізмла́да смире́нія і молча́нія храни́телю;","ра́дуйся, моли́тви і воздержа́нія ревни́телю.","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і ди́вний благоче́стія подви́жниче, преподо́бне о́тче Іо́сифе, і́же сугу́бий сви́ше дар приє́мий богові́дінія же і ісціле́ній, я́ко імі́яй дерзнове́ніє ко Святі́й Тро́йці моли́ ізба́витися нам от находя́щих бід і скорбе́й і болі́зней, да любо́вію зове́м ті:","Ра́дуйся, преподо́бне о́тче Іо́сифе, богому́дре, чудотво́рче."]},{"h":"Молитва","ps":["О, преблаже́нне і присносла́вне о́тче наш Іо́сифе! Ві́дуще твоє́ ве́ліє к Бо́гу дерзнове́ніє і к твоєму́ тве́рдому заступле́нію прибіга́юще, в сокруше́нії се́рдця мо́лим тя: озари́ нас сві́том дарова́нния тебі́ благода́ті і моли́твами твої́ми помози́ нам бу́рноє мо́ре житія́ сего́ прейти́ безм'яте́жно і приста́нища спасе́нія небла́зненно дости́гнути: порабоще́ни бо су́ще су́єтними, і гріхолюби́ви, і не́мощни є́же от обише́дших нас зол возни́кнути, ко кому́ прибі́гнем, а́ще не к тебі́, яви́вшему неоскудіва́ємоє бога́тство ми́лости в земні́м житії́ твоє́м? Ві́руєм же, я́ко і по отше́ствії твоє́м мно́жайшеє стяжа́л єси́ дарова́ніє милосе́рдовати бе́дствующим. Ті́мже у́бо, припа́дающе ни́ні к цільбоно́сній іко́ні твоє́й, умиле́нно про́сим тя, свя́тче Бо́жий: сам іскуше́н бив, помози́ і нам, іскуша́ємим; посто́м і бді́нієм попра́вий си́лу де́монськую, і нас от нападе́ній вра́жиїх защити́; препита́вий гла́дом погиба́ющих, і нам іспроси́ у Го́спода ізоби́ліє плодо́в земни́х і вся я́же ко спасе́нію потре́бная; посрами́вий єрети́чеськая мудрова́нія, Це́рков Святу́ю от єресе́й і раско́лов, і смуще́ній моли́твами твої́ми огради́: да то́жде му́дрствуєм всі, єди́нім се́рдцем сла́в'яще Святу́ю, Єдиносу́щную, Животворя́щую і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во вся ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О, вели́кий наста́вниче, ревни́телю і учи́телю Правосла́вния ві́ри, свя́те прему́дре Іо́сифе! Прийми́ моле́ніє нас, грі́шних, тебі́ приноси́моє, і те́плим предста́тельством умоли́ в Тро́йці сла́вимаго Бо́га, да ниспосле́ть бога́тия Своя́ ми́лости нам, грі́шним, да утверди́ть во Свято́й Своє́й Правосла́вній Це́ркві пра́вую ві́ру і благоче́стіє: па́стирем єя́ да пода́сть святу́ю ре́вность о спасе́нії слове́снаго ста́да, я́ко да ві́рующих соблюду́ть, неві́рующих же і отпа́дших от і́стинния ві́ри вразум'я́ть і обратя́ть. Нам же всім іспроси́ вся благопотре́бная во вре́меннім сем житії́ і поле́зная к ві́чному спасе́нію на́шему. Пом'яни́ ста́до твоє́, є́же собра́л єси́, не забу́ди посіща́ти чад твої́х і, я́ко чадолюби́вий оте́ць, не пре́зри, ніже́ отри́ни моле́нія на́ша, но воздіжи́ ру́ці твої́ моли́твеннеї ко Го́споду Бо́гу, да отложи́ть пра́ведний гнів Свой, дви́жимий на ни, і ізба́вить нас от враг ви́димих і неви́димих, от гла́да, пото́па, меча́, смертоно́сния я́зви, наше́ствія іноплеме́нних і междоусо́бния бра́ні. Єй, премилосе́рдий засту́пниче наш, пресла́вний чудотво́рче, всіх нас упра́ви в ми́рі і покая́нії сконча́ти живо́т наш і пресели́тися со упова́нієм в блаже́нная селе́нія ра́йськая, іді́же непреста́нно славосло́виться всепі́тоє і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Я́ко по́стников удобре́ніє і отце́в красоту́, / ми́лости пода́теля, разсужде́нія світи́льника, / всі ві́рнії соше́дшеся восхва́лим, / кро́тости учи́теля, і єресе́й посрами́теля, / прему́драго Іо́сифа, Россі́йськую звізду́, / моля́щася Го́споду, // поми́ловатися душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Житія́ треволне́нія і м'яте́ж мирськи́й, / і стра́стная взигра́нія в нічто́же вміни́в, / пусти́нний граждани́н показа́лся єси́, / мно́гих бив наста́вник, Іо́сифе преподо́бне, / мона́хов собра́тель, і моле́бник ві́рен, / чистоти́ рачи́тель. // Моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Іо́сифе, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Мартирію Зеленецькому","e":"Akathist to our Venerable Father Martyrius of Zelenets","secs":[{"h":"Кондак 1","ps":["Ізбра́нниче благода́ті Бо́жієй, преподо́бне о́тче наш Марти́ріє, от ю́ности твоєя́ Христа́ возлюби́л єси́ і Тому́ невозвра́тно послі́довал єси́. Оби́тель Зелене́цькую созда́в, в той мно́гія к спасе́нії упра́вил єси́. Чудеси́ украси́вся в житії́, в масти́тій ста́рости преста́вился єси́ і, днесь на Небесі́х лику́юще ви́ну мо́лишися за ни. Ми же, сві́тло па́м'ять то́ю пра́зднующе, та́ко тя велича́єм:","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Ікос 1","ps":["А́нгели і Арха́нгели і вся Во́їнства Небе́сная Христа́ пі́сньми превозно́сять. Сим же і ду́хи пра́ведник соверше́нних сликовству́ють, в їх же лице́ тя зря́ще, та́ко хва́лим досто́йно, на́шего засту́пника:","Ра́дуйся, от ю́ности Небе́снаго оте́чествія взиска́вий;","ра́дуйся, вся ми́ра сего́ кра́сная ні во что же вміни́вий.","Ра́дуйся, Христо́ві єди́ному послужи́вий;","ра́дуйся, сего́ ра́ди крест житія́ і́ночеськаго приє́мий.","Ра́дуйся, оби́тель Зелене́цькую устро́ївий;","ра́дуйся, созда́вий і́ноком вита́лище безпеча́льноє.","Ра́дуйся, бра́тії ра́ди мно́гі труди́ претерпі́вий;","ра́дуйся, єще́ в житії́ чудеси́ от Бо́га просла́вленний.","Ра́дуйся, царе́вича от сме́ртнаго одра́ воздви́гнувий;","ра́дуйся, в житії́ явле́нія Ма́тере Бо́жия удосто́єнний.","Ра́дуйся, ли́ку пра́ведних вчине́нний.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 2","ps":["Ви́діл єси́, преподо́бне Марти́ріє, смерть роди́телей твої́х, і от сего́ єще́ в мла́дости позна́л єси́, я́ко стра́нники і прише́льці єсьми́ в юдо́лі сей земно́й. Мо́ре же жите́йськоє зря напа́стей, бу́рею воздвиза́ємоє, к ти́хому приста́нищу устреми́лся єси́. В це́рков бо, я́ко в кора́бль, прите́кл єси́ і Небе́сним Ко́рмчим Христо́м в селе́нія го́рняя упра́влен бил єси́, іді́же днесь ра́достно вопіє́ши Бо́гові: Аллилу́я!"]},{"h":"Ікос 2","ps":["Уразумі́л єси́ путі́ спаси́тельния, о́тче наш Марти́ріє, єгда́, ієре́я Благове́щенськия це́ркве Бори́са посіща́я, поуче́ніям єго́ внима́л єси́. І, тому́ послі́довав, во Великолу́цькую оби́тель Се́ргієву пресели́лся єси́ і вся і́ночеськаго житія́ тяготи́ поне́сл єси́. Ті́мже та́ко ті рцем:","Ра́дуйся, Вели́ких Лук проізраста́ніє ди́вноє;","ра́дуйся, сирото́, сохране́нноє Бо́гом от напа́стей вся́чеських.","Ра́дуйся, я́ко посла́ ті Госпо́дь роди́теля но́ва ієре́я пра́ведна;","ра́дуйся, я́ко любо́вію той благо́му і́гу Христо́ву тя покори́.","Ра́дуйся, сла́дці послу́шавий того́ от писа́нія назида́нія;","ра́дуйся, ча́сто входи́вий в храм Благові́щенія Пречи́стия.","Ра́дуйся, моли́твою та́мо умудря́вийся;","ра́дуйся, прия́тієм Пречи́стих Та́їн укрепля́вийся.","Ра́дуйся, про́чеє дня проводи́вий в труді́х вся́чеських;","ра́дуйся, целому́дріє душе́вноє і тіле́сноє неруши́мо соблюди́й.","Ра́дуйся, досто́йно на по́двиг і́ночеськаго житія́ вше́дий во оби́тель Великолу́цькую.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жієй снабдева́єм, седьм літ со наста́вником твої́м преби́л єси́, преподо́бне, і́же мно́гим поле́зним тя научи́. Найпа́че же уча́ше боля́щих поско́ру Святи́х Та́їн сподобля́ти, зане́ по сме́рті той душе́, я́ко несу́щей свята́я, де́мони ніка́коже мо́гуть каса́тися, а́нгели же ю сріта́ють с пі́снію: Аллилу́я!"]},{"h":"Ікос 3","ps":["Імі́ній не стяжа́в, стяжа́л єси́ му́дрость жи́зні по Бо́зі, преподо́бне Марти́ріє, я́ко бо сі́м'я, в зе́млю вмета́ємо, но́ви кла́си возраща́єть, та́ко і поуче́нія наста́вника твоєго́ би́ша душі́ твоє́й сі́менем жи́зні ві́чния. Сего́ ра́ди тя ублажа́єм:","Ра́дуйся, послуша́нієм украси́вийся;","ра́дуйся, посто́м істончи́вий пло́ті стра́стная.","Ра́дуйся, препобіжда́вий сон моли́твенним бді́нієм;","ра́дуйся, трудо́м земледі́лія укріпи́вий си́ли своя́.","Ра́дуйся, послужи́вий больни́м во враче́бниці;","ра́дуйся, омива́вий стру́пи гно́йния і я́зви неісці́льния.","Ра́дуйся, поскорбе́вий с скорб'я́щими;","ра́дуйся, немощни́х ропта́нія кро́тці понеси́й.","Ра́дуйся, за́повідь Христо́ву дія́нієм соверши́вий;","ра́дуйся, ми́лостиве, я́ко ві́чноє поми́лованіє стяжа́л єси́.","Ра́дуйся, та́ко себі́ предугото́вавий к постриже́нію і́ночеському.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 4","ps":["Бу́ря гріхо́вная мно́гі лю́ди погуби́. Оба́че си́лою благода́ті Христо́ви мно́зі спасе́ніє улуча́ють, живу́ще благоче́стне, мона́си і мирсті́ї. Ки́йждо приє́млеть, є́же по мі́рі сил обріта́єть, ов о ча́діх спаса́ється, ов же і́ночестії приє́млеть обі́ти і Бо́гові денноно́щно поє́ть піснь серафи́мськую: Аллилу́я!"]},{"h":"Ікос 4","ps":["Сли́шав Ісу́са Христа́, ре́кша о і́ночестім житії́: «моги́й вмісти́ти, да вмісти́ть», і зря себі́ к о́ному прикло́нна, усе́рдно моли́л єси́, преподо́бне, наста́вника, да жела́ніє твоє́ освяти́ть і укріпи́ть постриже́нієм, є́же і получи́л єси́. Ті́мже тебе́ вопіє́м:","Ра́дуйся, я́ко остри́гл єси́ власи́ глави́ твоєя́ в зна́меніє мироотрече́нія;","ра́дуйся, я́ко обле́клся єси́ в хито́н во́льния нищети́.","Ра́дуйся, приє́мий ря́су а́ки оде́жду весе́лія;","ра́дуйся, препоя́савий бедра́ свої́ я́ко си́лою і́стини.","Ра́дуйся, ма́нтією, а́ки броне́ю пра́вди, оді́явийся;","ра́дуйся, покри́вий главу́ свою́ покрива́лом смире́нія.","Ра́дуйся, с одія́нієм санда́лій не скор би́вий на творе́ніє во́лі своєя́;","ра́дуйся, глаго́лом Бо́жиїм, а́ки мече́м вооружи́вийся во всегда́шней моли́тві Ісу́совой.","Ра́дуйся, крест, щит ві́ри приї́м, с любо́вію облобиза́вий і;","ра́дуйся, свіщу́ взем, свіще́ю благоче́стія яви́вийся посліди́.","Ра́дуйся, прия́тий во во́їнства проти́ву ми́ра, пло́ті і дия́вола.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ дре́вле приведе́ мудреці́ восто́чния к я́слем Вифлеє́мським, іді́же ті́ї обріто́ша Царя́ ца́рствующих і Го́спода госпо́дствующих. Та́ко і тя, преподо́бне Марти́ріє, путь і́ночеськаго житія́ приведе́ посліди́ в селе́нія го́рняя, іді́же рожде́нному от Ді́ви ви́ну прино́ситься спасе́нними піснь вели́кая і хвале́бная: Аллилу́я!"]},{"h":"Ікос 5","ps":["Врагу́, при́сно на пусти́нних муже́й страхова́нії мно́гими напа́дающу, житіє́м моли́твенним противуста́л єси́, преподо́бне, і жесто́ким страсте́й умерщвле́нієм. Ми же, чудя́щеся твоєму́ терпі́нію бра́ні, от того́ воздви́гнутия, умиле́нно поє́м ті хвали́:","Ра́дуйся, до́брі преуспі́вий в і́ночеських по́двизіх;","ра́дуйся, пусти́ннаго жи́тельства возжелі́вий зіло́.","Ра́дуйся, моли́твою на сіє́ Бо́жия благослове́нія проси́вий;","ра́дуйся, удосто́ївийся явле́нія преподо́бнаго Михаї́ла Кло́пськаго.","Ра́дуйся, я́ко той благослови́ твоє́ ізволе́ніє;","ра́дуйся, за шестьдеся́т по́прищ от оби́телі нача́вий пусти́нноє жи́тельство.","Ра́дуйся, я́ко ве́лію брань воздвиго́ша проти́ву тя зді злі́ї де́мони;","ра́дуйся, я́ко мно́жицею во́пльми во вре́м'я полу́нощі устраша́ху тя.","Ра́дуйся, ізби́ти мня́ще, нічто́же ті зло сотвори́ти можа́ху;","ра́дуйся, я́ко прогоня́л єси́ я моли́твою, а́ки пла́менним мече́м.","Ра́дуйся, си́лою креста́ Христо́ва посрами́вий си́лу вра́жию.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 6","ps":["Пропові́дниче благоче́стія, єгда́ узрі́л єси́, преподо́бне Марти́ріє, о́браз Влади́чиці на́шея Богоро́диці в столпі́ о́гненні і сві́тлі в страні́ Ти́хфинстій, зіло́ умили́лся єси́ Бо́жию к себі́ милосе́рдію. Єгда́ же в град Смоле́нск богомоле́нія ра́ди вшел єси́, яви́шася ті преподо́бнії Авраа́мій і Єфре́м і па́ки пусти́нноє ті прореко́ша житіє́, сла́дці воспі́л єси́: Аллилу́я!"]},{"h":"Ікос 6","ps":["Возсія́ благода́ть Бо́жія в оби́телі Ти́хфинстій, єгда́ та́мо пожи́л єси́ с ученико́м свої́м Авраа́мієм, і́же і сподо́бися зрі́ти крест зве́зден, назнамену́ющ мі́сто твоєя́ оби́телі. Ті́мже ті рцем та́ко:","Ра́дуйся, на Го́спода возложи́вий все своє́ упова́ніє;","ра́дуйся, ісше́дий на поклоне́ніє святи́м моще́м преподо́бних Авраа́мія і Єфре́ма.","Ра́дуйся, преподо́бне, преподо́бних собесі́дниче;","ра́дуйся, незри́мий днесь споспі́шниче ко святи́м місто́м ше́ствующим.","Ра́дуйся, прише́дий на поклоне́ніє іко́ні Богома́тері Ти́хфинстій;","ра́дуйся, я́ко та́мо доброді́тельним житіє́м просія́л єси́.","Ра́дуйся, ключехрани́телю, отверза́вий і затворя́вий две́рі храмо́вния;","ра́дуйся, днесь вводя́й во врата́ Небе́сния моли́твою за немощну́ю бра́тію.","Ра́дуйся, просла́вивий прия́вшую тя оби́тель равноа́нгельним житіє́м;","ра́дуйся, ізше́дий із тоя́ на по́двиг устроє́нія но́вия.","Ра́дуйся, возжеги́й світи́льник во спасе́ніє немощни́м.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 7","ps":["Хотя́й єди́н Бо́гові моли́тися і би́ти в безмо́лвії, отше́л єси́, преподо́бне, в мі́сто, над ним же Авраа́мій крест ви́ді зве́зден, і обрі́л єси́ то́є, я́ко о́стров зе́лен посреді́ вод бла́тних, ліс же, а́ки страж нощни́й, поко́й єго́ от прише́ствія мирськи́х люде́й храня́ше. Вельми́ ті любе́зна обрі́теся пусти́ня сія́ прегорча́йшая, ю́же ви́дящи, умиле́нно воспі́л єси́: Аллилу́я!"]},{"h":"Ікос 7","ps":["Но́вая купі́ль Силоа́мськая бисть ті, преподо́бне, Зелене́цькая пу́стинь, в той бо от немощни́х і стра́стних єстества́ очи́стил єси́ себе́ бді́нієм і посто́м і ді́ланієм духо́вним, і уго́ден Го́сподеві яви́лся єси́, сего́ ра́ди і ми та́ко ублажа́єм:","Ра́дуйся, обріти́й мі́сто, ті Бо́гом на вселе́ніє угото́ванноє;","ра́дуйся, не убоя́вийся пусти́ннаго одино́чества.","Ра́дуйся, па́м'ятовавий, я́ко с тобо́ю бі при́сно Госпо́дь;","ра́дуйся, я́ко Ілия́ на Карми́лі, моли́лся єси́ ту.","Ра́дуйся, я́ко Іоа́нн в Іорда́нськой пусти́не посто́м украси́лся єси́;","ра́дуйся, ревни́телю преподо́бних Ону́фрія, Мака́рія і Анто́нія, вели́ких отце́в.","Ра́дуйся, проразумі́вий а́біє би́вшую кознь дия́вола;","ра́дуйся, предреки́й приве́дшу тя му́жеві Іо́сифу дще́ри смерть дия́волим ухищре́нієм би́вшую.","Ра́дуйся, откри́вий, я́ко уто́пшая ли́ку му́ченичу причте́ся Бо́жієй ми́лостью;","ра́дуйся, вола́ поги́бша во ві́твіх древе́сних дия́вольським кознова́нієм об'яви́вий тому́жде.","Ра́дуйся, та́ко от уни́нія му́жа благогові́йна спаси́й.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці єсьми́ на землі́ сей, преподо́бне, при́сно ни враг іскуша́єть, стра́сті возмуща́я, уни́ніє вселя́я, і мно́гі поставля́єть препо́ни теку́щим по путі́ в го́рній Ієрусали́м. А́ще же что і бла́го сотвори́м бли́жнему, тщи́ться, да поги́бнеть мзда, скорбми́ а́біє нам отмсти́ти. Бог же сія́ терпи́ть, я́коже дре́вле І́овле поруга́ніє, да вя́щшеє дасть утіше́ніє посліди́ пою́щим: Аллилу́я!"]},{"h":"Ікос 8","ps":["Всяк в житії́ крест скорбе́й і печа́лей, єго́же кому́ даде́ Госпо́дь, прено́сить, і а́ще в уни́ніє не впаде́ть, посліди́ сугу́бо прославля́ється. Та́ко і ти, о́тче, вся претерпі́в, ми́лостей Госпо́дніх сподо́бился єси́, сего́ ра́ди тя ублажа́єм:","Ра́дуйся, ізнача́ла согради́вий часо́вницю і ма́лу хи́жину;","ра́дуйся, ту сла́дці денноно́щно моли́вийся Бо́гові.","Ра́дуйся, Христа́ ра́ди претерпі́вий зной і мра́зи мно́гіє;","ра́дуйся, пита́вийся, я́же то́чію ті приноша́ху окре́стнії.","Ра́дуйся, вско́рі уті́шенний виді́нієм о́гненна столпа́ с руко́ю, і́скри размета́ющею;","ра́дуйся, я́ко сія́ зна́менаше оби́ліє благода́ті, от тебе́ ісходи́ти іму́щия ко бра́тії.","Ра́дуйся, світи́льниче, єго́же позна́ша вско́рі ві́рнії;","ра́дуйся, я́ко не отгна́л єси́ жа́ждавших с тобо́ю пожи́ти.","Ра́дуйся, я́ко прийма́л єси́ от ми́ра к тебі́ притека́ющих;","ра́дуйся, па́стирю слове́сних ове́ць.","Ра́дуйся, послужи́вий немощно́му челові́честву до сконча́нія живота́.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 9","ps":["Всего́ себе́ прине́сл єси́ в же́ртву, Бо́гові уго́дную. Мно́гіє труди́, ско́рби і печа́лі поне́сл єси́, устроя́я оби́тель і служа́ще бра́тії, і́же от язв мирськи́я суєти́ му́дре в чистоту́ житія́ богоуго́днаго влекл єси́, словеса́ і дія́нія моли́твою укріпля́яй. Два же хра́ма і ке́ллії согради́л і оби́тель стіно́ю древ'я́ною огради́л єси́, да я́коже во вертогра́ді цвіти́ істоча́ють благоуха́нія, і́ноці зді уго́дне Бо́гові пою́ть: Аллилу́я!"]},{"h":"Ікос 9","ps":["Ві́твми дре́во благосінноли́ственноє прикрива́єть мно́гія, і ти, преподо́бне, мно́гія прикри́л єси́ от наві́тов вра́жиїх і мо́ря жите́йськаго бур. Мно́зі бо к тебі́ притеко́ша во оби́тель Зелене́цькую, ї́хже ра́ди ігу́менства сан многопопечи́тельний і свяще́нство прия́л єси́ і в ца́рствующий град потре́бних ра́ди оби́телі пешеше́ствовал єси́. Сего́ ра́ди ублажа́єм тя:","Ра́дуйся, світи́льниче, осія́вий те́мную страну́;","ра́дуйся, созда́телю хра́мов, в ни́хже і́м'я Бо́жиє прославля́ється.","Ра́дуйся, а́ки сокро́вище ве́ліє внеси́й в о́ния святи́я іко́ни, от настоя́теля ті пре́жде вда́нния;","ра́дуйся, посто́м, слеза́ми і моли́твою созда́вий основа́ніє оби́телі непоколеби́моє.","Ра́дуйся, благоче́стієм привлеки́й мно́гіє щедрода́телі;","ра́дуйся, к тебі́ бо, я́ко пчела́ ко у́лію, приноша́ху боголю́бці сокро́вища своя́.","Ра́дуйся, ві́роваху бо, я́ко та́ко творя́ще, взаї́м даю́ть Бо́гові;","ра́дуйся, я́ко єди́н благи́й Фео́дор согради́ ті вся потре́бная.","Ра́дуйся, поуча́яй, я́ко оби́телей лі́пота моли́твою і́ноков стяжава́ється;","ра́дуйся, я́ко за добро́, ті да́нноє, моли́лся усе́рдно сам і вся бра́тія твоя́.","Ра́дуйся, о́бразе і́стиннаго і́ночеськаго житія́.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 10","ps":["Спаси́тельния ми́лости сподо́бился єси́, преподо́бне о́тче Марти́ріє: єди́ножди по моли́тві ма́ло усну́вшу ті, узрі́л єси́ Ма́тер Бо́жию. В діви́чем о́бразе бі Пречи́стая, умиле́нна лице́м і прекра́сна, бровми́ черна́. На главі́ бя́ше злати́й віне́ць, от ка́меній многоці́нних світя́щий зіло́. Ти же, Ю узрі́в, с слеза́ми умиле́нія преклони́вся, воспі́л єси́: Аллилу́я!"]},{"h":"Ікос 10","ps":["Стіна́ ті неруши́мая бисть, преподо́бне, іко́на Ти́хфинськая, є́юже благослови́ тя настоя́тель, єгда́ в Зелене́цький ото́к отхожда́л єси́. Єгда́ же Пречи́стую зрі́ти удосто́їлся єси́, а́біє неви́димій би́вшей, на іко́ну сію́ воззрі́л єси́ і позна́в єси́, я́ко в подо́бії тоя́ іко́ни бі Влади́чиця: я́же пом'яту́ющи, та́ко ті рцем:","Ра́дуйся, і́стинний Пречи́стия святи́х іко́н чти́телю;","ра́дуйся, і́стиннаго святи́х іко́н почита́нія научи́телю.","Ра́дуйся, Пречи́стия Влади́чиці лик, слеза́ми іспо́лненний і прекра́сний ви́діти удосто́єнний;","ра́дуйся, я́ко келе́йния іко́ни твої́ і днесь осіня́ють гроб твой.","Ра́дуйся, я́ко покланя́ющеся їм, честь не дре́ву, но на нем ізображе́нним воздає́м;","ра́дуйся, я́ко не дскам і ва́пам, но напи́санному Божеству́ на них поклоне́ніє прино́сим.","Ра́дуйся, я́ко ли́ки святи́х і твой лобиза́юще, а́ки но́зі ва́ша лобиза́єм;","ра́дуйся, я́ко фимія́мом моли́тву на́шу зна́менуєм.","Ра́дуйся, свіщи́ возжига́юще, о сві́ті, в нем же Бог живе́ть, па́м'ятуєм;","ра́дуйся, я́ко от іко́н твої́х ісхо́дить си́ла ціле́бная.","Ра́дуйся, я́ко возложе́нієм їх, ме́ртва воскреси́ Госпо́дь.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 11","ps":["Пі́сні надгро́бния і послі́днєє цілова́ніє смени́ся пі́нієм хвале́бним ми́лости Бо́жієй і слеза́ми ра́дости, єгда́, в Москву́ ті ше́ствующу, во Тве́рі, у царя́ Симео́на си́на Іоа́нна воскреси́л єси́ моли́твою і святи́х іко́н твої́х возложе́ніє по си́лі благода́ті Христо́ви, ті да́нния. Сего́ ра́ди зіло́ возлюби́ Симео́н оби́тель твою́, преподо́бне, і три но́ви хра́ми ту согради́, да о чудеси́ сем ви́ну Бо́гові возно́ситься піснь хвале́бная: Аллилу́я!"]},{"h":"Ікос 11","ps":["Я́ко світи́льника тя благоче́стія почита́ющий цар Симео́н мно́го потре́бними оби́тель твою́ снабді́. Єгда́ же сконча́лся єси́, преподо́бне, чтий вельми́ па́м'ять твою́ святи́тель Корни́лій, Новугра́ду влади́ка му́дрий, зіло́ возлюби́ і преукраси́, іді́же і мі́сто упокоє́нія сі ізбра́. Я́же пом'яту́юще і оби́тель твою́ ра́ди ві́ри і терпі́нія укра́шену ви́дящи, та́ко тебі́ вопіє́м:","Ра́дуйся, іска́телю ца́рствія Бо́жия, єму́же вся земна́я приложи́шася;","ра́дуйся, я́ко оби́тель твоя́ потре́бними не оскуді́.","Ра́дуйся, я́ко треми́ хра́ми, я́ко купі́ль треми́ свіща́ми осія́ся сія́;","ра́дуйся, я́ко неду́жнії душе́ю ту оздравля́хуся.","Ра́дуйся, я́ко ца́ріє і прості́ї, бога́тії і убо́зії, посіща́юще ю, во спасе́ніє назида́хуся;","ра́дуйся, я́ко уме́ршаго о́трока в утіше́ніє роди́телема воскреси́л єси́.","Ра́дуйся, я́ко тім си́лу благода́ті Бо́жия яви́л єси́;","ра́дуйся, науча́яй тім, я́ко в Бо́зі живо́т наш і смерть скончава́ються.","Ра́дуйся, пропові́дниче Бо́жия всемогу́щества;","ра́дуйся, благода́ті сосу́де преіспо́лненний.","Ра́дуйся, от гро́ба твоєго́ істоча́яй многообра́зная ісціле́нія.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 12","ps":["Благода́ті Бо́жієй ізбра́нниче, преподо́бне о́тче наш Марти́ріє, єгда́ состарі́лся єси́ і оста́ви тя крі́пость твоя́, сам рука́ма свої́ма мі́сто упокоє́нія і гроб соді́лал єси́. Прови́дя же кончи́ну свою́, до́брі поуча́л єси́ бра́тію твою́, є́же жи́ти і досто́йно пі́ти ви́ну Бо́гові: Аллилу́я!"]},{"h":"Ікос 12","ps":["Поє́м твоя́ ми́лості і чудеса́, преподо́бне о́тче наш Марти́ріє, ви́ну бо і по преставле́нії твоє́м нас не оставля́єши і моли́твами твої́ми у Го́спода потре́бная, я́же к животу́ і благоче́стію, ісхода́тайствуєши, єгда́ тя с ві́рою і любо́вію призива́єм, і мо́лишися, во є́же спасти́ся всім. Сего́ ра́ди от благода́рних серде́ць ті вопіє́м усе́рдно:","Ра́дуйся, моли́твенниче наш усе́рдний;","ра́дуйся, помо́щниче наш ско́рий.","Ра́дуйся, мир всім правосла́вним пред кончи́ною твоє́ю завеща́вий;","ра́дуйся, о ми́рі всего́ ми́ра незри́мий хода́таю.","Ра́дуйся, на су́ші і в мо́рі от всіх оста́вленним по́мощ подава́яй;","ра́дуйся, неду́гующих от сме́ртнаго одра́ к жи́зні возвраща́яй.","Ра́дуйся, всіх душе́вних і тіле́сних неду́гов врачу́;","ра́дуйся, от злих духо́в му́чимих ізба́вителю.","Ра́дуйся, ско́рбних се́рдце незри́моє умиротворе́ніє;","ра́дуйся, покро́ве к тебі́ притека́ющих.","Ра́дуйся, о спасе́нії всіх те́плий моли́твенниче.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 13","ps":["О, преподо́бне і богоно́сне о́тче наш Марти́ріє. Прийми́ ма́лоє со умиле́нієм ті приноси́моє на́ми моле́ніє сіє́, і со Пречи́стою Ма́терію Го́спода і всі́ми святи́ми моли́ся Го́споду Ісу́су Христу́, да ізба́вить нас от вся́ких бід і скорбе́й, от враг ви́димих і неви́димих, от напра́сния сме́рти і бу́дущих мук, і сподо́бит со ізбра́нними Єго́ воспіва́ти Тро́йці Святі́й во ві́ки: Аллилу́я!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели і Арха́нгели і вся Во́їнства Небе́сная Христа́ пі́сньми превозно́сять. Сим же і ду́хи пра́ведник соверше́нних сликовству́ють, в їх же лице́ тя зря́ще, та́ко хва́лим досто́йно, на́шего засту́пника:","Ра́дуйся, от ю́ности Небе́снаго оте́чествія взиска́вий;","ра́дуйся, вся ми́ра сего́ кра́сная ні во что же вміни́вий.","Ра́дуйся, Христо́ві єди́ному послужи́вий;","ра́дуйся, сего́ ра́ди крест житія́ і́ночеськаго приє́мий.","Ра́дуйся, оби́тель Зелене́цькую устро́ївий;","ра́дуйся, созда́вий і́ноком вита́лище безпеча́льноє.","Ра́дуйся, бра́тії ра́ди мно́гі труди́ претерпі́вий;","ра́дуйся, єще́ в житії́ чудеси́ от Бо́га просла́вленний.","Ра́дуйся, царе́вича от сме́ртнаго одра́ воздви́гнувий;","ра́дуйся, в житії́ явле́нія Ма́тере Бо́жия удосто́єнний.","Ра́дуйся, ли́ку пра́ведних вчине́нний.","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Кондак 1","ps":["Ізбра́нниче благода́ті Бо́жієй, преподо́бне о́тче наш Марти́ріє, от ю́ности твоєя́ Христа́ возлюби́л єси́ і Тому́ невозвра́тно послі́довал єси́. Оби́тель Зелене́цькую созда́в, в той мно́гія к спасе́нії упра́вил єси́. Чудеси́ украси́вся в житії́, в масти́тій ста́рости преста́вился єси́ і, днесь на Небесі́х лику́юще ви́ну мо́лишися за ни. Ми же, сві́тло па́м'ять то́ю пра́зднующе, та́ко тя велича́єм:","Ра́дуйся, Марти́ріє, ско́рий наш помо́щниче, Зелене́цький чудотво́рче!"]},{"h":"Молитва","ps":["О, па́стирю до́брий, наста́вниче наш, преподо́бне о́тче Марти́ріє! Усли́ши є́же к тебі́ ни́ні приноси́моє моле́ніє на́ше. Ві́ми бо, я́ко ду́хом с на́ми пребива́єши. Ти у́бо, преподо́бне, я́ко імі́я дерзнове́ніє ко Влади́ці Ісу́су Христу́, Бо́гу на́шему, і к Пречи́стій Богома́тері, бу́ди хода́тай і моли́твенник те́плий о оби́телі сей, ю́же возгради́л єси́, і о нас, недосто́йних рабі́х, живу́щих в ней,– єя́же ти просвіти́тель сий і нача́льник, богособра́нному твоєму́ бра́тству помо́щник і засту́пник при́сно явля́єшися,– я́ко да твої́м предста́тельством і моли́твами невреди́ми на мі́сті сем пребу́дем: от бісо́в же і злих челові́к ненаве́тованни от всіх бід і напа́стей свобо́дні сохрані́мся. Всім же отовсю́ду приходя́щим во святу́ю оби́тель твою́, і моля́щимся тебі́ с ві́рою, і поклоня́ющимся ра́ці моще́й твої́х, о є́же ізба́витися от вся́кия ско́рби, болі́зні і напа́сти, ми́лостивне поспіши́,– дарова́ти же правосла́вним мир, тишину́, благоде́нствіє і ізоби́ліє плодо́в земни́х. І о всіх нас те́плий предста́тель ко Го́споду і помо́щник душа́м на́шим бу́ди, є́же отпусти́тися нам согріше́ніям на́шим і моли́твами твої́ми, свя́те, ізба́витися нам ві́чнаго муче́нія і сподо́битися Ца́рствія со всі́ми святи́ми, да сла́ву, благодаре́ніє і поклоне́ніє возсила́єм Єди́ному Бо́гу, в Тро́йці сла́вимому, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 2","ps":["От ю́ности, Богоблаже́нне, Христа́ возлюби́в, / оте́чество оста́вил єси́ / і, всіх мирськи́х м'яте́жей уклони́вся, / в ти́хоє приста́нище пречестни́я оби́телі Богома́терни дости́гл єси́; / отню́дуже уві́дів непрохо́дную пусти́ню, / крестови́дною заре́ю пока́занную, / жела́тельні ю обрі́л єси́, / і, в ней всели́вся, / і́ночествующих собра́л єси́, / і сих уче́ньми свої́ми, я́ко лі́ствицею восхо́дною на Не́бо, / трудолю́бно тща́лся єси́ возводи́ти к Бо́гу, / Єму́же моли́ся, Богому́дре Марти́ріє, // дарова́ти душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Оте́чества, преподо́бне, і всего́ мирська́го м'яте́жа уклони́тися возжелі́л єси́, / і, в пусти́ню всели́вся, / та́мо во блаже́ннім безмо́лвії жесто́коє житіє́ показа́л єси́, / і ча́да послуша́нія і смире́нія в нем возрасти́л єси́. / Сего́ ра́ди, дерзнове́ніє стяжа́в ко Святі́й Тро́йці, / є́же моли́тися, Богоблаже́нне, о нас, ча́діх свої́х, ї́хже собра́л єси́, / і о всіх правові́рних, да зове́м ті: // ра́дуйся, о́тче Марти́ріє, безмо́лвія пусти́ннаго люби́тель."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Марти́ріє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Харитону Сповіднику","e":"Akathist to our Venerable Father Chariton the Confessor","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий і чудотво́рче, пресві́тлий Фаранськия пусти́ні світи́льниче, велича́я просла́вльшаго тя Го́спода, благода́рственноє пі́ніє прино́сим ті, чту́ще святу́ю па́м'ять твою́. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Святі́й Тро́йці, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті яви́лся єси́, преподо́бне Харито́не, да яви́ши собо́ю о́браз і́стиннаго благоче́стія і до́брих діл. Ми же, чудя́щеся неізследимим путе́м Госпо́днім, на тебі́ явле́нним, і прославля́я ве́ліє благоутро́біє Бо́жиє, во умиле́нії серде́чнім воспіва́єм ті:","Ра́дуйся, Го́сподеві порабо́тати пла́менні вожделі́вий.","Ра́дуйся, Єго́ єди́наго па́че всего́ возлюби́вий.","Ра́дуйся, благо́є і́го Христо́во на ра́мена своя́ взе́мий.","Ра́дуйся, сі́м'я сло́ва Бо́жия в се́рдці своє́м всі́явий.","Ра́дуйся, ві́ри Правосла́вния і благоче́стія ревни́телю.","Ра́дуйся, моли́тви, поста́ і воздержа́нія храни́телю.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 2","ps":["Ви́дя Го́спода пред собо́ю ви́ну і на ми́лость Єго́ упова́я, во благоче́стії преуспі́л єси́, о́тче Харито́не, доброді́тельми християнськими ду́шу свою́ обогаща́я і і́стинним іспові́дником і́мені Христо́ва себі́ явля́я, непреста́нно вопія́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом і́стиннаго богопозна́нія сви́ше руководи́мий, о́тче преподо́бне, положи́л єси́ в се́рдці твоє́м за Христо́м неукло́нно слі́довати і во всем ісполня́ти во́лю Єго́. Ті́мже, усе́рдіє твоє́ похваля́юще, взива́єм си́це:","Ра́дуйся, пло́ті мудрова́ніє умертви́вий.","Ра́дуйся, терпі́нієм твої́м зло́бу ми́ра сего́ побіди́вий.","Ра́дуйся, во́їне Христо́в добропобі́дний.","Ра́дуйся, Небе́снаго Влади́ки ра́бе благи́й і ві́рний.","Ра́дуйся, я́ко в ра́дость Го́спода твоєго́ вшел єси́.","Ра́дуйся, я́ко со святи́ми му́чениками і преподо́бними водвори́лся єси́.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 3","ps":["Си́ла Боже́ственния любве́, є́юже от ю́ности іспо́лнено бисть се́рдце твоє́, богому́дре Харито́не, та́ко укріпи́ тя во благоче́стії, я́ко ві́ру і́стинную пред всі́ми іспові́дуя і муче́нія же́стокая претерпіва́я, ніколи́же всп'ять обрати́лся єси́, ра́достно воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці своє́м тве́рдую ві́ру во Христа́ Бо́га, не убоя́лся єси́, свя́те Харито́не, гні́ва нечести́ваго Авреліяна, оба́че, презрі́в сла́ву ми́ра сего́, іспові́дал єси́ себе́ християни́на би́ти; сего́ ра́ди от него́ біє́нія претерпі́в, я́ко злоді́й, в темни́цю всажде́н бил єси́. Таково́му твоєму́ дерзнове́нію і му́жеству див'я́щеся, глаго́лем ті си́це:","Ра́дуйся, іспові́дниче Христо́в неустраши́мий.","Ра́дуйся, сто́лпе правові́рія несокруши́мий.","Ра́дуйся, за і́м'я Христо́во неща́дно бієнний.","Ра́дуйся, за Го́спода твоєго́ в темни́ці заключе́нний.","Ра́дуйся, Єго́ ра́ди муки́ жесточайшия претерпі́вий.","Ра́дуйся, віне́ць побі́дний от Него́ прия́вий.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 4","ps":["Бу́ря страда́ній лю́тих не поколеба́ тя, о́тче Харито́не, єгда́ іге́мон но́вия преще́нія на тя воздви́же; ти же, на ка́мені ві́ри Христо́ви тве́рдо стоя́, со дерзнове́нієм глаго́лал єси́: «Аз во І́стиннаго Бо́га ві́рую і Єму́ то́кмо служу́ і покланя́юся, я́ко Той єсть Созда́тель всего́, Спас ми́ра, пребива́ющий во ві́ки, Єму́же А́нгели на Небесі́ вопію́ть: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́шаще тве́рдоє іспові́даніє твоє́, страстоте́рпче Христо́в, і ви́дяще ран твої́х ісціле́ніє, яряшеся мучи́тель і предаде́ тя на жесточайшия муки́, повеліва́я ті́ло твоє́ свіща́ми опаля́ти; ти же тверд я́ко адама́нт пребива́я, Го́спода, во страда́ніях тя укріпля́ющаго, славосло́вил єси́. Сіє́ твоє́ пачеєсте́ственноє терпі́ніє благогові́йно воспомина́юще, взива́єм си́це:","Ра́дуйся, Го́сподем чуде́сно от ран ісцеленний.","Ра́дуйся, к ли́ку святи́х іспові́дников сопричтенний.","Ра́дуйся, Христо́вих страсте́й і́стинний прича́стниче.","Ра́дуйся, Пресвяти́я Тро́йці пла́менний іспові́дниче.","Ра́дуйся, благода́тію Тоя́ я́ко броне́ю защищенний.","Ра́дуйся, огне́м страда́ній я́ко зла́то очище́нний.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 5","ps":["Боготе́чною стезе́ю к ти́хому приста́нищу спасе́нія устреми́вся, преподо́бне, єгда́ із темни́чнаго заключе́нія ізведе́н бил єси́ і стопи́ твоя́ во Святи́й Град Ієрусали́м направи́л єси́, воспіва́я Пострада́вшему за род челові́чеський: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша тя разбо́йници лю́тії, о́тче Харито́не, во Святи́й Град путь соверша́юща, уми́слиша сме́рті преда́ти тя: сего́ ра́ди, связа́вше тя, в пеще́рі затвори́ша, но по ма́лі вре́мені са́мі от я́да змії́на погибо́ша. Ти же, Го́споду за чу́дноє спасе́ніє твоє́ хвалу́ возда́в, пеще́ру разбойничу в храм Бо́жий претвори́л єси́ і с бра́тією, пришедшею вслід тебі́, Созда́теля вся́чеських в нем славосло́вил єси́. Сего́ ра́ди воспіва́єм ті:","Ра́дуйся, себе́ і весь живо́т твой Го́сподеві преда́вий.","Ра́дуйся, все упова́ніє своє́ на Бо́га полага́вий.","Ра́дуйся, покорним себі́ во́лі Бо́жієй сотвори́вий.","Ра́дуйся, го́рнєє любому́дріє возлюби́вий.","Ра́дуйся, я́ко вся любе́зная і кра́сная ми́ра сего́ презрі́л єси́.","Ра́дуйся, я́ко небе́сних і нетлі́нних жела́нієм вожделі́л єси́.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 6","ps":["Пропові́дником нищелю́бія яви́лся єси́, о́тче преподо́бне, єгда́ все бога́тство, єго́же разбо́йници непра́ведно стяжа́ша, на по́льзу о́бщую обрати́л єси́, нищія і а́лчущия пита́я і оби́тель і́ночеськую в пусти́ні Фаранстей созида́я. Ті́мже помина́юще по́двиги і труди́ твоя́, во сла́ву Бо́га Ви́шняго под'ятия, воспіва́єм Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ я́ко со́лнце пресві́тлоє в пусти́ні Фаранстей, о́тче Харито́не, і сія́нієм по́двигов твої́х привле́кл єси́ во оби́тель твою́ мно́гі ревни́тели богоугожде́нія і́стиннаго, і́же стека́хуся к тебі́ отвсю́ду, да руково́дствуєши їх ко спасе́нію. Ті́мже у́бо і ми, тобо́ю наставля́ємі, ублажа́єм тя і зове́м:","Ра́дуйся, а́вво богому́дрий, і́ноков мно́жество собра́вий.","Ра́дуйся, послуша́ніє бра́тії твоє́й законоположи́вий.","Ра́дуйся, селе́ніє Ду́ха Свята́го в себі́ показа́вий.","Ра́дуйся, пост і воздержа́ніє я́ко сладча́йшую снідь возлюби́вий.","Ра́дуйся, милосе́рдіє і братолю́біє чу́дноє яви́вий.","Ра́дуйся, приме́ром богоуго́днаго житія́ твоєго́ всіх поучавий.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 7","ps":["Хоті́ніє імі́л єси́, преподо́бне, в безмо́лвії пребива́ти: сего́ ра́ди удали́лся єси́ в мі́сто безлюдноє, іді́же в по́двизіх пустинножи́тельства до́брі подвиза́лся єси́. Оба́че, содержа́ во умі́ сло́во Госпо́днє: «Гряду́щаго ко Мні не ізжену́ вон», нікого́же отри́нул єси́ от приходя́щих к тебі́, но всіх оте́чеськи наставля́л єси́, за вся благодаря́ Христа́ і воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя наста́вника і́ночествующих разумі́єм, о́тче Харито́не: мно́зі бо прихожда́ху к тебі́, благослове́нія ра́ди і доброді́тельнаго житія́; ти же всіх с любо́вію прийма́л єси́, поуча́я от Боже́ственнаго Писа́нія, є́же твори́ти за́повіді Госпо́дні, храни́ти чистоту́ тіле́сную і імі́ти любо́в нелицемі́рную друг ко дру́гу. Ті́мже благода́рственно вопіє́м ті:","Ра́дуйся, в зако́ні Госпо́дні непоро́чно ходи́вий.","Ра́дуйся, в трезве́нії у́мнім все житіє́ твоє́ проводивий.","Ра́дуйся, стра́хом Госпо́днім вся путі́ своя́ ограждавий.","Ра́дуйся, ученики́ твоя́ нелі́ностно во благоче́стії назида́вий.","Ра́дуйся, Христо́ви слове́сния о́вці ко спасе́нію подвиза́яй.","Ра́дуйся, неради́вия от сна гріхо́внаго возбужда́яй.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 8","ps":["Странника і прише́льця в ми́рі сем помишля́я себі́ би́ти, преподо́бне, о часі́ сме́ртнім непреста́нно пам'ятовал єси́; ті́мже оби́телі Ієрихонськую і Сукійськую хотя́щим спасти́ся устро́їв, в пеще́ру, безмо́лвія ра́ди, всели́лся єси́, іді́же дні і нощі́ в моли́тві і по́двизіх пребива́я, воспіва́л єси́ Сладча́йшему Ісу́су: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, о́тче Харито́не, о Бо́зі і благоугожде́нії Єму́ со ученики́ твої́ми бесі́довал єси́, со слеза́ми умоля́я їх вся за́повіді Христо́ви ві́рно храни́ти. Ті́мже, я́ко возше́дий на висоту́ соверше́нства духо́внаго, наставля́й і нас по путі́ спасе́нія, да і ми тебі́ поє́м:","Ра́дуйся, узок путь в Ца́рствіє Небе́сноє ізбра́вий.","Ра́дуйся, пустинничества по́двиг во́лею под'явий.","Ра́дуйся, Христа́ Бо́га в се́рдці твоє́м вмісти́вий.","Ра́дуйся, і́м'я Єго́ спаси́тельноє во умі́ своє́м носи́вий.","Ра́дуйся, моли́твенную сла́дость се́рдцем твої́м позна́вий.","Ра́дуйся, слез благода́тних пото́к умили́тельний істочавий.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся вели́кому сви́ше тебі́ дарова́нію, богоблаже́нне Харито́не, ти бо на землі́ невеще́ственноє житіє́ показа́л єси́, і во пло́ті, а́ки безпло́тен, яви́лся єси́ і дар чудотворе́нія от Го́спода прия́л єси́. Ни́ні же, Того́ бла́гостію к Небе́сним причте́н єси́ Си́лам, в Небесі́х поє́ши Всеси́льному Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не довлі́ють ізглаго́лати вся по́двиги і страда́нія твоя́, о́тче Харито́не, і́бо добро́та житія́ твоєго́ воі́стину превосхо́дить похвалу́ челові́чеськую. Оба́че ми, любо́вію к тебі́ побіжда́ємі, дерза́єм смиренному́дренно благохвали́ти тя пі́нієм такови́м:","Ра́дуйся, я́ко Святі́й Тро́йці ни́ні ра́достно предстої́ши.","Ра́дуйся, я́ко о спасеніїї на́шем Бо́га умоля́єши.","Ра́дуйся, христия́нському ро́ду при́сноє утіше́ніє.","Ра́дуйся, лю́б'ящим і чту́щим тя хода́таю спасе́нія.","Ра́дуйся, приводя́й грі́шних ко ісправле́нію.","Ра́дуйся, те́плий о всем ми́рі предста́телю.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 10","ps":["Спасе́нія по́двиг до́брі соверши́вши, житія́ же вре́меннаго отріша́яся і отходя́ к животу́ ві́чному і блаже́нному, Харито́не преподо́бне, утіша́л єси́ ученики́ твоя́, глаго́ля: «Пеци́теся о спасе́нії своє́м, я́ко да ізбі́гнув сіте́й вра́жиїх, сподо́бітеся по кончи́ні своє́й Го́спода усрі́сти і ми́лость от Него́ получи́ти, воспіва́я со ізбра́нними: Аллилу́я»."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв твої́х, уго́дниче Христо́в, огради́ нас от вся́каго душевре́днаго іскуше́нія дия́вольськаго, я́ко тебі́ дарова́ нам Преблаги́й Бог в по́мощ і защи́ту душа́м і тілесе́м на́шим. Тебе́ у́бо про́сим: помози́ нам во вся́кой ско́рби і обстоя́нії, си́це тебі́ вопію́щим:","Ра́дуйся, я́ко свя́то і пра́ведно на землі́ пожи́л єси́.","Ра́дуйся, я́ко воі́стину а́нгел земни́й і челові́к небе́сний бил єси́.","Ра́дуйся, я́ко отверзо́шася тебі́ врата́ ра́йськия.","Ра́дуйся, я́ко ду́шу твою́ Госпо́дь прия́т в Небе́сния оби́телі.","Ра́дуйся, дерзнове́ніє моли́твенноє ко Го́споду стяжа́вий.","Ра́дуйся, по кончи́ні твоє́й чад твої́х не оста́вивий.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приноша́ху тебі́ духо́вная ча́да твоя́ по чу́днім твоє́м, о́тче, к Бо́гу отше́ствії, с пла́чем ве́ліїм провожда́юще тя на мі́сто упокоє́нія в пе́рвую оби́тель твою́: сле́зи мно́гія о разлуче́нії твоє́м пролива́ху, со воздиха́нієм вопію́ще псало́мськую піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная звізда́ яви́лся єси́, богоно́се Харито́не, не́бо церко́вноє украша́ющая і мрак де́монський дале́че отгоня́ющая; ті́мже і на́ша се́рдця, омраче́нная гріхми́, просвіти́ і к сві́ту покая́нія возведи́, да зове́м ті:","Ра́дуйся, свіще́, Боже́ственним огне́м пламені́ющая.","Ра́дуйся, денни́це, ві́рних душі́ і се́рдця просвіща́ющая.","Ра́дуйся, благоче́стію прибіга́ющих к тебі́ науча́яй.","Ра́дуйся, уз гріхо́вних моля́щихся тебі́ свобожда́яй.","Ра́дуйся, смиренному́дрія іску́сний наста́вниче.","Ра́дуйся, і́ноком в бра́ні духо́вній помо́щниче.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 12","ps":["Благода́ть Пресвята́го Ду́ха іспроси́ нам, преподо́бне Харито́не, у Всеще́драго Бо́га, вразумля́ющую і укріпля́ющую ни во спасе́ніє, да уклоня́ющеся от путе́й нече́стія і заблужде́ній, хо́дим во сві́ті за́повідей Бо́жиїх, воспіва́юще а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще сла́вноє житіє́ твоє́, страда́нія і по́двиги, ублажа́єм тя, о́тче Харито́не, я́ко уго́дника Бо́жия преподо́бнаго і іспові́дника пресла́внаго. Ти же, Бо́гу предстоя́, при́сно помина́й нас, любо́вію соверша́ющих па́м'ять твою́ і во смире́нії зову́щих ті такова́я:","Ра́дуйся, чту́щих тя наста́вниче благода́тний.","Ра́дуйся, притека́ющих к тебі́ покрови́телю благонаде́жний.","Ра́дуйся, я́ко воздвиза́ємих от ми́ра, пло́ті і дия́вола іскуше́ній хода́тайством твої́м нас свобожда́єши.","Ра́дуйся, я́ко нераска́янних грі́шников к соверше́нному покая́нію побужда́єши.","Ра́дуйся, духо́в лука́вих прогони́телю і по́лчищ бісо́вських побіди́телю.","Ра́дуйся, ран гріхо́вних і неду́гов душе́вних всеблаги́й ціли́телю.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 13","ps":["О, преподо́бне і богоно́сне о́тче Харито́не, прийми́ сіє́ ма́лоє, от лю́б'ящих серде́ць приноси́моє тебі́ хвале́ніє і, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, моли́ся за ни, да благоприя́тним твої́м хода́тайством ізба́влени бу́дем от вся́каго іскуше́нія проти́внаго і, богоуго́дні зді на землі́ пожи́вше, сподо́бимся ви́ну на Небесі́ воспіва́ти со бесплотними піснь Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті яви́лся єси́, преподо́бне Харито́не, да яви́ши собо́ю о́браз і́стиннаго благоче́стія і до́брих діл. Ми же, чудя́щеся неізследимим путе́м Госпо́днім, на тебі́ явле́нним, і прославля́я ве́ліє благоутро́біє Бо́жиє, во умиле́нії серде́чнім воспіва́єм ті:","Ра́дуйся, Го́сподеві порабо́тати пла́менні вожделі́вий.","Ра́дуйся, Єго́ єди́наго па́че всего́ возлюби́вий.","Ра́дуйся, благо́є і́го Христо́во на ра́мена своя́ взе́мий.","Ра́дуйся, сі́м'я сло́ва Бо́жия в се́рдці своє́м всі́явий.","Ра́дуйся, ві́ри Правосла́вния і благоче́стія ревни́телю.","Ра́дуйся, моли́тви, поста́ і воздержа́нія храни́телю.","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий і чудотво́рче, пресві́тлий Фаранськия пусти́ні світи́льниче, велича́я просла́вльшаго тя Го́спода, благода́рственноє пі́ніє прино́сим ті, чту́ще святу́ю па́м'ять твою́. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Святі́й Тро́йці, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, преподо́бне о́тче Харито́не, мона́шествующих похвало́ і утвержде́ніє."]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Харито́не! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́, не премолчи́ за ни ко Го́споду, і не пре́зри нас, недосто́йних, ві́рою і любо́вію чту́щих тя. Помина́й нас у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва, а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх, і вся́кия пре́лести бісо́вськия, і ко́зней дия́вольських, па́стирю наш до́брий. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́в, возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Слез твої́х тече́ньми пусти́ні безпло́дноє возді́лал єси́, / і і́же із глубини́ воздиха́ньми во сто трудо́в уплодоноси́л єси́, / і бил єси́ світи́льник вселе́нния, / сія́я чудеси́, Харито́не о́тче наш. // Моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Наслади́вся, богому́дре, воздержа́нія, / і пло́ті твоєя́ вожделі́нія обузда́в, / яви́лся єси́ ві́рою возраща́єм, / і я́ко жи́зні дре́во посреді́ рая́ процві́л єси́, // Харито́не всеблаже́нне, свяще́ннійший."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Харито́не, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Михаїлу, першому митрополиту Київському","e":"Akathist to St Michael, the first Metropolitan of Kyiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Христа́ Бо́га сосу́д, по́слан бил єси́ в зе́млю Россі́йськую і язи́к наш святи́м креще́нієм просвіти́л єси́ святи́телю о́тче Михаї́ле, ті́мже Влади́ці своєму́ на небесі́ ни́ні предстоя́, тому́ моли́ся прилі́жно, от вся́ких бід і напа́стей ізба́витися ста́ду твоєму́, да зове́м ті:","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Ікос 1","ps":["Арха́нгелов і а́нгелов Цар, і всея́ тва́рі Созда́тель і Промисли́тель, милосе́рдіє Своє́ яви́ к лю́дем страни́ на́шея, во тьмі ідолослуже́нія ходи́вшим, і тя, святи́телю Михаї́ле, я́ко апо́стола посла́, да сія́ просвіти́ши сві́том і́стиннаго богопозна́нія. І се твої́ми уче́ньми, я́же пе́рвіє же́ртви бісо́м приноша́ху, ни́ні ду́ші своя́ дароно́сять Христу́. Тебі́ же благода́рственная сія́ возно́сять піснопі́нія:","Ра́дуйся, ві́ри Христо́ви усе́рдний насади́телю;","ра́дуйся, ідолослуже́ніє іскорени́вий.","Ра́дуйся, бісо́вськия же́ртви упраздни́вий;","ра́дуйся, сві́те, от восто́ка возсія́вий.","Ра́дуйся, тьму ідолобі́сія разгна́вий;","ра́дуйся, уче́нієм Христо́вим лю́ди просвіти́вий.","Ра́дуйся, і́дольськия тре́би кресто́м разруши́вий;","ра́дуйся, ни́ву Христо́ву до́брі возде́лавий.","Ра́дуйся, благопло́дная сі́мена на ней всі́явий;","ра́дуйся, медото́чная уста́ Христо́ва;","Ра́дуйся, свирі́ль благозву́чная Ду́ха Свята́го.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 2","ps":["Ви́діл єси́, святи́телю Михаї́ле, плоди́ трудо́в твоєя́ про́повіді гра́ждане бо сла́внаго гра́да Ки́єва, і́стині твоєго́ уче́нія все́ю душе́ю і се́рдцем вне́млюще, уві́роваша во Христа́ і́стиннаго Бо́га, ме́рських же і́долов отврати́шася і о́вих у́бо сокруша́ху, іни́х же с поруга́нієм в реку́ вмета́ху, в ни́хже бі́си: «О лю́ті нам», вопія́ху. Зря сія́, блаже́нне о́тче, ра́довался єси́ ду́хом твої́м, благода́рно поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богодухнове́нен імі́я, досточу́дне о́тче Михаї́ле, бу́їя лю́ди боже́ственним твої́м уче́нієм до́брі наказа́в, і гла́дом душе́вним та́ющия, єва́нгельським сло́ва хлі́бом напита́в, Христо́ві сія́ приве́л єси́: Єму́ же, святи́телю, моли́ся, о похваля́ющих тя си́це:","Ра́дуйся, Це́ркве красото́;","ра́дуйся, архієре́єв добро́то.","Ра́дуйся, Правосла́вія світи́ло;","ра́дуйся, благоче́стія пра́вило.","Ра́дуйся, люде́й россі́йських вели́кий учи́телю;","ра́дуйся, проро́чествія во апо́століх Первозва́ннаго сла́вний соверши́телю.","Ра́дуйся, ли́ка Богоізбра́ннаго отце́в Пече́рських предстоя́телю;","ра́дуйся, равноапо́столом Кири́ллу і Мефо́дію равностоя́телю.","Ра́дуйся, двана́десять сино́во Влади́мира купі́лію Креще́нія отроди́вий;","ра́дуйся, тім всей землі́ єго́ усе́рдно послужи́вий.","Ра́дуйся, ві́ру Христо́ву распространи́вий;","ра́дуйся, пре́лесть де́монськую низложи́вий.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 3","ps":["Си́лою богоуго́дних моли́тв твої́х, свя́те, пра́отцем на́шим пособи́вий в Єди́наго І́стиннаго Бо́га уві́ровати, ло́жния же бо́ги отри́нути і сокруши́ти, помози́ і нам мла́том доброді́тельнаго житія́ сокруши́ти душе́вния куми́ри на́ші: го́рдость у́бо смире́нієм, сребролю́біє же нестяжа́нієм, блуд цілому́дрієм, гнів кро́тостію, чревоуго́діє воздержа́нієм, за́висть доброжела́нієм, уни́ніє же крі́пким на Бо́га упова́нієм. Да та́ко ізби́вше перу́нов духо́вних, возмо́жем Бо́гу предста́ти, Єму́ же ти, о́тче, научи́л єси́ нас ві́ровати і пі́ти непреста́нно: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи квас ві́ри во Христа́, жена́, богому́драя княги́ня О́льга, о́ний в са́тіх люде́й россі́йських сокри́. Тобо́ю же, по во́лі Всемогу́щаго, все ті́сто держа́ви Влади́мирови сква́сив, возрасте́ во ві́ру Христо́ву. Сего́ ра́ди прийми́ от на́шего усе́рдія досто́йния похвали́ тебі́:","Ра́дуйся, Бо́жиє к Русі́ благоволе́ніє;","ра́дуйся, моли́тв святи́я О́льги ісполне́ніє.","Ра́дуйся, славнодержа́внаго Влади́мира вели́кий советода́телю;","ра́дуйся, новоізбра́нних люде́й Христо́вих му́дрий назида́телю.","Ра́дуйся, і́мже ца́ріє на́ші і всі лю́діє росси́йстії спаса́ються;","ра́дуйся, і́мже архієре́ї на́ші, свяще́нници же і мона́си хва́ляться.","Ра́дуйся, і́мже ни́щії от Бо́га богате́ють і прославля́ються;","ра́дуйся, і́мже претружде́ннії ста́рці чрез ві́ру Христо́ву в раї́ упокоєва́ються.","Ра́дуйся, і́мже младе́нці преста́вившіїся «Оса́нна во ви́шніх» вопію́ть;","ра́дуйся, і́мже душі́ сино́в россі́йських, я́ко і́скри, по сте́блію к небесі́ теку́ть.","Ра́дуйся, землі́ на́шея прекра́сноє благослове́ніє;","ра́дуйся, пресла́внаго гра́да Ки́єва освяще́ніє.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 4","ps":["Бу́рю і́долов сокруша́ющую ощути́вше, бі́си рида́юще вопія́ху: «О лю́ті на́шему окая́нству. Я́ко пре́жде почита́єми от всіх би́хом, ни́ні же поруга́ніє от єди́наго под'є́млем прише́льця, і́же учи́ть челові́ки во Христа́ у́бо ві́ровати, нас же сокруша́ти, Єди́ному Бо́гу пою́ще: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́шим дре́вле от Боже́ственнаго Писа́нія, я́ко падо́ша сті́ни Ієрихо́нськия, Ісу́сом Нави́ном, киво́ту обноси́му: ни́ні же ві́ми, я́ко і́доли падо́ша тебі́, святи́телю Михаї́ле во страну́ Россі́йськую прише́дшу. Ті́мже ми, ча́да твоя́, тобо́ю в пресві́тлую Креще́нія оде́жду оде́яннії, благода́рно восхваля́єм тя си́це зову́ще:","Ра́дуйся, світи́льниче на гора́х Ки́євських сві́тло возсія́вий;","ра́дуйся, із тьми к сві́ту лю́ди приведи́й.","Ра́дуйся, те́рніє многобо́жія весьма́ істреби́вий;","ра́дуйся, теплото́ю любве́ Боже́ственния ду́ші оте́ць на́ших согре́вий.","Ра́дуйся, усти́ твої́ми Христа́ Си́на Бо́жия пропові́давий;","ра́дуйся, о́гненним язи́ком твої́м і́дольськоє нече́стіє обличи́вий.","Ра́дуйся, в Трієди́наго Бо́га ві́ровати отці́ на́ші научи́вий;","ра́дуйся, добропло́дная древеса́ рая́ Ісу́сова насади́вий.","Ра́дуйся, я́ко от тебе́ лю́діє росси́йстії водо́ю благода́ті уми́шася;","ра́дуйся, я́ко тобо́ю душе́вная очеса́ їх во святі́й купі́лі откри́шася.","Ра́дуйся; я́ко тобо́ю, во сла́ву Бо́жию, це́ркві мно́гія созда́шася;","ра́дуйся, я́ко тобо́ю оби́телі і́ноков согради́шася.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 5","ps":["Богосія́ннаго світи́льника тя, Михаї́ле богому́дре, Вели́кий Влади́мир во омраче́нную ідолослуже́нієм Россі́йськую зе́млю приведе́, да і зді твої́м прише́ствієм освятя́ться лю́діє і і́стинния ві́ри позна́нієм вразум'я́ться, правосла́вно і богоуго́дно возноси́ти хвале́бную піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 5","ps":["Сли́шав Патріа́рх Царягра́да, я́ко Влади́мир Креще́ніє свято́є восприя́, і єго́ я́ко святи́телей преднача́льника моля́ше: да му́драго учи́теля в Корсу́нь град пришле́ть і того́ митрополи́та землі́ Росси́йстій поста́вить, возра́довася зіло́ і со освяще́нним собо́ром сові́т сотвори́в, ізбра́ тя, свя́те, сіє́ вели́коє послуша́ніє іспо́лнити. Лю́ди же росси́йстії тя сре́тивше і благогові́йний зрак лиця́ твоєго́ ви́дівше, бесі́ди же твоєя́ сла́дость сли́шавше, глаго́лаху:","Ра́дуйся, благи́й наш наста́вниче;","ра́дуйся, апо́стольськія вла́сті і че́сти преє́мниче.","Ра́дуйся, во архієре́єх сла́вний;","ра́дуйся, во ві́рі вели́кий.","Ра́дуйся, в повелі́ніїх доброразсуди́тельний;","ра́дуйся, в поуче́ніїх пресла́достний.","Ра́дуйся, кро́ткий нра́вом;","ра́дуйся, висо́кий по Бо́зі житіє́м.","Ра́дуйся, пра́вди усе́рдний рачи́телю;","ра́дуйся, непра́вди гро́зний обличи́телю.","Ра́дуйся, я́ко твої́ми моли́твами от ві́чния сме́рти упова́єм ізбіжа́ти;","ра́дуйся, я́ко твої́ми уче́ньми жизнь ві́чную ві́руєм стяжа́ти.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 6","ps":["Пропові́дник Христо́ви ві́ри яви́лся єси́ в Нові́граді, Михаї́ле свяще́нне, в онь же прише́д, і́доли сокруша́я, тре́бища разоря́я, лю́ди крести́л єси́, це́ркві созида́л єси́ і пресві́тери по градо́м і ве́сем поставля́л єси́, братолю́бію і христия́нському житію́ лю́ди поуча́я і увіщева́я, да всі єди́ними усти́ і єди́ним се́рдцем с тобо́ю нави́кнуть Христу́ Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, святи́телю Христо́в, я́ко звізда́ пресві́тлая во Оте́чествії на́шем, і тьму ідолобі́сія сві́том Боже́ственних твої́х уче́ній до конця́ подави́л єси́. Сего́ ра́ди тя, я́ко а́нгела Бо́жия, лю́ди росси́йстії почита́ху зову́ще:","Ра́дуйся, ві́ри на́шея во Христа́ нача́ло;","ра́дуйся, Це́ркве Бо́жія в Русі́ основа́ніє.","Ра́дуйся, ієра́рхом в пропові́данії сло́ва Єва́нгельськаго о́бразе;","ра́дуйся, і́ноком, в путь богоуго́днаго житія́ теку́щим, пра́вило.","Ра́дуйся, пра́ведній жи́зні миря́ном вино́вниче;","ра́дуйся, всім доброді́тельно живу́щим віне́чниче.","Ра́дуйся, чистото́ю ду́шу твою́ украси́вий;","ра́дуйся, путь житія́ вре́меннаго во смире́нії ду́ха препроводи́вий.","Ра́дуйся, ді́ли благи́ми сві́тло просія́вий;","ра́дуйся, премно́гими чудеси́ лю́ди удиви́вий.","Ра́дуйся, я́ко сло́во бла́го о па́стві твоє́й Пастиренача́льнику Христу́ возда́л єси́;","ра́дуйся, я́ко от руку́ Єго́ пра́ведноє воздая́ніє прия́л єси́.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 7","ps":["Хотя́ преблаги́й Бог но́вия лю́ди Себі́ ізбра́ти, пе́рвіє в позна́ніє Боже́ственноє вели́каго во царі́х Влади́мира приведе́, і́же у́мним сія́нієм благода́ті во святі́й купі́лі осві́щшеся, прия́т тя па́стиря ви́шнім открове́нієм, на Русь же овця́м Свої́м, в неві́рії заблу́ждшим, приведе́. Та́же уче́нієм і Креще́нієм во і́м'я Отця́, і Си́на, і Свята́го Ду́ха во воді́ сія́ оми́во во двор Христо́в приве́л єси́. С ни́ми же ни́ні престо́лу Єго́ предстоя́, моли́ся да і нас сподо́бит с тобо́ю на небесі́ приноси́ти піснь Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя апо́стола зрим, архієре́є блаже́нне Михаї́ле, зе́млю Россі́йськую обтека́юща: я́ко дости́гнути тебі́ і ко гра́ду Росто́ву, іді́же люде́й вели́коє мно́жество крести́л єси́ і ві́ровати в Тро́йці Єди́ному Бо́гу научи́л єси́, благоче́стію і благоразу́мію ти́я наказа́в і це́ркві мно́гія воздви́г, пресві́тери же і дия́кони їм поста́вил єси́, і уста́ви благоче́стни тім препо́дал єси́, глаго́лющим тебі́ сицева́я:","Ра́дуйся, благода́тію Креще́нія главу́ Русі́, а́ки дияди́мою увінча́вий;","ра́дуйся, правосла́вієм, а́ки пе́рстнем, зе́млю на́шу Христу́ обручи́вий.","Ра́дуйся, сію́ в благоче́стіє, а́ки в порфи́ру ца́рськую облачи́вий;","ра́дуйся, Єва́нгеліє Христо́во, а́ки гри́вну злату́ю на ви́ю єя́ возложи́вий.","Ра́дуйся, Крест Госпо́день в держа́ву непобіди́мую єй дарова́вий;","ра́дуйся, вся ча́да єя́ правосла́вная Христу́ Го́споду і Пречи́стій Єго́ Ма́тері усинови́вий.","Ра́дуйся, женише́ Це́ркве пресві́тлий;","ра́дуйся, си́не Небе́снаго Отця́ пресла́вний.","Ра́дуйся, о́тче отце́в, велеле́пая красото́;","ра́дуйся, па́стирю па́стирей, всехва́льная добро́то.","Ра́дуйся, і всіх родо́в россі́йських моли́твенниче;","ра́дуйся, небе́сних А́нгелов собесі́дниче.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 8","ps":["Стра́нствующим і блужда́ющим в пусти́ні ідолослуже́нія сино́м россі́йським бил єси́ путево́ждь в зе́млю обітова́нную преподо́бне о́тче Михаї́ле, а́ще і не чети́редесять літ я́коже Мойсе́й, но чети́ре лі́та то́чію лю́ди Ки́євськия страни́ детоводи́л єси́, не ма́нною тлі́нною, но і́стинним хлі́бом с небесе́ сше́дшим сія́ пита́я, і́же єсть Христо́с Госпо́дь. Сему́ у́бо поє́м о тебі́ піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, архіпа́стирю приснопа́м'ятне угожда́ти тому́ при́сно па́ству твою́ поуча́л єси́, чад твоя́ духо́вная і умоля́я нічто́же любві́ Христо́вой предпочита́ти, ми же твої́х чад духо́вних вну́ци, тебі́ глаго́лем си́це:","Ра́дуйся Христа́ Го́спода все́ю душе́ю і се́рдцем возлюби́вий;","ра́дуйся, ві́ровати Єму́ і люби́ти Єго́ і нас научи́вий.","Ра́дуйся, я́ко Бо́гу вельми́ угоди́л єси́;","ра́дуйся, я́ко зако́н Боже́ственний нам препо́дал єси́.","Ра́дуйся, Небе́снаго Влади́ки ра́бе благи́й і ві́рний;","ра́дуйся, да́нний тебі́ тала́нт не сокри́вий, но трудолю́бно умно́живий.","Ра́дуйся, мно́гу ку́плю їм сотвори́вий;","ра́дуйся, похвалу́ ве́лію от Го́спода твоєго́ получи́вий.","Ра́дуйся, под і́го благо́є Христо́во, со смире́нієм ви́ю свою́ подклони́вий;","ра́дуйся, тяготу́ дне і вар, во виногра́ді Єго́ со усе́рдієм под'я́вий.","Ра́дуйся, дина́рія вмі́сто Небе́сноє Ца́рствіє от Христа́ восприя́вий;","ра́дуйся, в ра́йських оби́теліх по труді́х твої́х сла́дці почи́вий.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 9","ps":["Всі лю́діє росси́йстії, пе́рвіє язи́чеським многобо́жієм блужда́вшії, ни́ні же тобо́ю, святи́телю Бо́жий Михаї́ле, до́брі наста́вленнії к Богові́дінію прийдо́ша і во святі́й купі́лі от сліпоти́ разу́мних оче́с ізба́вльшеся, Єди́наго Созда́теля своєго́ прославля́ють, Тому́ воспіва́юще: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть к прославле́нію трудо́в і по́двигов твої́х, духоно́сне о́тче, я́же ти под'я́л єси́: та́ко бо по ві́рі ревнова́л єси́, я́ко і к безбо́жним ага́ряном, к болга́ром і сараци́ном му́жа ні́коєго Ма́рка Фило́софа на про́повідь посла́л і лю́ди ко Христу́ призива́л. Ни́ні же глаго́лем тебі́ си́це:","Ра́дуйся, подо́бно Ілії́ по Го́споді Бо́зі поревнова́вий;","ра́дуйся, о распростране́нії святи́я ві́ри Єго́ мно́го пораде́вий.","Ра́дуйся, во сла́ву Христо́ву потруди́вийся;","ра́дуйся, достопокланя́ємоє і́м'я Єго́ пред язи́ки пронеси́й.","Ра́дуйся, усе́рдієм во уче́нії Христо́ві апо́столом уподо́бивийся;","ра́дуйся, во спасе́нії душ челові́чеських самому́ Христу́ подража́вий.","Ра́дуйся, любве́ Боже́ственния іспо́лненний;","ра́дуйся, сострада́нієм к бли́жнему насище́нний.","Ра́дуйся, гро́ме ка́пища язи́чеськая разруша́яй;","ра́дуйся, тимпа́ні велегла́сний сла́ву Божества́ Христо́ва возвіща́яй.","Ра́дуйся, я́ко дерзнове́ніє ве́ліє ни́ні ко Христу́ і́маши;","ра́дуйся, я́ко престо́лу Єго́ в ра́дості неізрече́нній предстої́ши.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 10","ps":["Спасе́нія лю́дем жела́я і Це́ркві до́браго утвержде́нія, па́стирю наш преблаги́й, потща́лся сей ізря́дно вся устро́їти о росси́йстім пле́мені новоізбра́нних: па́стирі і учи́тели по градо́м поста́вил єси́ і тім ста́до слове́сних ове́ць споручи́в, Пастиренача́льнику Христу́ сца́рствовати сам отше́л єси́ на вели́кий плач і рида́ніє па́ству твою́ і кня́зя Влади́мира подви́гнув, к моще́м твої́м припа́дающих, Бо́гу же жа́лостні зову́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ Бо́га ві́рний раб і служи́тель бил єси́, о́тче наш Михаї́ле, і а́ще о Го́споді сном сме́рти почи́л єси́, оба́че свято́є ті́ло твоє́ тлі́нію бисть неприча́стно, неду́гом же челові́чеським врачева́тельно яви́ся. Ті́мже ра́ці моще́й твої́х предстоя́ще, моли́твенно восхваля́єм тя:","Ра́дуйся, я́ко нетлі́нієм ті́ла твоєго́ на землі́ сві́тиши;","ра́дуйся, я́ко свя́тостію душі́ твоєя́ на небесі́ блиста́єши.","Ра́дуйся, страни́ Россі́йськия пресві́тлоє озаре́ніє;","ра́дуйся, вели́каго хра́ма сего́ преізря́дноє украше́ніє.","Ра́дуйся, гра́да твоєго́ Ки́єва вели́кий засту́пниче;","ра́дуйся, оби́телі Пече́рськия усе́рдний моли́твенниче.","Ра́дуйся, о всіх ча́діх Це́ркве правосла́вния те́плий пред Бо́гом хода́таю;","ра́дуйся, всім призива́ющим тя на по́мощ ско́рий предста́телю.","Ра́дуйся, я́ко богоуго́дним житіє́м твої́м, а́ки со́лнцем пресві́тлим всіх нас просвіща́єши;","ра́дуйся, я́ко апо́стольськими труда́ми твої́ми весь мир удивля́єши.","Ра́дуйся, єго́же ті́ло пречестно́є я́ко кипари́с благово́нний, в Це́ркві Бо́жії благоуха́єть;","ра́дуйся, єго́же душа́ пресвята́я я́ко кедр в раї́ Христо́ві в ра́дості процвіта́єть.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 11","ps":["Пі́нієм хвале́бним велича́єм тя, святи́телю Бо́жий Михаї́ле, і хода́тая у Престо́ла Небе́снаго Влади́ки імі́ти тебі́ ча́єм. Не посрами́ у́бо ві́ри на́шея, па́стирю предо́брий, но прийми́ моли́тви на́ша, я́ко кади́ло благово́нноє, і умоли́ Христа́ да да́руєть і нам доброді́тельні жизнь на́шу сконча́ти і с тобо́ю у Христа́ водвори́тися, да усли́шим глас твой к Нему́ о нас: се аз і ді́ти, я́же мі дал єси́, Го́споди, і к Нему́ с тобо́ю вку́пі воспоє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная луча́ бил єси́, богому́дре о́тче Михаї́ле, во тьмі многобо́жія сідя́щим, путеводя́щая к Со́лнцю Пра́вди Христу́ Бо́гу, Єму́ же моли́ся, во сві́ті за́повідей Єго́ всегда́ нам пребива́ти, ра́достноє пі́ніє тебі́ принося́щим:","Ра́дуйся, світи́льниче Трисія́ннаго Сві́та;","ра́дуйся, заре́ Незаходи́маго Со́лнця.","Ра́дуйся, огню́ і́дольськоє нече́стіє попаля́яй;","ра́дуйся, пла́меню, єрети́чеськая уче́нія пожига́яй.","Ра́дуйся, святи́телю, поуча́яй всіх, я́ко ність іна́го Бо́га, кромі́ Небе́снаго;","ра́дуйся, челові́ков вразуми́телю, глаго́ляй, я́ко ність спасе́нія вні собо́рния апо́стольськія Це́ркве.","Ра́дуйся, на богоуго́дноє житіє́ наставля́яй;","ра́дуйся, в Небе́сноє Ца́рствіє путь показу́яй.","Ра́дуйся, звіздо́ путеводя́щая ко Христу́;","ра́дуйся, путю́, і́мже прийдо́хом к і́стинному Бо́гу.","Ра́дуйся, ключу́, врата́ ра́йськая синово́м россі́йським отве́рзий.","Ра́дуйся, хода́таю, безчи́сленноє мно́жество сих та́мо водвори́вий.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия по лі́тіх мно́зіх ті́ло твоє́ свято́є нетлі́нно в землі́ соблюде́, в це́ркві Десяти́нней положе́но, і я́ко сокро́вище многоці́нноє па́стві твоє́й ці́ло і невреди́мо сіє́ яви́, я́ко ніже́ оде́жд твої́х свяще́нних косну́тися тлі́нію: отсю́ду у́бо ві́рою уразумі́хом, я́ко Христу́ предстої́ши і мо́лишися о почита́ющих тя і пою́щих Єму́ тебе́ ра́ди: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще свято́є і пресла́вноє житіє́ твоє́, Михаї́ле равноапо́стольне, почита́єм твою́ свяще́нную па́м'ять, ре́вность же твою́ по Бо́зі восхваля́єм, любо́в твою́ ко Христу́ і к бли́жнему превозно́сим. Ти же, о всеблаже́ннійший о́тче, не возгнуша́йся смире́нним сим пі́нієм:","Ра́дуйся, я́ко Престо́лу Пресвяти́я Тро́йці предстої́ши;","ра́дуйся, я́ко Всемогу́щаго о всем ми́рі мо́лиши.","Ра́дуйся, я́ко со арха́нгели і а́нгели Трисвяту́ю піснь на Небесі́ поє́ши;","ра́дуйся, я́ко со апо́столи в ра́йських оби́теліх пребива́єши.","Ра́дуйся, я́ко с ли́ки святи́телей пред Бо́гом о душа́х на́ших хода́тайствуєши;","ра́дуйся, я́ко с полки́ преподо́бних спасе́нію на́шему споспешеству́єши.","Ра́дуйся, я́ко с Пречи́стою Ді́вою Богоро́дицею, ру́ці свої́ пречестни́я о ми́рі Оте́чества на́шего ко Христу́ воздіва́єши;","ра́дуйся, я́ко о соєдине́нії люде́й непреста́нно Єго́ умоля́єши.","Ра́дуйся, со проро́ки і му́ченики Ви́шняго Ца́рствія наслі́дниче;","ра́дуйся, рая́ Бо́жия со всі́ми святи́ми єдиновсе́льниче.","Ра́дуйся, небе́сних вели́чий і красо́т зри́телю;","ра́дуйся, безконе́чних сла́достей і блаже́нств ра́йських облада́телю.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 13","ps":["О всехва́льний і преди́вний чудотво́рче, о́тче наш Михаї́ле, Россі́йськия страни́ пе́рвий святи́телю і всіх правосла́вних христия́н предста́телю, прийми́ сіє́ ма́лоє моле́ніє на́ше, в похвалу́ тебі́ приноси́моє, і моли́твами твої́ми іспроси́ нам у Бо́га во ві́ці сем житіє́ ти́хоє і доброді́телей іспо́лненноє, да і в жи́зні бу́дущей сподо́бимся ку́пно с тобо́ю пі́ти в Тро́йці Єди́ному Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелов і а́нгелов Цар, і всея́ тва́рі Созда́тель і Промисли́тель, милосе́рдіє Своє́ яви́ к лю́дем страни́ на́шея, во тьмі ідолослуже́нія ходи́вшим, і тя, святи́телю Михаї́ле, я́ко апо́стола посла́, да сія́ просвіти́ши сві́том і́стиннаго богопозна́нія. І се твої́ми уче́ньми, я́же пе́рвіє же́ртви бісо́м приноша́ху, ни́ні ду́ші своя́ дароно́сять Христу́. Тебі́ же благода́рственная сія́ возно́сять піснопі́нія:","Ра́дуйся, ві́ри Христо́ви усе́рдний насади́телю;","ра́дуйся, ідолослуже́ніє іскорени́вий.","Ра́дуйся, бісо́вськия же́ртви упраздни́вий;","ра́дуйся, сві́те, от восто́ка возсія́вий.","Ра́дуйся, тьму ідолобі́сія разгна́вий;","ра́дуйся, уче́нієм Христо́вим лю́ди просвіти́вий.","Ра́дуйся, і́дольськия тре́би кресто́м разруши́вий;","ра́дуйся, ни́ву Христо́ву до́брі возде́лавий.","Ра́дуйся, благопло́дная сі́мена на ней всі́явий;","ра́дуйся, медото́чная уста́ Христо́ва;","Ра́дуйся, свирі́ль благозву́чная Ду́ха Свята́го.","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Кондак 1","ps":["Ізбра́нний от Христа́ Бо́га сосу́д, по́слан бил єси́ в зе́млю Россі́йськую і язи́к наш святи́м креще́нієм просвіти́л єси́ святи́телю о́тче Михаї́ле, ті́мже Влади́ці своєму́ на небесі́ ни́ні предстоя́, тому́ моли́ся прилі́жно, от вся́ких бід і напа́стей ізба́витися ста́ду твоєму́, да зове́м ті:","Ра́дуйся, Михаї́ле, вели́кий ієра́рше, Це́ркве Россі́йськия пресла́вний первопресто́льниче."]},{"h":"Молитва","ps":["О, святи́й вели́кий і пресла́вний архіпа́стирю і о́тче наш Михаї́ле, страни́ Россі́йськия первопресто́льниче і просвіти́телю, всіх же племе́н христия́нських благонаде́жний пред Бо́гом хода́таю, тебі́ припа́дающе мо́лимся: помози́ нам би́ти твоєя́ к Бо́гу любве́ подража́тельми, є́ю же в земні́м животі́ твоє́м преіспо́лнен бил єси́. Просвіти́ уми́ і сердця́ на́ша сві́том Боже́ственнаго уче́нія. Научи́ нас тебі́ послі́довати ві́рно і за́повіді Госпо́дні усе́рдно твори́ти, да яви́мся ча́да твоя́ не і́менем то́кмо, но і всім житіє́м, та́ко позна́ємся. Моли́ся, равноапо́стольне ієра́рше, о Це́ркві Росси́йстій, о гра́ді твоє́м і оби́телі, в ней же нетлі́нно мо́щі твоя́ святи́я почива́ють, і о всем Оте́честві на́шем, при́зри ми́лостивно на вся ві́рния твоя́ чти́телі, по́мощі твоєя́ і́щущия: бу́ди всім в болі́зніх ціли́тель, в ско́рбіх і печа́ліх уті́шитель, в біда́х і ну́ждах помо́щник, в час же сме́ртний засту́пник і покрови́тель, да твоє́ю по́мощію сподо́бимся і ми грі́шнії спасе́ніє получи́ти і Ца́рствіє Христо́во наслі́довати. Єй, святи́телю Христо́в, а́ще восхо́щеши мо́жеши по́мощи нам, да на по́мощ твою́ упова́юще, просла́вим Ди́внаго во святи́х Свої́х Бо́га Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь проро́чествіє во апо́століх Первозва́ннаго іспо́лнися: / се бо на сих гора́х возсія́ благода́ть і ві́ра умно́жися. / І і́же неві́рієм обветша́вшії / Боже́ственною купі́лію отроди́шася / і би́ша лю́діє обновле́нія, / ца́рськоє свяще́ніє, язи́к свят, Христо́во ста́до, / єму́же ти пе́рвий па́стир яви́лся єси́, / я́ко пе́рвіє Креще́нієм послужи́вий. / І ни́ні, предстоя́ Влади́ці Христу́ Бо́гу, / моли́ всім сино́м ру́ським спасти́ся: // і́маши бо дерзнове́ніє я́ко ієра́рх Бо́жий і священнослужи́тель."]},{"h":"Кондак, глас 2","ps":["Моїсей втори́й Россі́ї яви́лся єси́, о́тче, / пренеси́й ми́сленний виногра́д от єгипе́тськаго ідолослуже́нія / в зе́млю проро́чествієм предуви́діну. / Бу́деть, рече́, утвержде́ніє ві́ри на землі́, / і на ве́рсіх гор Ки́євських превознесе́ться па́че Лива́на / плод пита́ющ ми́ра всего́. / От него́же вкуси́вше, // ублажа́єм тя, Михаї́ле, Бо́жий ієра́рше."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Михаї́ле, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Никону, ігумену Радонезькому","e":"Akathist to our Venerable Father Nikon, Abbot of Radonezh","secs":[{"h":"Кондак 1","ps":["Великого строї́теля Ла́ври богоно́снаго Се́ргия досто́йними похвала́ми ублажи́м пресла́вно. Ти же, я́ко до́брий люби́телю благолі́пія, прими́ от нас сицева́я, с любо́вію тебі́ приноси́мия пі́нія:","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Ікос 1","ps":["А́нгелу, пусти́нному подража́телю, к Се́ргію, отцю́ твоєму́ прите́кл єси́ і до конця́ ві́рен заветам єго́ преби́л єси́, ті́мже помина́й нас, во весе́лії зову́щих ті:","Ра́дуйся, Ни́коне, ізбі́гший жите́йських попече́ній.","Ра́дуйся, до́брий послу́шателю оте́чеських уче́ній.","Ра́дуйся, ко́рень зла в себі́ побіди́вий.","Ра́дуйся, лилію благоче́стія в се́рдці своє́м возрасти́вий.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 2","ps":["Ви́дя в роди́теліх свої́х до́броє благоче́стіє і ві́ри правосла́вния тве́рдоє іспові́даніє, я́ко ча́до їх возлю́бленноє воспіва́л єси́ с ни́ми: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум добр стяжа́в себі́, плоди́ благочести́ваго воспита́нія вско́рі, в младом возрасте́ яви́л єси́: кротостью і смире́нієм Бо́гу угожда́я, сим доброді́телем твої́м подража́я, сих доброді́телей дости́гнути жела́я, велегла́сно зове́м:","Ра́дуйся, до́брая о́трасле роди́телей благочести́вих;","Ра́дуйся, в ю́ності єще́ сад Христу́ в се́рдці своє́м насади́вий.","Ра́дуйся, і́ночеський путь на землі́ ізбра́вий;","Ра́дуйся, пре́лести ми́ра сего́ попра́вий.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 3","ps":["Си́лою сви́ше умудренний, к подви́жнику вели́кому прише́д і к стопа́м єго́ припал, умоля́я єго́, даби́ однім се́рдцем пі́ти с ним піснь Христу́ Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я от Бо́га дар прозрі́нія, Се́ргій Преподо́бний, оте́ць твой духо́вний, узрі́во в тебі́ і́скреннєє ізлія́ніє душі́ твоєя́, повелі́ [ко] ученику́ своєму́ Афана́сію в оби́тель єго́ ше́ствовати і в ней і́ночеському житію́ поуча́тися. Ми же на сем путі́ твоє́м зове́м:","Ра́дуйся, се́рдце своє́ преподо́бному отцю́ откри́вий;","Ра́дуйся, ду́шу свою́ в послуша́ніє єму́ преклони́вий.","Ра́дуйся, ре́вностним і́ноком себе́ яви́вий;","Ра́дуйся, ра́дость небе́сную получи́вий.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 4","ps":["Бу́рю жите́йських помишле́ній презрі́вши, сан ієре́я Бо́жия восприя́л єси́, в но́вом по́двизі своє́м всера́достно воспіва́я сре́дцем і усти́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша о твоє́м до́брім житії́, по двої́х лі́тіх преподо́бний оте́ць твой Се́ргій возжела́ ви́діти тя і с ра́достію прия́в, в єди́ной келії с собо́ю житії́ повелі́, благода́тію се́рдце твоє́ к соверше́нству уготовля́я, ми же вас вку́пі я́ко єди́них прославля́єм:","Ра́дуйтеся, до́брії доброді́телей подви́жници;","Ра́дуйтеся, душі́ свої́ в храм бо́жий устроїтеліє.","Ра́дуйтеся, Христо́вих соверше́нств достизателіє;","Ра́дуйтеся, ангельського житія́ подража́теліє.","Ра́дуйтеся, отці́ на́ші Се́ргіє і Ни́коне, Це́ркві Росси́йстій сла́во і украше́ніє."]},{"h":"Кондак 5","ps":["Богото́чною руко́ю духо́вная дарова́нія істоча́я, вся на поле́зная наставля́я, Се́ргіє і Ни́коне преподо́бне, піснь Бо́гу воспіва́юще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше до́браго себі́ помо́щника в попече́нії о бра́тії, учи́тель твой Се́ргій преподо́бний ізбра́ тя і поста́ви ігу́меном оби́телі своєя́, ти же Ни́коне всесла́вний, безмо́лвіє возлюби́вий, то́кмо во́лі отця́ повину́вшеся прия́л єси́ бре́м'я трудо́в єго́, того́ ра́ди зове́м:","Ра́дуйтеся, і́скреннії на́ші наста́вници;","Ра́дуйтеся, сла́внії домо́в Бо́жиїх строї́теліє.","Ра́дуйтеся, сокро́вищ духо́вних обладателіє;","Ра́дуйтеся, мона́шествующих собирателіє.","Ра́дуйтеся, отці́ на́ші Се́ргіє і Ни́коне, Це́ркві Росси́йстій сла́во і украше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дник боже́ственних уче́ній бил єси́, Ни́коне преподо́бне, в це́ркві бра́тію поуча́я, пі́ти всегда́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ми́ру сві́том євангельського благоче́стія, к ми́ру а́нгельському преста́вися учи́тель твой, Ни́коне преподо́бне, ти же ско́рбію іспо́лненний, прими́ я́ко о́бщника печа́лі твоєя́, піснопі́нія сія́:","Ра́дуйтеся, преподо́бнії Се́ргіє і Ни́коне, і́стиннії дру́зі Христо́ви;","Ра́дуйтеся, ві́рнії ісполни́теліє за́повідей єго́.","Ра́дуйтеся, до́брії ді́лателіє вертогра́да єго́;","Ра́дуйтеся, блаже́ннії наслі́дници, го́рнія сла́ви єго́.","Ра́дуйтеся, отці́ на́ші Се́ргіє і Ни́коне, Це́ркві Росси́йстій сла́во і украше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ до́брі іспо́лнити служе́ніє своє́, любо́в оте́чеськую к бра́тії ізливал єси́, ті́мже і і́м'я твоє́, я́ко ми́ро всю́ду, благоуха́нієм свої́м подвиза́я всіх пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно явля́я в житії́ своє́м мно́гіє труди́ твоя́, єще́ і сло́вом поуче́нія мона́шествующих наставля́я ка́ко жи́ти їм по во́лі Творця́ своєго́; за сію́ ре́вность ді́ланія твоєго́ прими́ похвалу́ сію́:","Ра́дуйся, до́брий па́стирю ове́ць свої́х;","Ра́дуйся, ігу́мене, досто́йний преподо́бнаго Се́ргия преє́мниче.","Ра́дуйся, тве́рдий ісполни́телю єго́ велі́ній;","Ра́дуйся, люби́мий посреді́ мона́шествующих селе́ній.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 8","ps":["Стра́нно безмо́лвія люби́телю обителью і́ноков управля́ти і ігу́меном бра́тії битії́ і по шести́ лі́тіх на по́двиг соверше́ннаго уєдине́нія, преподо́бне о́тче, устреми́ся, да єди́ною душе́ю неразлу́чно Бо́гу предстоя́ вопи́ти Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь го́ре возви́сися і созерца́я се́рдцем неізрече́нная і пресла́вная, не можа́ше отри́нути моле́ніє бра́тії: «Попекись і о спасе́нії бли́жніх твої́х», с любо́вію прия́л па́ки бре́м'я трудо́во в оби́телі: сих ра́ди і ми па́ки зове́м ті:","Ра́дуйся, ско́рий послу́шателю ві́рних моле́ній;","Ра́дуйся, те́плий хода́таю на́ших проше́ній.","Ра́дуйся го́ре предстоя́щий;","Ра́дуйся, до́лі усе́рдієм горя́щий.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 9","ps":["Вся бра́тія оби́телі Святи́я Тро́йці печа́лі іспо́лнишася, єгда́ хан Єдигей опустоши́ зе́млю Россі́йськую і к оби́телі їх приступи́, то́кмо моли́твами Ни́кона ігу́мена своєго́ не оста́ви пі́ти піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовещанії недоуміва́ють, что і глаго́лати о пречудном виді́нії преподо́бнаго, єгда́ святи́теліє Московскиє Петр і Алексей, а с ни́ми і преподо́бний Се́ргій яви́шася і реко́ша єму́: «Уго́дно сіє́ Го́споду, да коснуться сего́ мі́ста іноплеме́нници, да не скорбі́те і не смущайте серде́ць ва́ших; іскуше́ніє ско́ро пре́йде і оби́тель не то́кмо не запусті́єть, но бо́ліє расцвететь». За сіє́ открове́ніє тебі́ досто́йні воспіва́ти похвали́ сія́:","Ра́дуйся, Ни́коне, моли́твенниче те́плий і преізря́дний;","Ра́дуйся, открове́ній Бо́жиїх зри́телю.","Ра́дуйся, бу́дущих я́ко настоя́щая созерца́телю.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ святи́ні ні́ким удали́хся вре́менно с бра́тію своє́ю із оби́телі і в ізгна́нії не преста́ с наде́ждею воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чний, Уті́шителю, Тро́йце Пребоже́ственная, не даде́ поги́бнути мі́сту ізбра́нному і по удале́нії Єдигея с полчищами, превратившаго всю оби́тель в развалини, возврати́шася преподо́бний с бра́тією і нача́ восставляти оби́тель своєго́ чу́днаго наста́вника, за сію́ ре́вность пла́менную і за вели́коє мно́жество трудо́в твої́х, прими́ всеблаже́нне Ни́коне, піснь сію́ к тебі́ возноси́мую:","Ра́дуйся, возлю́бленноє ча́до Святи́я Тро́йці;","Ра́дуйся, ізбра́нний сосу́де Боже́ственнаго промишле́нія.","Ра́дуйся, мно́гі ско́рбі претерпі́вий;","Ра́дуйся, от них же Господом ізба́вивийся.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим тебі́, преподо́бне, я́ко по тріє́х лі́тіх через тя іспо́лнишася проро́чеськоє прорече́ніє отця́ твоєго́ духовного і оби́тель я́ко крин процвіте́ на мі́сті опустошенія і все мно́жества і́ноков воспі́ша благода́рственную піснь Го́споду: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́теля узрі́во в тебі́ Це́рков Россі́йськая, я́ко сподо́бишася обрісти́ і на сві́щниці ми́ра отця́ твоєго́ Се́ргия богоно́снаго, мо́щі святи́я поста́вити і над си́ми храм Живначальния Тро́йці воздви́гнути і живописью лу́чшею украси́ти єго́, за сія́ труди́ твоя́ прими́ от недосто́йних уст славосло́вія:","Ра́дуйся, сподо́бивийся узрі́ти і ми́ру всему́ яви́ти свята́го ті́ла Сергієва нетлі́ніє;","Ра́дуйся, чрез сіє́ громогласно пропові́давий та́їнство Воскресе́нія.","Ра́дуйся, Па́сху ві́чную ми́ру яви́вий;","Ра́дуйся, строї́телю це́ркві Бо́жієй і украси́телю.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть пода́ждь мі, Го́споди, да воспою́ досто́йно уго́дника твоєго́, науча́юща всіх пі́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще житіє́ твоє́, о́тче преподо́бне, восхваля́єм і сконча́ніє твоє́, ка́ко поуча́я бра́тію: «Держа́ти ві́ру пра́вую і житіє́ благочести́воє» умолк і в ра́дості воскликнув: «Отнесіте меня в хра́мину сві́тлую, угото́ванную мні моли́твами отця́ моєго́», і, огради́в себ'я́ крестним зна́менієм, ду́шу свою́ Бо́гу пре́дал єси́, ті́мже ми ві́чно тебі́ благодарнії, благогові́йно поє́м:","Ра́дуйся, світи́льниче ві́ри і благоче́стія;","Ра́дуйся, луче́ Сві́та Невече́рняго.","Ра́дуйся, наслі́дниче жи́зні ві́чния;","Ра́дуйся, ра́досте на́ша і похвале́ніє.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 13","ps":["О, вели́кий уго́дниче Бо́жий, дру́же Сергієв і сожи́телю всім святи́м, не преста́й посіща́ти нас, любо́вію помина́ющих тя, подава́я тре́бующим ісціле́ніє і ми́ру всему́ утіше́ніє, да с ра́достію всегда́ вопіє́м: Аллилу́я, аллилу́я, аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелу, пусти́нному подража́телю, к Се́ргію, отцю́ твоєму́ прите́кл єси́ і до конця́ ві́рен заветам єго́ преби́л єси́, ті́мже помина́й нас, во весе́лії зову́щих ті:","Ра́дуйся, Ни́коне, ізбі́гший жите́йських попече́ній.","Ра́дуйся, до́брий послу́шателю оте́чеських уче́ній.","Ра́дуйся, ко́рень зла в себі́ побіди́вий.","Ра́дуйся, лилію благоче́стія в се́рдці своє́м возрасти́вий.","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Кондак 1","ps":["Великого строї́теля Ла́ври богоно́снаго Се́ргия досто́йними похвала́ми ублажи́м пресла́вно. Ти же, я́ко до́брий люби́телю благолі́пія, прими́ от нас сицева́я, с любо́вію тебі́ приноси́мия пі́нія:","Ра́дуйся, Ни́коне, Це́ркві Росси́йстій украше́ніє."]},{"h":"Тропар, глас 1","ps":["Послуша́нія до́брий рачи́тель бив, / преподо́бне Ни́коне приснопа́м'ятне, / Це́рков бо прекра́сну Святи́я Тро́йці / в похвалу́ отцю́ твоєму́ воздви́гл єси́. / Тім­же і ми, ча́да твоя́, любо́вію вопіє́м ті: / сла́ва Да́вшему ті крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 4","ps":["Духо́вному твоєму́ настоя́телю, о́тче Ни́коне, / вся́чеськи приліпи́вся / і от него́ наставля́єм, / во всем Христо́ві порабо́тився, / мона́хов бил єси́ чинонача́льник / і преподо́бних сожи́тель, // с ни́миже Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ни́коне, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Саві Освяченому","e":"Akathist to our Venerable Father Sabbas the Sanctified","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, преподо́бне о́тче Са́вво, ми́ру правосла́вному світи́льниче і те́плий о нас пред Бо́гом моли́твенниче! Велича́єм просла́вльшаго тя Го́спода, восхваля́юще любо́вію равноа́нгельноє житіє́ твоє́. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Соді́тель ізбра́ тя от младе́нства, преподо́бне, просла́вити трисія́тельноє і́м'я Єго́: ти бо, осмиле́тен сий, вся кра́сная ми́ра тлі́ннаго презрі́в, во оби́тель святу́ю прите́кл єси́, іді́же я́ко а́нгел земни́й богоуго́дно подвиза́лся єси́. Ті́мже і всели́ся в тя благода́ть Пресвята́го Ду́ха, Єго́же ді́йством сві́тло украша́яся, ангелоподо́бноє житіє́ показа́л єси́. Ми же, зря́ще ве́лія ісправле́нія твоя́, с любо́вію вопіє́м тебі́ си́це:","Ра́дуйся, роди́телей благочести́вих благослове́нний пло́де.","Ра́дуйся, Каппадокі́йськия страни́ свято́є украше́ніє.","Ра́дуйся, Палести́нськия землі́ і гра́да Ієрусали́ма світи́льниче.","Ра́дуйся, во Іорда́нстій пусти́ні со а́нгели всели́вийся.","Ра́дуйся, я́ко от младе́нства Христа́ возлюби́л єси́.","Ра́дуйся, я́ко же́ртву живу́ю себі́ Го́сподеві прине́сл єси́.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послі́дователю.","Ра́дуйся, за́повідей Госпо́дніх ві́рний блюсти́телю.","Ра́дуйся, я́ко от ю́ности і́гу Христо́ву себі́ порабо́тил єси́.","Ра́дуйся, я́ко красоту́ тлі́нную і мирську́ю сла́дость ні во что́же вміни́л єси́.","Ра́дуйся, Бо́жия ра́зума іспо́лненний.","Ра́дуйся, благода́тію Ду́ха Свята́го приосіне́нний.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 2","ps":["Ви́дів Всеві́дець Госпо́дь благо́є ду́ші твоєя́ проізволе́ніє, є́же рабо́тати Єму́ усе́рдно вся дні живота́ твоєго́, єще́ во ю́ности просла́ви тя Боже́ственною Своє́ю си́лою: любве́ бо ра́ди бра́тськия в разжже́нную пещ вступи́в і оде́жди твоя́ неопале́нни сохрани́в, благода́тію Бо́жиєю неврежде́н от огня́ преби́л єси́. Сего́ ра́ди прославля́юще Царя́ сла́ви Христа́, прославля́ющаго святи́я Своя́, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум просвіще́н от Бо́га імі́я, преподо́бне о́тче Са́вво, дия́вольськия іскуше́нія при́сно разумева́л єси́: єгда́ бо преле́стник ро́да челові́чеськаго іскуси́ тя взя́ти плод дре́ва пре́жде ста́рчеськаго благослове́нія, а́біє пом'яну́л єси́ прароди́телі, і́же сні́дію дре́ва в раї́ прельсти́шася. Ті́мже пове́рг плод на зе́млю; нога́ми сей попра́л єси́, запові́дав себі́ до сме́рти не вкуси́ти плода́ сего́, главу́ дре́вняго змі́я сокруша́я. Сего́ ра́ди прийми́ от нас похвали́ сія́:","Ра́дуйся, от ю́ности по́стничеськоє житіє́ показа́вий.","Ра́дуйся, на висоту́ доброді́телей возше́дий.","Ра́дуйся, мона́шеськаго житія́ і уста́ва і́стовоє пра́вило.","Ра́дуйся, ре́вностний ісполни́телю оте́чеських преда́ній.","Ра́дуйся, я́ко любве́ ра́ди бра́та в пе́щний пла́мень вшел єси́.","Ра́дуйся, я́ко си́лою благода́ті Христо́ви от огня́ не опале́н ізше́л єси́.","Ра́дуйся, всеці́лоє послуша́ніє Го́споду Бо́гу соверши́вий.","Ра́дуйся, главу́ дре́вняго запина́теля сокруши́вий.","Ра́дуйся, на висоту́ безстра́стія возше́дий.","Ра́дуйся, ко́зні де́монськия до конця́ побіди́вий.","Ра́дуйся, благо́є і́го Христо́во на рамена́ твоя́ восприя́вий.","Ра́дуйся, зако́на Бо́жия от всея́ ду́ші взиска́вий.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго, просвіща́ющая вся́каго челові́ка, гряду́щаго в мир, і показу́ющая путі́ пра́вия, наста́ви тя, преподо́бне о́тче Са́вво, дости́гнути свята́го гра́да Ієрусали́ма, іді́же поклони́лся єси́ Живоно́сному Гро́бу Воскре́сшаго Христа́, і со слеза́ми облобиза́в, благода́рственно воспі́л єси́ Єму́ піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ве́лію ре́вность о по́двизі мона́шеськаго равноапо́стольнаго житія́, преподо́бне, потща́лся єси́ ідти́ во Іорда́нськую пусти́ню, іді́же наста́вника себі́ обрі́т вели́каго Євфи́мія і того́ житію́ досто́йно поревнова́в, свято́му Крести́телю Христо́ву Іоа́нну в по́двизіх твої́х уподо́бился єси́. Ми же, див'я́щеся бога́тству доброді́телей твої́х, усе́рдно вопіє́м ті:","Ра́дуйся, житію́ безпло́тних поревнова́вий.","Ра́дуйся, по́двигом дре́вніх святи́х оте́ць досто́йно подража́вий.","Ра́дуйся, пусти́ні Іорда́нськия благода́тноє прозябе́ніє.","Ра́дуйся, свята́го житія́ благоуха́ніє.","Ра́дуйся, благода́ті Христо́ви сосу́де ізбра́нний.","Ра́дуйся, пусти́нноє житіє́ па́че всего́ возлюби́вий.","Ра́дуйся, страсте́й те́рнія усе́рдно історга́вий.","Ра́дуйся, во ю́ном возрасте́ му́дростію Христо́вою просвіще́нний.","Ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний ревни́телю.","Ра́дуйся, у́мнаго трезві́нія неуси́пний храни́телю.","Ра́дуйся, лі́ствицею доброді́телей к небе́сним оби́телем возше́дий.","Ра́дуйся, я́ко фі́нікс в пусти́ні процвіти́й.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 4","ps":["Бу́рю внутр помисло́в і страсте́й во́лни безбі́дно преше́д, преподо́бне о́тче Са́вво, обрі́л єси́ ти́хоє приста́нище Христа́, Єму́же нелі́ностно во мно́зі долготерпі́нії порабо́тал єси́; отню́дуже Боже́ственною благода́тію Христо́вою восходя́ от си́ли в си́лу, от дія́нія к боговиді́нію, небе́снаго Сіо́на дости́гл єси́, іді́же со А́нгели поє́ши Тро́йці Святі́й піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще ди́вная твоя́ наставле́нія, я́же не то́чію в словесі́х, но і в по́двизіх твої́х явля́л єси́, прихожда́ху к тебі́ іздале́ча жа́ждущії спасе́нія, подража́ти доброді́телем твої́м хотя́щеє. Ти же, преподо́бне о́тче, му́дро назида́я і к Небе́сному Ца́рствію управля́я всіх, ві́рою притека́ющих к тебі́, світи́льник Правосла́вія соді́лался єси́. Сего́ ра́ди с любо́вію вопіє́м ті:","Ра́дуйся, наста́вниче мона́хов Богому́дрий.","Ра́дуйся, ове́ць христо́вих до́брий па́стирю.","Ра́дуйся, ко спасе́нію ві́рний путеводи́телю.","Ра́дуйся, по́стников ди́вний учи́телю.","Ра́дуйся, крі́пкоє па́дающих возведе́ніє.","Ра́дуйся, правостоя́щих утвержде́ніє.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послу́шателю.","Ра́дуйся, і́ночеськаго житія́ до́брий наста́вниче.","Ра́дуйся, я́ко огне́м моли́тви стрі́ли вра́жія попали́л єси́.","Ра́дуйся, я́ко єще́ во пло́ті сий, ра́йськую сла́дость предвкуси́л єси́.","Ра́дуйся, пусти́нний жи́телю і в тілесі́ а́нгеле.","Ра́дуйся, вселе́нния світи́льниче.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́, блаже́нне Са́вво, смире́нієм возвиша́ємий і в го́рняя черто́ги востеки́й, науча́я всіх го́рняя му́дрствовати, а не земна́я, от страсте́й отреша́тися, со Христо́м жи́ти і от сердця́ воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя ученици́ твої́ наста́вника прему́дра і зна́менієм небе́сния благода́ті сія́юща, дивля́хуся, тща́щеся твоєму́ житію́ подража́ти; я́ко бо луча́ сві́тлаго со́лнця пра́вди, просвіти́ся житіє́ твоє́. Сего́ ра́ди сли́шиши от всіх похва́льная пі́нія такова́я:","Ра́дуйся, восто́чная звіздо́ златоза́рнійшая.","Ра́дуйся, а́нгелов собесі́дниче.","Ра́дуйся, по́стников похвало́.","Ра́дуйся, безмо́лвствующих сла́во.","Ра́дуйся, учи́телю смире́нія і цілому́дрія.","Ра́дуйся, о́бразе кро́тости і послуша́нія.","Ра́дуйся, я́ко во глубини́ нищети́ духо́вния прини́кл єси́.","Ра́дуйся, я́ко на висоту́ доброді́телей возше́л єси́.","Ра́дуйся, я́ко путь к животу́ ві́чному обрі́л єси́.","Ра́дуйся, я́ко ісправле́нії твої́ми безпло́тния удиви́л єси́.","Ра́дуйся, мно́жество душ уневі́стивий Христу́.","Ра́дуйся, ку́пно с ни́ми пребива́яй в ра́дості Го́спода твоєго́.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 6","ps":["Пропові́дник і ісполни́тель Єва́нгельських слове́с, є́же не скрива́ти себі́ сокро́вищ на землі́, яви́лся єси́, преподо́бне о́тче Са́вво. Сего́ ра́ди і ча́да твоя́ духо́вная наставля́л єси́, є́же Єди́наго Го́спода іска́ти во вся дні жи́зні своєя́, всім се́рдцем Тому́ приліпля́тися і непреста́нно пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ Боже́ственний, в нощі́ моля́щуся тебі́, преподо́бне, показу́я столпо́м о́гненним пеще́ру нерукотворе́ну, ю́же храм соді́лал єси́, і та́мо вели́кую ла́вру устро́їв, богоуго́дния по́двиги і моли́твенния труди́ показа́л єси́. Ми же, вели́чію благода́ті Ви́шняго, на тебі́ почи́вшия, див'я́щеся, умиле́нно взива́єм:","Ра́дуйся, я́ко виді́нія пренебе́снаго сві́та сподо́бился єси́.","Ра́дуйся, я́ко благоволе́нієм Бо́жиїм вели́кую ла́вру устро́їл єси́ і в ню мно́жество і́ноков собра́л єси́.","Ра́дуйся, духо́вния о́вці ко го́рнему ца́рствію до́брі упра́вивий.","Ра́дуйся, мно́гая чудеса́ благода́тію Свята́го Ду́ха сотвори́вий.","Ра́дуйся, ліни́вия подви́гнувий ре́вностними по́двиги твоєго́ житія́ Христолюби́ваго.","Ра́дуйся, печа́льних ско́роє утіше́ніє.","Ра́дуйся, Єва́нгелія Христо́ва богому́дрий учи́телю.","Ра́дуйся, провозві́стниче путе́й Госпо́дніх.","Ра́дуйся, вся во уме́ти вміни́вий, да Христа́ приобря́щеши.","Ра́дуйся, Христу́ невозвра́тно послі́довавий.","Ра́дуйся, благи́й і ві́рний ра́бе Христо́в.","Ра́дуйся, до́брий ді́лателю виногра́да Христо́ва.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 7","ps":["Хотя́ ві́рен би́ти до конця́ Ісу́су Христу́, Си́ну Бо́жию, взе́мшему гріхи́ ми́ра, кро́тость, незло́біє, смире́ніє в се́рдці твоє́м до́брі насади́л єси́, богоно́се о́тче Са́вво, і вся́кия ско́рби, укоре́нія і досажде́нія ра́достно претерпі́л єси́, ві́дая, я́ко мно́гими скорбми́ подоба́єть вни́ти в Ца́рствіє Небе́сноє. Сего́ ра́ди, несе́нієм креста́ Христо́ва і терпі́нієм скорбе́й, єще́ на землі́ ду́шу твою́ во оби́тель Пресвяти́я Тро́йці устро́їл єси́, Є́йже ни́ні предстої́ши со А́нгели і вопіє́ши а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вний воі́стину побідоно́сець показа́лся єси́ на стра́сті плотські́я, богоблаже́нне; вся бо разжже́нния стрі́ли лука́ваго посто́м, бді́нієм і сле́зними моли́твами угаси́л єси́. Ті́мже вопіє́м тебі́ сицева́я:","Ра́дуйся, крест Христо́в на рамена́ твоя́ восприє́мий.","Ра́дуйся, кресто́м сим я́ко лі́ствицею на не́бо возше́дий.","Ра́дуйся, терпі́нія і незло́бія рачи́телю.","Ра́дуйся, і́ноков до́брі подвиза́ющихся моли́твенний пред Бо́гом предста́телю.","Ра́дуйся, ві́ри Правосла́вния мо́щний защи́тниче.","Ра́дуйся, Небе́снаго Ца́рствія наслі́дниче.","Ра́дуйся, благода́тію Бо́жиєю приосіне́нний.","Ра́дуйся, я́ко о́браз страсте́й Христо́вих в се́рдці твоє́м предписа́л єси́.","Ра́дуйся, сві́том трисо́лнечним Святи́я Тро́йці озаре́нний.","Ра́дуйся, я́ко душе́внима очи́ма при́сно Го́спода созерца́л єси́.","Ра́дуйся, я́ко благода́тію Бо́жиєю вся прови́діл єси́.","Ра́дуйся, благода́тними чудеси́ житіє́ твоє́ озари́вий.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 8","ps":["Стра́нника і прише́льця помишля́л єси́ в себі́ би́ти в ми́рі сем, преблаже́нне о́тче Са́вво; ті́мже гряду́щаго гра́да Ієрусали́ма Небе́снаго взиску́я, вся помишле́нія твоя́ к небесі́ непреста́нно возноси́л єси́, і, я́ко в тимпа́ні, во умерщвле́ннем тілесі́, сла́дці воспіва́л єси́ побі́дную піснь Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь обле́клся єси́ во ору́жія Бо́жия, преподо́бне; ті́мже возмо́гл єси́ всю си́лу дия́волю низложи́ти. Помози́ у́бо і нам, преблаже́нне о́тче, моли́твами твої́ми ізби́ти сіте́й вра́жиїх, да благода́рственно зове́м тебі́ си́це:","Ра́дуйся, сто́лпе непрекло́нний терпі́нія.","Ра́дуйся, ревни́телю от ми́ра удале́нія.","Ра́дуйся, я́ко держа́вно плотські́я стра́сті низложи́л єси́.","Ра́дуйся, я́ко плоть твою́ ду́хові покори́л єси́.","Ра́дуйся, я́ко во бді́нних моли́твах неосла́бно пребива́л єси́.","Ра́дуйся, я́ко умерщвле́нієм пло́ті безстра́стіє стяжа́л єси́.","Ра́дуйся, я́ко вся́коє наслажде́ніє земно́є возненави́діл єси́.","Ра́дуйся, я́ко ті́сним і приско́рбним путе́м ходи́л єси́.","Ра́дуйся, я́ко я́зви Го́спода Ісу́са Христа́ на ті́лі твоє́м носи́л єси́.","Ра́дуйся, я́ко си́лою креста́ Госпо́дня де́монськия ко́зні сокруши́л єси́.","Ра́дуйся, ви́шніх іді́же Христо́с сі́де одесну́ю Отця́ при́сно іска́вий.","Ра́дуйся, ми́сленним о́ком к невече́рнему сві́ту Христу́ непреста́нно взира́вий.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє просла́ви тя і Це́рков восхвали́, преподо́бне о́тче Са́вво; ти бо царя́ неправому́дрствующа і Севи́рови єресенача́льники проти́в'ящіяся Правосла́вній Це́ркві небоя́зненно обличи́л єси́ і, все духо́вноє во́їнство Правосла́вія совокупи́в, є́ресь в коне́ць низложи́л єси́, нас же всіх во правові́рії утверди́в, научи́л єси́ єдиногла́сно воспіва́ти Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния недоумі́ють досто́йно восхвали́ти тя, преблаже́нне; па́че бо єстества́ челові́чеськаго подвиза́лся єси́ во вся дні живота́ твоєго́. Ті́мже чудеси́ Христо́с Бог тебі́ обогати́, я́ко і зві́ріє ди́вії повинова́хуся і служа́ху тебі́, во дні же гла́да моли́твою твоє́ю не́бо дождь даде́ на зе́млю су́ху. Сего́ ра́ди, любо́вію подвиза́ємії, вопіє́м тебі́ такова́я:","Ра́дуйся, Це́ркве Правосла́вния похвало́.","Ра́дуйся, єретико́в і всіх проти́вников правові́рія обличи́телю.","Ра́дуйся, я́ко люде́й увіща́ти о і́стині Правосла́вія потща́лся єси́.","Ра́дуйся, за і́стину Правосла́вія мно́гія труди́ і по́двиги под'є́мий.","Ра́дуйся, Правосла́вния ві́ри світи́ло і утвержде́ніє.","Ра́дуйся, проро́ком, апо́столом і святи́телем сопричте́нний.","Ра́дуйся, царе́й правосла́вних покро́ве і защи́щеніє.","Ра́дуйся, христия́н правові́рних моли́твенноє огражде́ніє.","Ра́дуйся, єрети́чеських уче́ній разори́телю.","Ра́дуйся, правосла́вних догма́тов уясни́телю.","Ра́дуйся, всім подвиза́ющимся о Правосла́вії помо́щниче.","Ра́дуйся, па́стирей Правосла́вния Це́ркве споспі́шниче.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мно́жество люде́й твої́м попече́нієм, премилосе́рдий Госпо́дь досто́йна тя наста́вника ізбра́, преблаже́нне о́тче Са́вво; мно́зі бо тобо́ю на путь спасе́нія наста́влени би́ша, і мно́гі оби́телі твої́м тща́нієм устро́їшася, в ни́хже науча́л єси́ немо́лчно воспіва́ти Єди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рдая і крі́пкоє огражде́ніє правосла́вних яви́лся єси́, преподо́бне, хода́тайством бо твої́м мир Це́ркві Бо́жієй дарова́ся. Ті́мже мо́лим тя, преблаже́нне, бу́ди помо́щник во всіх ско́рбіх і напа́стіх і нам, к заступле́нію твоєму́ прибега́ющим, да со умиле́нієм вопіє́м ті си́це:","Ра́дуйся, пусти́нниче, мирську́ю суєту́ возненави́дівий і Єди́наго Бо́га іска́вий.","Ра́дуйся, алтаря́ Госпо́дня служи́телю благогові́йний.","Ра́дуйся, со вся́ким тща́нієм Го́споду благоугожда́вий.","Ра́дуйся, пла́менную любо́в ко Христу́ яви́вий.","Ра́дуйся, мно́гія оби́телі созида́вий.","Ра́дуйся, мно́жество чад духо́вних внутр собра́вий.","Ра́дуйся, во оскуде́ніїх і лише́ніїх на Бо́га упова́вий.","Ра́дуйся, ві́рою і упова́нієм ізоби́ліє плодо́в земни́х приє́мий.","Ра́дуйся, тезоімени́тия тебі́ оби́телі стра́же неуси́пний.","Ра́дуйся, в біда́х, напа́стіх і ско́рбіх помо́щниче неотсту́пний.","Ра́дуйся, і́ноков ко спасе́нію до́брий путеводи́телю.","Ра́дуйся, многомо́щний моли́твенниче о душа́х на́ших.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сим тебі́, преподо́бне о́тче Са́вво, і с любо́вію припа́дающе ко ізображе́нію честна́го ли́ка твоєго́, восхваля́єм ангелоподо́бноє житіє́ твоє́. Ти же, предстоя́ престо́лу Пресвяти́я Тро́йці, не преста́й моля́ся о нас, ублажа́ющих тя, да сподо́бимся небе́снаго селе́нія дости́гнути і гла́сом ра́дованія воспі́ти Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник Бо́жия благода́ті бил єси́, преблаже́нне, сего́ ра́ди в сме́ртнім успе́нії твоє́м душа́ твоя́, я́ко со́лнце сія́ющая, вознесе́на бисть святи́ми а́нгели в небе́сния оби́телі. Ми же, помина́юще твою́ блаже́нную кончи́ну і на небесі́ прославле́ніє, ра́достно вопіє́м ті:","Ра́дуйся, уго́дниче Бо́жий, тече́ніє твоєя́ жи́зні благоче́стно сконча́вий.","Ра́дуйся, ві́ру, наде́жду і любо́в до конця́ сохрани́вий.","Ра́дуйся, я́ко ца́рство і сла́ву ві́чную наслі́довал єси́.","Ра́дуйся, я́ко по труді́х житія́ земна́го в небе́сних селе́ніїх водвори́лся єси́.","Ра́дуйся, нетлі́нним вінце́м сла́ви небе́сния от ру́ки Вседержи́теля увінча́нний.","Ра́дуйся, блаже́нство ра́йськоє со всі́ми святи́ми восприє́мий.","Ра́дуйся, а́нгеле земни́й і челові́че небе́сний.","Ра́дуйся, на небесі́ і на землі́ от Го́спода просла́вленний.","Ра́дуйся, живоно́сний істо́чниче, благода́ть ісціле́нія ізлива́яй.","Ра́дуйся, одержи́мих неду́ги благода́тію Бо́жиєю ісціля́яй.","Ра́дуйся, я́ко с висоти́ небе́сния на нас (і оби́тель твою́) призира́єши.","Ра́дуйся, я́ко всіх нас от напа́стей сохраня́єши.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 12","ps":["Благода́ть і ве́ліє твоє́ дерзнове́ніє пред Бо́гом ві́дуще, богоно́сне о́тче Са́вво, усе́рдно вопіє́м тебі́: не преста́й моля́ся те́плі ко Го́споду, да сохрани́ть святу́ю Це́рков Свою́ непози́блему от неві́рія, єресе́й і раско́ла, да ізба́вить нас от бід і лю́тих обстоя́ній і приведе́ть в Ца́рствіє Своє́ Небе́сноє, я́ко да поє́м со благодаре́нієм тобо́ю благоді́ющему нам ди́вному во святи́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще просла́вльшаго тя Го́спода і ублажа́юще тя, преблаже́нне о́тче, прилі́жно мо́лимся тебі́, є́же сподо́битися і нам хода́тайством твої́м неосужде́нно предста́ти Стра́шному Суди́щу Христо́ву, да с ра́достію і любо́вію воспомина́юще твоє́ моли́твенноє о нас пред Бо́гом предста́тельство, благохва́льно зове́м тебі́ си́це:","Ра́дуйся, пречестно́є селе́ніє Пресвяти́я Тро́йці.","Ра́дуйся, ізбра́нноє Свята́го Ду́ха жили́ще.","Ра́дуйся, сія́ніє незаходи́маго Со́лнця.","Ра́дуйся, луча́ми подвиго́в твої́х мона́шеськоє житіє́ озаря́яй.","Ра́дуйся, досто́йний А́нгелов собесі́дниче.","Ра́дуйся, му́чеников і преподо́бних на небесі́ сожи́телю.","Ра́дуйся, я́ко мзда твоя́ мно́га на небесі́.","Ра́дуйся, Це́ркві Правосла́вния украше́ніє.","Ра́дуйся, в біда́х су́щим ско́роє вспоможе́ніє.","Ра́дуйся, те́плий пред Го́сподем о нас моли́твенниче.","Ра́дуйся, при́сний і́ноков помо́щниче і засту́пниче.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 13","ps":["О вели́кий і ди́вний уго́дниче Христо́в, преподо́бне о́тче Са́вво! Прийми́ ми́лостивно сіє́ ма́лоє моле́ніє, от усе́рдія на́шего в похвалу́ тебі́ приноси́моє, і твої́м моли́твенним предста́тельством у престо́ла Царя́ Небе́снаго іспроси́ нам, є́же ізба́витися в жи́зні сей от всіх бід і напа́стей, в сме́ртнім же успе́нії на́шем благу́ю часть спасе́нія і наслі́діє ві́чних благ получи́ти, я́ко да сподо́бимся с тобо́ю і со всі́ми святи́ми в ра́дості ві́чній во ві́ки воспіва́ти Христу́ Бо́гу Спаси́телю на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Соді́тель ізбра́ тя от младе́нства, преподо́бне, просла́вити трисія́тельноє і́м'я Єго́: ти бо, осмиле́тен сий, вся кра́сная ми́ра тлі́ннаго презрі́в, во оби́тель святу́ю прите́кл єси́, іді́же я́ко а́нгел земни́й богоуго́дно подвиза́лся єси́. Ті́мже і всели́ся в тя благода́ть Пресвята́го Ду́ха, Єго́же ді́йством сві́тло украша́яся, ангелоподо́бноє житіє́ показа́л єси́. Ми же, зря́ще ве́лія ісправле́нія твоя́, с любо́вію вопіє́м тебі́ си́це:","Ра́дуйся, роди́телей благочести́вих благослове́нний пло́де.","Ра́дуйся, Каппадокі́йськия страни́ свято́є украше́ніє.","Ра́дуйся, Палести́нськия землі́ і гра́да Ієрусали́ма світи́льниче.","Ра́дуйся, во Іорда́нстій пусти́ні со а́нгели всели́вийся.","Ра́дуйся, я́ко от младе́нства Христа́ возлюби́л єси́.","Ра́дуйся, я́ко же́ртву живу́ю себі́ Го́сподеві прине́сл єси́.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послі́дователю.","Ра́дуйся, за́повідей Госпо́дніх ві́рний блюсти́телю.","Ра́дуйся, я́ко от ю́ности і́гу Христо́ву себі́ порабо́тил єси́.","Ра́дуйся, я́ко красоту́ тлі́нную і мирську́ю сла́дость ні во что́же вміни́л єси́.","Ра́дуйся, Бо́жия ра́зума іспо́лненний.","Ра́дуйся, благода́тію Ду́ха Свята́го приосіне́нний.","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, преподо́бне о́тче Са́вво, ми́ру правосла́вному світи́льниче і те́плий о нас пред Бо́гом моли́твенниче! Велича́єм просла́вльшаго тя Го́спода, восхваля́юще любо́вію равноа́нгельноє житіє́ твоє́. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, пресві́тлая мона́хов похвало́, Са́вво преподо́бне."]},{"h":"Молитва","ps":["О преди́вний і всехва́льний уго́дниче Бо́жий, преподо́бне о́тче Са́вво! Днесь (во святі́м хра́мі твоє́м) благогові́йно предстоя́ще пред свято́ю іко́ною твоє́ю і ра́достно соверша́юще пресві́тлую па́м'ять твою́, ублажа́єм тя засту́пника на́шего. Почита́юще же твоє́ ве́ліє дерзнове́ніє пред Го́сподем, смире́нно мо́лим тя, преблаже́нне: прийми́ ми́лостивно от нас хвале́бноє пі́ніє сіє́, от любве́ і усе́рдія тебі́ приноси́моє. І, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, потщи́ся богоприя́тним твої́м хода́тайством іспроси́ти у Царя́ ца́рствующих і Го́спода госпо́дствующих, я́ко да проба́вить вели́кия і бога́тия ми́лости Своя́ на нас грі́шних, да пода́сть нам дух пра́вия ві́ри, дух ві́дінія і любве́, дух ми́ра і ра́дости о Ду́сі Свя́те, да ізба́вить от бід і напа́стей, да низпо́слеть вся поле́зная ко спасе́нію душ на́ших. Всім же правосла́вним да низпо́слеть мир, тишину́, безм'яте́жіє, усе́рдіє к ісполне́нію за́повідей єго́, ізоби́ліє плодо́в земни́х, і да ізба́вить всю ру́ськую страну́ от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні, смертоно́сния я́зви і от вся́каго зла. Єй, уго́дниче Бо́жий! Не пре́зри моле́ній на́ших, но усли́ши нас моля́щихся тебі́, і под кро́вом заступле́нія твоєго́ сохрани́ нас (і оби́тель твою́) ненаві́тни от враг ви́димих і неви́димих, да сподо́бимся сконча́ти житіє́ на́ше в покая́нії і воспри́ймем ві́чная блага́я во Ца́рствії Христа́ Бо́га на́шего, іді́же восхва́лим с тобо́ю і всі́ми святи́ми достопоклоня́ємоє і́м'я Пресвяти́я Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Слез твої́х тече́ньми пусти́ні безпло́дноє возді́лал єси́, / і і́же із глубини́ воздиха́ньми во сто трудо́в уплодоноси́л єси́, / і бил єси́ світи́льник вселе́нній, сія́я чудеси́, Са́вво о́тче наш, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Я́ко от младе́нства Бо́гу же́ртва непоро́чная / прине́слся єси́ доброді́телію, Са́вво блаже́нне, / садоді́латель бив благоче́стія. / Ті́мже бил єси́ преподо́бних удобре́ніє, / граждани́н же пусти́нний достохва́лен. / Ті́мже зове́м ті: // ра́дуйся, Са́вво пребога́те."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Са́вво, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Макарію, ігумену Калязинському","e":"Akathist to our Venerable Father Macarius, Abbot of Kalyazin","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче, і ізря́дний уго́дниче Христо́в, многоціле́бний істо́чниче і моли́твенниче о душа́х на́ших, преподо́бне о́тче Мака́ріє, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела тя земна́го і челові́ка Небе́снаго, преподо́бне о́тче Мака́ріє, ки́їми пі́нії і пі́сньми восхва́лим, ки́їми вінці́ ув'язе́м трудолюбивую главу́ твою́, і ки́їми словеси́ возвели́чим многоболі́зненния по́двиги твоя́; ті́мже благогові́йно притека́юще к ра́ці многоціле́бних моще́й твої́х, усе́рдно припа́дающе, со умиле́нієм взива́єм ті:","Ра́дуйся, ре́вностний Христо́в подража́телю.","Ра́дуйся, за́повідей єго́ і́стинний блюсти́телю.","Ра́дуйся, а́нгелов собесі́дниче.","Ра́дуйся, преподо́бних похвала́.","Ра́дуйся, ві́рних слуге Госпо́день.","Ра́дуйся, усе́рдний чистоти́ і воздержа́нія храни́телю.","Ра́дуйся, сто́лпе терпі́нія.","Ра́дуйся, о́бразе незло́бія і кро́тости.","Ра́дуйся, смиренному́дрія наста́вниче.","Ра́дуйся, світи́льниче многосві́тлий.","Ра́дуйся, непости́дноє христия́н прибі́жище.","Ра́дуйся, безме́здний врачу́ немощству́ющих.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще благоро́днії твої́ роди́теліє во мла́дости тя, богому́дре, соверше́нная му́дрствующа, Го́споду, дарова́вшему ті такова́я, воспіва́ху благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неукло́нний імі́л єси́, преподо́бне Мака́ріє, а́ще і юн бив ті́лом, но стар сий умо́м: вся бо ми́ра сего́ кра́сная от ю́ности твоєя́ пренебре́г, ді́тськая ігра́лища презрі́л єси́, псалми́ же і пі́сні духо́вния Бо́гу Спаси́телю се́рдцем і усти́ непреста́нно воспіва́л єси́, научи́ і нас та́яжде му́дрствовати і ді́яти, вопію́щих ті:","Ра́дуйся, христия́нськия му́дрости і́стинноє зерца́ло.","Ра́дуйся, я́ко боже́ственному жела́нію ум твой от ю́ности впери́л єси́.","Ра́дуйся, я́ко во мла́дости твоє́й вре́менная і земна́я уме́ти би́ти вміни́л єси́.","Ра́дуйся, я́ко єди́ная небе́сная от сосцю́ ма́тере твоєя́ возлюби́л єси́.","Ра́дуйся, я́ко от ю́ности яре́м Госпо́день на ра́мена своя́ возложи́л єси́.","Ра́дуйся, я́ко плоть порабо́тил єси́ ду́ху.","Ра́дуйся, я́ко проти́ву ко́знем дия́вольским, єще́ юн сий, ста́ти не устраши́лся єси́.","Ра́дуйся, я́ко от младе́нчества чте́нія Боже́ственних Писа́ній всім се́рдцем возлюби́л єси́.","Ра́дуйся, я́ко день і нощ в чте́нії і пі́нії богодухнове́нних псалмо́в пребива́л єси́.","Ра́дуйся, я́ко непліне́нний страстьми́ ум твой сло́вом Бо́жиїм просвіти́л єси́.","Ра́дуйся, я́ко Христа́ єще́ в невинней душі́ твоє́й всели́л єси́.","Ра́дуйся, я́ко непоро́чним се́рдцем возжелі́л мирська́го м'яте́жа уклони́тися, і в пусти́ню всели́тися.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ду́ха Свята́го сви́ше облече́н бив, і ю́ности твоє́й безсильна врага́ сотвори́л єси́: укріпи́, Богоблаже́нне Мака́ріє, моли́твами твої́ми і нас, во всіх благи́х ізнемога́ющих, да сподо́бимся с тобо́ю воспіва́ти ви́ну піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я бога́тство чистоти́ душе́вния, і висоту́ смире́нія, роди́тельськоє бога́тство і рабо́в послуже́ніє ні во что же вміни́л єси́, і по разріше́нії плотська́го соу́за, і́мже на ма́лоє вре́м'я свя́зан бил єси́, я́ко олень жа́ждущий на істо́чники водни́я, устреми́лся єси́, всеблаже́нне, в пусти́ню: в не́йже твоє́ високородство на смиренному́дріє, бога́тство на убо́жество преміни́л єси́, совлеки́йся оде́жди многосві́тлия і облеки́йся в ру́бищі. Ті́мже удивля́ющеся таково́му твоєму́ смиренному́дрію, си́це ублажа́єм тя, вопію́ще:","Ра́дуйся, вся́ку го́рдость ми́ра презрі́вий.","Ра́дуйся, я́ко оста́вив вре́менная, взиска́л єси́ ві́чная.","Ра́дуйся, я́ко дом велелепний і черто́ги украшенни возненави́діл єси́.","Ра́дуйся, я́ко возлюби́л єси́ убо́гую хи́жину па́че черто́гов преізящних.","Ра́дуйся, я́ко ру́бищі украси́лся єси́ па́че оде́жди златотканния.","Ра́дуйся, я́ко вмі́сто бра́шен сластопитательних, возлюби́л єси́ ізнуря́ти плоть твою́ посто́м і мно́гим воздержа́нієм.","Ра́дуйся, я́ко не пожелал єси́ от рабо́в послуже́нія, но па́че сам послужи́ти всім ізво́лил єси́.","Ра́дуйся, я́ко возлюби́л єси́ па́че одра́ м'ягкаго на землі́ поверженіє.","Ра́дуйся, я́ко ві́рою пра́вою, а́ки щито́м, защитился єси́ от всіх іскуше́ній вра́жиїх.","Ра́дуйся, я́ко неістощимим терпі́нієм твої́м, па́че ко́пія острейшим, врага́ на́шего спасе́нія смерте́льно уязви́л єси́.","Ра́дуйся, я́ко неуси́пними твої́ми моли́твами, запина́теля на путі́ благоче́стія безсильна сотвори́л єси́.","Ра́дуйся, я́ко сто́лпе і утвержде́ніє доброді́телі нам яви́лся єси́.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю сумни́тельних помишле́ній укроща́я і пролагая в тишину́ Боже́ственними уче́нії, і́миже увіря́я себі́, я́же о Ца́рствії Небе́снім, преблаже́нне Мака́ріє, непреста́нно воспіва́л єси́ піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав преподо́бне Мака́ріє в Єва́нгелії глас Спаси́теля взивающ: і́же хо́щеть по Мні іти́, отве́ржеться себе́, і во́зьметь крест свой, і по Мні гряде́ть, отве́рглся єси́ себе́, і взем на рама́ крест твой, ходи́л єси́ по стопа́м Христо́вим невозвра́тно. Ті́мже ми, недосто́йнії, воспису́єм ті такова́я, глаго́люще:","Ра́дуйся, єва́нгельських велі́ній ві́рний блюсти́телю.","Ра́дуйся, Христо́вих слове́с тве́рдий храни́телю.","Ра́дуйся, креста́ своєго́ усе́рдний носи́телю.","Ра́дуйся, і́го Христо́во і бре́м'я Єго́ благоду́шно под'ємий.","Ра́дуйся, я́ко не обрати́вийся всп'ять в шествії ко Го́рнему Ієрусали́му.","Ра́дуйся, неізсяка́ємий сосу́де благода́ті Христо́ви.","Ра́дуйся, чи́стоє прия́телище Ду́ха Свята́го.","Ра́дуйся, я́ко вся стра́сті плотські́я воздержа́нієм мно́гим умертви́л єси́.","Ра́дуйся, вертогра́да Христо́ва всеусе́рдний насади́телю.","Ра́дуйся, я́ко ум твой к безстра́стію возви́сил єси́.","Ра́дуйся, вся блага́я землі́, Небе́снаго ра́ди Ца́рствія, за уме́ти вміни́вий.","Ра́дуйся, равноа́нгельноє житіє́ до конця́ возлюби́вий.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Бо́гом направляєм, всеблаже́нне о́тче, безмо́лвноє в пусти́ні житіє́ обрі́л єси́, і псало́мськи воспі́л єси́: се поко́й мой во вік ві́ка, зді вселю́ся: в не́йже і подвиза́лся єси́ до́бльственно в пості́ і бді́нії, і от о́чію мно́гі сле́зи ізлива́я, непреста́нно воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів су́єтних імі́ній рачи́тель неукло́нноє твоє́ в пусти́ні пребива́ніє, дия́вольським наущенієм возжига́єм, восхоті́ умертви́ти тя: но ра́ди постигшия єго́ сме́ртния болі́зні прише́л в чу́вство, паде́ пред нога́ма твої́ма, прося́ у тебе́ проще́нія і в пусти́ні с тобо́ю пребива́нія. Ти же я́ко па́стир до́брий і незло́бивий, прия́л єси́ єго́ с ра́достію, я́ко овча́ поги́бшеє, проща́я єму́ вся і причита́я єго́ к ізбра́нному твоєму́ ста́ду. Таково́є у́бо твоє́ незло́біє, і о спасе́нії заблу́ждших мно́гоє попече́ніє сли́шавше, по до́лгу воспіва́єм ті си́це:","Ра́дуйся, незло́бія при́сний храни́телю.","Ра́дуйся, смиренному́дрія і́скренній люби́телю.","Ра́дуйся, о́бразе кро́тости і терпі́нія.","Ра́дуйся, наста́вниче цілому́дрія.","Ра́дуйся, світоно́сний сто́лпе, просвіща́яй су́щия во тьмі.","Ра́дуйся, оби́телі і́ноков вели́коє украше́ніє.","Ра́дуйся, я́ко широ́кий путь, веду́щий в па́губу, ненави́діти поуча́л єси́.","Ра́дуйся, я́ко ті́сною і приско́рбною стезе́ю ше́ствовати благоїску́сно внуша́л єси́.","Ра́дуйся, дре́во благопло́дноє, при ісхо́дищах вод Боже́ственния благода́ті насажде́нноє, і мно́гі пита́ющеє.","Ра́дуйся, дре́во благосінноли́ственноє, мно́гі от зно́я прохлажда́ющеє.","Ра́дуйся, ізбра́ннаго твоєго́ стада́ стра́жу неуси́пний.","Ра́дуйся, благохотних подража́телей твої́х житіє́м і уче́нієм на Не́бо руководи́телю і сопутствователю.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дници би́ша твоєго́ незло́бія і прозорливости та́тіє, єгда́ похи́щенная і́ми живо́тная к тебі́ возврати́ша, і вмі́сто наказа́нія прия́ша от тебе́ оте́чеськоє наставле́ніє, ви́дівше же тако́є твоє́ незло́біє, со мно́гим удивле́нієм отше́дше, воспі́ша піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в пусти́ні, я́ко заря́ пресві́тлая, преподо́бне о́тче, просвіща́я і наставля́я на путь спасе́нія вся к тебі́ притекающия, сего́ ра́ди со мно́гим удивле́нієм взива́єм ті си́це:","Ра́дуйся, заре́ пресві́тлая, от пусти́ні восходя́щая і душі́ ві́рних озаря́ющая.","Ра́дуйся, заблу́ждших і́стинний наста́вниче.","Ра́дуйся, цілому́дрія зерца́ло.","Ра́дуйся, і́стинний о́бразе благоче́стія.","Ра́дуйся, алтаря Госпо́дня благогові́йний служи́телю.","Ра́дуйся, і́ночеськаго равноа́нгельнаго житія́ ревни́телю.","Ра́дуйся, безмо́лвія дре́вніх Богоно́сних оте́ць подража́телю.","Ра́дуйся, сто́лпе о́гненний, наставля́яй на путь спасе́нія.","Ра́дуйся, со́лнце світоза́рноє, я́ко свої́ми луча́ми душі́ на́ша, от мра́за гріхо́внаго погиба́ющия, согріва́єши.","Ра́дуйся, луна́ пресві́тлая, я́ко нощ на́шего неразу́мія прогоня́єши.","Ра́дуйся, Боже́ственнаго о людях промишле́нія всеусе́рдний служебниче.","Ра́дуйся, ві́чния на́шея ра́дости те́плий хода́таю.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ разсла́бленний Заха́рія соверше́нноє получи́ти себі́ здра́віє, моли́ принести́ себе́ і положи́ти пред нога́ма твої́ма, преподо́бне о́тче, да твої́ми моли́твами полу́чить ісціле́ніє. Ти же я́ко врач прему́дрий, уврачева́л неду́ги єго́ тіле́сния вку́пі же і душе́вния, воспі́л єси́ Го́споду благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє імі́л єси́ житіє́, і ди́вния чудеса́ сотвори́л єси́ на землі́, преподо́бне о́тче Мака́ріє, єгда́ узрі́в єди́наго ю́ношу, мно́гоє вре́м'я бісо́м му́чима, умили́вся прослези́лся єси́, і воздохну́в сотвори́л єси́ моли́тву к Бо́гу: а́біє же ізи́де біс із стра́ждущаго, і бисть здрав. Ми же такова́я сли́шавше, с ра́достію взива́єм ті си́це:","Ра́дуйся, лука́вих духо́в крі́пкий побіди́телю.","Ра́дуйся, душепа́губних волко́в прогони́телю.","Ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, ра́бе Бо́жий, благи́й і ві́рний.","Ра́дуйся, врачу́ ско́рий с ві́рою тебі́ призива́ющих.","Ра́дуйся, лозо́ благоплодови́тая.","Ра́дуйся, я́ко твої́м посо́бієм сокруша́ються ко́зні вра́жия.","Ра́дуйся, совоітелю прему́дрий, ратующим проти́ву сил а́дових.","Ра́дуйся, неоску́дний пото́к чудесе́м.","Ра́дуйся, оби́льний благода́тію істо́чниче ісціле́ній.","Ра́дуйся, трисо́лнечнаго сві́та пресві́тлая луче́.","Ра́дуйся, челові́че Бо́жий, преподо́бієм і і́стиною, а́ки по́ясом злати́м, пропоясанний.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Ди́вноє і неізрече́нноє чу́до благода́ті Небе́сния, явля́ється ни́ні во о́чію всіх ві́рних: долготерпіли́вий бо і многоми́лостивий Госпо́дь не прогні́вался на ни до конця́ за беззако́нія на́ша, но, пом'яну́в щедро́ти Своя́, дарова́ нам тебе́, досточу́дне о́тче, засту́пника ізря́дна, і та́ко вознесе́ рог спасе́нія на́шего, да ви́ну поє́м єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ во ви́шніх, но і ни́жніх не оставлявши, преподо́бне о́тче Мака́ріє, при́сно со Христо́м ца́рствуєши, і о нас, грі́шних, моли́тви к Нему́ возно́сиши: не то́чію бо припа́дающих к цільбоно́сним моще́м твої́м, но і дале́че отстоя́щих, призива́ющих же всечестно́є і́м'я твоє́, предста́тельством твої́м соблюда́єши от вся́каго зла. Ті́мже во умиле́нії зове́м ті:","Ра́дуйся, прибі́жище на́ше во всіх ско́рбіх.","Ра́дуйся, ско́рий помо́щнице всіх в біда́х су́щих.","Ра́дуйся, ціли́телю болі́зней душе́вних вку́пі і тіле́сних.","Ра́дуйся, на неви́димия враги́ на́ша си́льний побо́рниче.","Ра́дуйся, посіти́телю благосе́рдий в не́мощі лежа́щих.","Ра́дуйся, уті́шителю в печа́лі су́щих.","Ра́дуйся, я́ко тобо́ю престає́ть рида́ніє.","Ра́дуйся, я́ко тобо́ю подає́ться ра́дованіє.","Ра́дуйся, я́ко Христу́ до́бльственно послі́довал єси́.","Ра́дуйся, я́ко Сладча́йшему Ісу́су до конця́ послужи́л єси́.","Ра́дуйся, я́ко наслажда́єшися лицезрі́нія Бо́жия.","Ра́дуйся, я́ко сподо́бился єси́ зрі́ти невече́рній день Ца́рствія Єго́.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кия ско́рби претерпі́л єси́, і мно́гі труди́ і по́двиги до́бльственно соверши́л єси́, ше́ствуя по путі́ спасе́нія до масти́тия ста́рости, облече́н во всеору́жіє Бо́жиє, во пло́ті а́ки безпло́тен, умерщвля́я стра́сті і сокруша́я наві́ти миродержи́теля тьми ві́ка сего́, ті́мже к Небе́сним сопричи́слен си́лам, ку́пно с ни́ми воспіва́єши Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния недоумі́ють досто́йно восхвали́ти тя, богому́дре Мака́ріє: кто бо дово́лен разумі́ти вся боре́нія твоя́ с миродержи́тели тьми ві́ка сего́; іли́ кто ізочте́ть труди́, болі́зні і по́двиги твоя́, в них же пустиннолюбноє житіє́ соверша́л єси́; оба́че ми, любо́вію твоє́ю побіжда́єми, благода́рно тебі́ зове́м:","Ра́дуйся, зако́на Бо́жия ісполни́телю всеусе́рдний.","Ра́дуйся, чистото́ю і цілому́дрієм, многоці́ннаго би́сера честні́йший.","Ра́дуйся, в терпі́нії і боре́нії проти́ву пло́ті, адама́нта тверді́йший.","Ра́дуйся, смиренному́дрієм і кро́тостію па́че сла́вних землі́ просла́вленний.","Ра́дуйся, во пло́ті а́ки безпло́тен на землі́ пожи́вий.","Ра́дуйся, живи́ми і спаси́тельними слеза́ми огнь по́хоті угаси́вий.","Ра́дуйся, борющимся со страстьми́ і похотьми́ помо́щниче благоуспешний.","Ра́дуйся, в труді́х, бді́нії і воздержа́нії вели́ким по́стником подража́телю ревностнейший.","Ра́дуйся, в духо́вній му́дрости наста́вниче благоїскуснейший.","Ра́дуйся, по́двигов і́ночеських показа́телю рачительнейший.","Ра́дуйся, пустинножи́телей красота́.","Ра́дуйся, го́рлице пустинолю́бная і добровидная.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Храня́й вся ко́сті пра́ведних, я́ко ні єди́ній от них сокруши́тися, Госпо́дь і Бог наш Ісу́с Христо́с яви́л нам твоє́ ті́ло нетлі́нноє на землі́, преподо́бне о́тче, я́ко живоно́сную купі́ль, врачу́ющую вся́ку болі́знь і вся́ку я́зю в лю́діх. Ті́мже прия́вше такова́го ціле́бника і моли́твенника, благода́рственно вопіє́м єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тя тве́рду і моли́твенника ізря́дна стяжа́в свята́я оби́тель твоя́, і всі страни́ Росси́йстії хва́ляться заступле́нієм твої́м. Ті́мже і ми грі́шнії, яка ча́да отця́ мо́лим: заступи́ і сохрани́ нас от іскуше́ній і скорбе́й, бід і напа́стей моли́твами твої́ми, да взива́єм ті ра́достно:","Ра́дуйся, благово́нний кри́не ра́йськаго вертогра́да.","Ра́дуйся, кипари́сі, ві́рних се́рдця благово́нієм ісполня́яй.","Ра́дуйся, немощни́х ціле́бниче.","Ра́дуйся, же́зле, па́дающих подкрепляяй.","Ра́дуйся, наде́жде і оти́шіє в мо́рі житія́ сего́ пла́вающих.","Ра́дуйся, тве́рдоє огражде́ніє і прибі́жище усе́рдно Бо́гу рабо́тающих.","Ра́дуйся, всіх усе́рдно притека́ющих к тебі́, іскуше́ній і бід ско́роє ізбавле́ніє.","Ра́дуйся, всіх обурева́ємих покро́ве тве́рдий.","Ра́дуйся, я́ко от оби́телі земни́я в оби́тель Небе́сную пресели́лся єси́.","Ра́дуйся, я́ко от оби́телі Небе́сния в оби́тель земни́я благотворя́ нисхо́диши.","Ра́дуйся, я́ко і по отше́ствії твоє́м с на́ми пребива́єши.","Ра́дуйся, я́ко і по преставле́нії твоє́м, умерщвле́нния гріхми́ душі́ на́ша моли́твами твої́ми воскреша́єши.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́нія і пі́сні духо́вния Тро́йці Єдиносу́щній, се́рдцем і усти́ на землі́ ви́ну приноси́л єси́, блаже́нне Мака́ріє: ті́мже і ни́ні на Небесі́х, с а́нгельськими чи́ньми Тро́їчеському предстоя́ Престо́лу, непреста́нно воспіва́єши Боже́ственную піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоподательнаго світи́льника, просвіща́ющаго душі́ на́ша, ві́рою ви́дим тебі́, преблаже́нне о́тче, пред Престо́лом Бо́жиїм стоя́ща, і твої́м блиста́нієм озаря́ємі, зове́м ті такова́я:","Ра́дуйся, о́блаче світоза́рний, просвіща́яй душі́ на́ша.","Ра́дуйся, вода́ спаси́тельная, всіх напая́ющая.","Ра́дуйся, па́стирю преди́вний.","Ра́дуйся, учи́телю прему́дрий.","Ра́дуйся, чистоти́ селе́ніє.","Ра́дуйся, печа́льних утіше́ніє.","Ра́дуйся, си́рих пита́телю.","Ра́дуйся, оби́димих предста́телю.","Ра́дуйся, прему́дрости Бо́жия прия́телище.","Ра́дуйся, неісчерпа́ємий істо́чниче благода́ті ісціле́ній.","Ра́дуйся, превозвестниче Бо́жиїх велі́ній.","Ра́дуйся, сокро́вище милосе́рдія Бо́жия неістощи́моє.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше ті да́нную позна́вше, благогові́йно лобиза́єм честни́я мо́щі твоя́, я́же Госпо́дь благоволи́л ди́вно яви́ти нам. Ті́мже благода́рственно вопіє́м Христу́ Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ к Бо́гу отше́ствіє, преподо́бне Мака́ріє, почита́єм свяще́нную па́м'ять твою́, велича́єм твоє́ смиренному́дріє, хва́лим твоє́ долготерпі́ніє, сла́вим незло́біє твоє́, ублажа́єм по́двиги твоя́ і кончи́ну тече́нія твоєго́, я́ко віне́ць пра́вди прия́л єси́ от Го́спода, Судії́ пра́веднаго. Ті́мже моля́щеся усе́рдно, о є́же сподо́битися і нам неосужде́нно предста́ти Стра́шному Суди́щу Христо́ву, взива́єм ті:","Ра́дуйся, у Престо́ла Бо́жия те́плий о нас предста́телю.","Ра́дуйся, му́жу, просла́вивий Бо́га в душі́ і в ті́лі твоє́м.","Ра́дуйся, соверше́нний в доброді́теліх челові́че.","Ра́дуйся, ди́вний подража́телю Отця́ на́шего Небе́снаго.","Ра́дуйся, устрої́телю оби́телі мона́шествующих.","Ра́дуйся, преблаги́й і до́брий наста́вниче і́ноков.","Ра́дуйся, всіх правосла́вних ско́рий помо́щниче і засту́пниче.","Ра́дуйся, Царя́ Небе́снаго ізві́стний умилостиви́телю.","Ра́дуйся, мно́гажди заступле́нієм твої́м проше́нія предваря́яй.","Ра́дуйся, Небе́сний граждани́не.","Ра́дуйся, я́ко с преподо́бними і пра́ведними весели́шися.","Ра́дуйся, я́ко со всі́ми ізбра́нними Бо́жиїми при́сно торжеству́єши.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О, пресла́вний і преди́вний о́тче Мака́ріє, прийми́ благоутро́бно сіє́ ма́лоє моле́ніє на́ше, і твої́м си́льним і благоприя́тним пред Бо́гом хода́тайством, ізба́ви нас от всіх враг ви́димих і неви́димих, от вся́кия напа́сти і ско́рби, от внеза́пния сме́рти і бу́дущия муки́, да сподо́бимся с тобо́ю і со всі́ми святи́ми во ві́ки воспіва́ти Бо́гу Спаси́телю на́шему благода́рную піснь: Аллилу́я, Аллилу́я, Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела тя земна́го і челові́ка Небе́снаго, преподо́бне о́тче Мака́ріє, ки́їми пі́нії і пі́сньми восхва́лим, ки́їми вінці́ ув'язе́м трудолюбивую главу́ твою́, і ки́їми словеси́ возвели́чим многоболі́зненния по́двиги твоя́; ті́мже благогові́йно притека́юще к ра́ці многоціле́бних моще́й твої́х, усе́рдно припа́дающе, со умиле́нієм взива́єм ті:","Ра́дуйся, ре́вностний Христо́в подража́телю.","Ра́дуйся, за́повідей єго́ і́стинний блюсти́телю.","Ра́дуйся, а́нгелов собесі́дниче.","Ра́дуйся, преподо́бних похвала́.","Ра́дуйся, ві́рних слуге Госпо́день.","Ра́дуйся, усе́рдний чистоти́ і воздержа́нія храни́телю.","Ра́дуйся, сто́лпе терпі́нія.","Ра́дуйся, о́бразе незло́бія і кро́тости.","Ра́дуйся, смиренному́дрія наста́вниче.","Ра́дуйся, світи́льниче многосві́тлий.","Ра́дуйся, непости́дноє христия́н прибі́жище.","Ра́дуйся, безме́здний врачу́ немощству́ющих.","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче, і ізря́дний уго́дниче Христо́в, многоціле́бний істо́чниче і моли́твенниче о душа́х на́ших, преподо́бне о́тче Мака́ріє, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Мака́ріє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Мака́ріє! Не забу́ди убо́гих свої́х до конця́, но помина́й нас во святи́х свої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до своє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад свої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти своя́ духо́вния, я́ко імі́я дерзнове́ніє к Небе́сному Царю́. Не промолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних, у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу: і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо і ті́лом преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх, і вся́кия пре́лести бісо́вськия, і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ с а́нгельськими во́їнстви, с безпло́тними ли́ки, с Небе́сними Си́лами у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: є́же моли́тися о нас Всеси́льному Бо́гу о по́льзі душ на́ших і іспроси́ти вре́м'я на покая́ніє, і о невозбра́нном преі́тії от землі́ на Не́бо, мита́рств же го́рких, бісо́во возду́шних князе́й і ві́чния му́ки ізба́витися, і Небе́сному Ца́рствію наслі́дником би́ти со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отцо́м, і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Плотська́я мудрова́нія, о́тче Мака́ріє, / воздержа́нієм і бді́нієм умертви́л єси́, / мі́сто бо, на не́мже по́ти твоя́ ізлія́л єси́, / я́ко труба́ вопіє́ть к Бо́гу, / пові́дающи твоя́ ісправле́нія, / і по сме́рті честни́я твоя́ мо́щі істоча́ють ісціле́нія. / Ті́мже вопіє́м ті: // моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Ви́шніх жела́я, воздержа́нієм і труди́, і по́ти наслади́вся, / жела́ніє пло́ті твоєя́ обузда́в, / чуде́с дар приє́м от Христа́ Бо́га, / світи́льник яви́лся єси́ пресві́тлий. / Ті́мже Христо́ва Це́рков пі́сньми сла́вить тя, // преподо́бне Мака́ріє, о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Мака́ріє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Стефану, єпископу Пермському","e":"Akathist to St Stephen, Bishop of Perm","secs":[{"h":"Кондак 1","ps":["Возбра́нний святи́телю, учи́телю прему́дрий, равноапостольний Стефа́не, всім ві́рою к тебі́ прибегающим істоча́яй многоціле́бния да́ри, похва́льная воспису́єм ті любо́вію творя́щії па́м'ять твою́; ти же, імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгельськоє твоє́ во пло́ті житіє́ прови́дів всея́ тва́рі Созда́тель, от ю́ности твоєя́ угото́ва тя в сосу́д че́стен, ті́мже научи́ вопи́ти тебі́ си́це:","Ра́дуйся, трехлетней су́щей ма́тері твоє́й, блаже́нним Прокопієм святи́тель возвіще́нний;","ра́дуйся, пре́жде рожде́нія твоєго́ вели́ким прорече́нний.","Ра́дуйся, рожде́нієм свої́м роди́телей удиви́вий;","ра́дуйся, благочести́вих роди́телей богоприя́тноє іспрошеніє.","Ра́дуйся, от благочести́ваго ко́рене о́трасль святі́йшая;","ра́дуйся, в науче́нії кни́жнім па́че све́рстников просвіще́нний.","Ра́дуйся, в ю́ності ра́зум соверше́нний яви́вий;","ра́дуйся, ізмла́да Христа́ возлюбивший.","Ра́дуйся, яре́м Єго́ носи́вий;","ра́дуйся, мир і блага́я єго́ презрі́вий.","Ра́дуйся, плоть свою́ ду́хові покори́вий;","ра́дуйся, ізря́дноє благода́ті жили́ще.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя тщету́ мирськи́х попече́ній, блаже́нне Стефа́не, отше́л єси́ от до́му роди́телей твої́х, водворя́яся с работающими Бо́гу во і́ночестім житії́; тім же жизнь твою́ не ми́рові, но Бо́гу посвяти́л єси́, благоприя́тно Єму́ вопія́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум, плотсько́му челові́ку неуразумі́нний, от ю́ности твоєя́ стяжа́в, богому́дре Стефа́не, удиви́л єси́ талантами любому́дрія душі́ твоєя́. Ті́мже взива́єм ті си́це:","Ра́дуйся, о́бразе кро́тости духо́вния;","ра́дуйся, вмі́сто вре́менних благи́х ві́чная стяжа́вий.","Ра́дуйся, чистоти́ усе́рдний храни́телю;","ра́дуйся, терпі́нія богому́дрий учи́телю.","Ра́дуйся, братолю́бія зерца́ло;","ра́дуйся, по́стников первостоя́телю.","Ра́дуйся, моли́твами твої́ми ди́вная сотвори́вий;","ра́дуйся, і́ноком пра́вило благоче́стія.","Ра́дуйся, святи́телей собесі́дниче;","ра́дуйся, терпі́нієм ви́димих і неви́димих враго́в побіди́вий.","Ра́дуйся, ві́ри побо́рниче;","ра́дуйся, апо́столов подража́телю.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго, в душеспаси́тельних по́двизіх чу́дно укріпи́вшая тя, уго́дниче Христо́в Стефа́не, показа́ перм'яном пе́рваго пропові́дника Єва́нгелія, пото́м пе́рваго єпи́скопа і моли́твенника, да всі, просвіща́ємі сві́том доброді́телей твої́х, ди́вному во святи́х Свої́х Бо́гу взива́єм: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я да́нную ті от Бо́га благода́ть неду́ги отгоня́ти, бил єси́ па́стир до́брий, по гора́м нече́стія заблужда́ющих обріта́яй і на путь і́стинний направля́яй. Сего́ ра́ди, моли́твами твої́ми врачу́ємі, взива́єм ті:","Ра́дуйся, богоме́рзькаго ідолослуже́нія іскорени́телю;","ра́дуйся, єресе́й істребителю.","Ра́дуйся, правові́рія насади́телю;","ра́дуйся, заблужда́ющих наста́вниче.","Ра́дуйся, миролю́бцев обличи́телю;","ра́дуйся, сластолю́бцев наказа́телю.","Ра́дуйся, вражде́бних примири́телю;","ра́дуйся, малоду́шних уті́шителю.","Ра́дуйся, зло́би і за́висти історгателю;","ра́дуйся, к воздержа́нію путеводи́телю.","Ра́дуйся, к трезвенному житію́ наста́вниче;","ра́дуйся, во уни́нії закосневающих ісправи́телю.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю злих помисло́в прилі́жно от себе́ посто́м і моли́твами отража́я, яви́лся єси́ храм Ду́ха Свята́го, о Не́мже непреста́нно от ю́ности твоєя́ во вся́ком благоче́стії і чистоті́ пребива́я, обвикл єси́ воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав архієре́й Росто́вський Арсе́ній цілому́дренноє житіє́ твоє́ і тща́ніє во славосло́вії і воспеванії ди́вних діл Бо́жиїх, ді́йствующу і наставля́ющу Свято́му Ду́ху, призва́ тя в клир, і гра́да У́стюга в собо́рнім хра́мі проглаго́ла тя чтецем; пото́м во і́ночестім житії́ па́че іни́х потруди́вшася Коломенський архієре́й Гера́сим, приосененієм того́жде Свята́го Ду́ха, поста́ви тя дия́кона і пресви́тера, і в сем свяще́ннім досто́їнстві ді́йствієм Боже́ственния благода́ті показа́лся єси́ ми́рові до́брий наста́вник мона́хов і мирськи́х, да сла́в'яще Бо́га, в Тро́йці покланя́ємаго, взива́єм і тебі́:","Ра́дуйся, му́дрости небе́сния жили́ще;","ра́дуйся, ра́дости і́стинния прича́стниче.","Ра́дуйся, ми́ром небе́сним приосіне́нний;","ра́дуйся, долготерпі́нія іску́с стяжа́вий.","Ра́дуйся, ві́ри христия́нськия пра́вило;","ра́дуйся, бла́гости Боже́ственния струя́.","Ра́дуйся, кро́тости духо́вния до́блій храни́телю;","ра́дуйся, воздержа́нія учи́телю.","Ра́дуйся, соль ми́ра;","ра́дуйся, світи́льниче всесві́тлий.","Ра́дуйся, на сві́щниці нетлі́нія всім світи́ти поста́вленний;","ра́дуйся, гра́де, верху́ гори́ стоя́й.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ северовосточная яви́лся єси́, єгда́ просвіще́нія ра́ди сві́том богопозна́нія в і́дольськия землі́ текл єси́, да всі, позна́вше Творця́ вселе́нния, с на́ми єди́німи усти́ і єди́нім се́рдцем Єму́ вопію́ть: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів добро́ту душі́ твоєя́, мно́гими дарова́нії свиді́тельствуєму, архієре́й Гера́сим, по твоєму́ жела́нію снабдив для креще́нія люде́й і освяще́нія церкве́й потре́бними, с ра́достію отпусти́ тя во Вели́кую Перм. Ми же апо́стольство твоє́ честву́єм приві́тствії си́ми:","Ра́дуйся, апо́столов єдиноревнителю;","ра́дуйся, му́дрости сосу́де.","Ра́дуйся, разу́мноє світи́ло;","ра́дуйся, та́їн Бо́жиїх вещателю.","Ра́дуйся, кро́тости Єва́нгельськия о́бразе;","ра́дуйся, богові́дінія рачи́телю.","Ра́дуйся, благоче́стія сто́лпе;","ра́дуйся, стра́ха Бо́жия прия́телище.","Ра́дуйся, духо́вная труба́ Єва́нгелія;","ра́дуйся, орга́не псалмопі́нія і славосло́вія.","Ра́дуйся, прему́дрий наста́вниче;","ра́дуйся, ко блаже́нству ві́чному путеводи́телю.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник богові́дінія неленостен бил єси́ в неві́дущей Бо́га землі́, і благи́м свої́м житіє́м любо́в і благові́ріє к віща́нієм твої́м приобрі́л єси́ толи́коє, я́ко і неві́рнії, чту́ще до́брая діла́ твоя́, научи́шася тобо́ю взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ христия́нськоє благоче́стіє в землі́, растленней ідолослуже́нієм, єгда́ нача́л єси́ Боже́ственноє сі́м'я в безбо́жних сі́яти, і утвержда́я їх во ві́рі і́стинній приме́ром свої́м, всего́ себе́ посвяти́л єси́ Бо́гу; ми же похва́льная воспису́єм ті:","Ра́дуйся, во́лю, і́щущую нетлі́нія, стяжа́вий;","ра́дуйся, главу́ го́рнія му́дрости іспо́лнивий.","Ра́дуйся, земна́я мудрова́нія презрі́вий;","ра́дуйся, о́чі от мирськи́я пре́лести отврати́вий.","Ра́дуйся, уста́ на хвале́ніє Го́спода употреби́вий;","ра́дуйся, язи́ко к боже́ственній про́повіді устро́ївий.","Ра́дуйся, ру́ці простри́й на моли́тву і подая́ніє ми́лостині;","ра́дуйся, ті́ми же мно́жество книг душеспаси́тельних написа́вий.","Ра́дуйся, се́рдце твоє́ посто́м і моли́твою в жили́ще Ду́ха Свята́го угото́вавий;","ра́дуйся, но́зі ко бді́нію і благовіствова́нію ми́ра напра́вивий.","Ра́дуйся, все твоє́ ті́ло воздержа́нієм удручи́вий;","ра́дуйся, непреста́нним богоми́слієм ду́шу і ті́ло освяти́вий.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ та́йну ві́чнаго спасе́нія перм'яном пові́дати, потща́лся єси́ пе́рвіє нави́кнути несведомому їх словесі́ і близький к ним би́ти беседник; та́же соста́вив пи́сьмена і і́ми к назида́нію їх і службе Боже́ственній потре́бная ізобрази́в мно́гая писа́нія, дарова́л єси́ пособне пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і спаси́тельноє сли́шавше уче́ніє пермстії лю́діє, о́вії руга́хуся, о́вії же креще́нія прося́ху, і чудя́щеся ди́вному житію́ твоєму́, с уче́нієм, із уст ісходя́щим, согласному, просла́виша Бо́га; ти же потща́лся єси́ креще́нієм просвіща́ти лю́ди і к славосло́вії Бо́жию освяща́ти хра́ми. Сего́ ра́ди воспіва́єм тебі́:","Ра́дуйся, па́стирю до́брий;","ра́дуйся, Христо́в но́вий іспові́дниче.","Ра́дуйся, учи́телю прему́дрий;","ра́дуйся, апо́стольство твоє́ свя́то соверши́вий.","Ра́дуйся, і́дольськую лесть упраздни́вий;","ра́дуйся, луче́ сві́та Єва́нгельськаго.","Ра́дуйся, тьми заблужде́нія істребителю;","ра́дуйся, неві́рних уче́нієм свої́м удиви́вий.","Ра́дуйся, кро́тостію своє́ю го́рдость мирську́ю попра́вий;","ра́дуйся, о́вці Христо́ви во єди́но ста́до совокупи́вий.","Ра́дуйся, духо́вную па́ству твої́ми к Бо́гу благоприя́тними моли́твами оградивий;","ра́дуйся, всім призива́ющим тя ско́рий помо́щниче.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до показа́л єси́, богому́дре Стефа́не, преда́в огню́ скве́рную і́дольськую божницю, єгда́ с ра́зними ору́дії обступи́ша тя бісо́встії чтителе, уби́ти тя хотя́ще; ти же, моля́ся о обраще́нії заблужда́ющих, молчаливою кро́тостію сих побіди́л єси́, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь, Стефа́не пречу́дне, ті́лом і душе́ю посвятился єси́ Бо́гу, пребива́я в непреста́нних труді́х Боже́ственнаго богосло́вія і презира́я угроженія нечести́вих, претящих ті пропові́дати сла́ву Бо́жию. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, земни́й А́нгеле;","ра́дуйся, небе́сний челові́че.","Ра́дуйся, виті́я непобіди́мий;","ра́дуйся, во́їне Христо́в неустраши́мий.","Ра́дуйся, христия́нськаго благоче́стія і́стинний ревни́телю;","ра́дуйся, враго́в Це́ркве Христо́ви обличи́телю.","Ра́дуйся, нечести́вих виті́й посрами́телю;","ра́дуйся, сто́лпе, от нощі́ неві́дінія к Со́лнцю Пра́вди приводяяй.","Ра́дуйся, уста́ боже́ственная, ми́ру спасе́ніє возвіща́ющая;","ра́дуйся, гла́се небе́сния і́стини, бу́їх умудря́яй.","Ра́дуйся, неві́рних сві́том Єва́нгелія Христо́ва просвіти́вий;","ра́дуйся, подо́бно теплоті́ со́лнечній, олядені́вшая се́рдця їх согреявий і тім плод мног Це́ркві Бо́жієй принеси́й.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє возвесели́ся о твоє́м благоче́стії і чистоті́, о твоє́м му́жестві, терпі́нії, бді́нії в моли́твах, поще́нії і по Бо́зі ре́вности; во о́ніх бо претерпіва́я, я́ко безпло́тен яви́лся єси́. Ми же прославля́ющемуся чрез тебі́ Бо́гу взива́єм: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії безбо́жних, ча́ри творя́щії, онемеша, си́ла бо кре́стная превозмогаше всім їх волхвова́нієм. Ми же, ви́дівше на ви́димих і неви́димих враго́в побіди́тельная, усе́рдно вопіє́м ті:","Ра́дуйся, несумні́нною ві́рою ди́вная сотвори́вий;","ра́дуйся, живи́м на Бо́га Жива́го упова́нієм чти́телей бісо́вських посрами́вий.","Ра́дуйся, за любо́в к Бо́гу і бли́жнему ду́шу твою́ положи́вий;","ра́дуйся, крі́пости боже́ственния прия́телище.","Ра́дуйся, орга́не, возвіща́яй сла́ву Бо́жию;","ра́дуйся, гро́ме, устраша́яй соблазняющия.","Ра́дуйся, і́дольськия ле́сти істребителю;","ра́дуйся, дия́вольських ко́зней обличи́телю.","Ра́дуйся, го́рдості єго́ сокрушителю;","ра́дуйся, плоди́ трудо́в твої́х во сто уплодоносивий.","Ра́дуйся, неві́рних умудри́вий твої́ми нра́ви;","ра́дуйся, погиба́ющих руководствуяй ко прия́тію ві́чния сла́ви.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Пермськую зе́млю, всемі́рно потща́лся єси́ просвіти́ти ю святи́м Креще́нієм; пото́м свої́ма рука́ма і́долов раздробля́я і сокруша́я богомерзькая ка́пища, на развалинах їх це́ркві христия́нськия, монастири́ і училища дово́льная воздви́гл і научи́л єси́ Єди́ному Трийпоста́сному Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і укріпле́ніє в нече́стії перм'яном, пансотник волхв с ве́лією де́рзостію в со́нмищі глаго́л безу́мний утверди́: кто про́йдеть в зи́мнеє вре́м'я невреди́м водо́ю і кто огня́ не устраши́ться, того́ ві́ра єсть і́стинная і жертвоприношеніє Творцю́ не́ба і землі́ єсть прия́тноє. Ти же, смиренному́дрія віща́я глаго́ли, ко Всеви́шнему о по́мощі взива́л єси́, і ві́рою, вся возмощи́ о і́мені Єго́, стяжа́в упова́ніє, повлекл єси́ суємудраго волхва́ в пла́мень о́гненний. Он же, си́лою Бо́жиєю устрашенний, іспові́да пред всі́ми своє́ безси́ліє і малоду́шних обольще́ніє. І та́ко всея́ Пе́рмськия страни́ во ві́ру і́стинную сверши́ся обраще́ніє. Сего́ ра́ди блажи́м тя, прему́дре Стефа́не, си́ми:","Ра́дуйся, щиті́ Правосла́вія;","ра́дуйся, смиренному́дрія зерца́ло.","Ра́дуйся, вели́каго упова́нія о́бразе;","ра́дуйся, ковче́же чуде́с, Бо́гом устро́єнний.","Ра́дуйся, злочести́ваго волхва́ сла́вно препревий і із землі́ тоя́ ізгна́вий;","ра́дуйся, послі́дователі єго́ на путь і́стинний обрати́вий.","Ра́дуйся, кня́зя ми́ра сего́ посрами́вий;","ра́дуйся, жертвоприношенія і́дольськая упраздни́вий.","Ра́дуйся, труди́ перм'ян от ло́ва звіре́й їм в по́льзу сотвори́вий;","ра́дуйся, блага́я їх, вмі́сто душевре́днаго пред і́доли сожже́нія, в потре́бу їм і на слу́жбу челові́ком показа́вий, і та́ко страну́ їх умудри́вий.","Ра́дуйся, преді́ли россі́йськия про́повідію сло́ва Бо́жия разширивий;","ра́дуйся, не то́кмо вре́менная, но і ві́чная блага́я перм'яном откри́вий.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє прино́сим ті, святи́телю Стефа́не, єго́же, на возвратном із Пе́рми путі́ моля́щася Святі́й Тро́йці і благословля́юща оби́тель, преподо́бний Се́ргій Радонежський у́мнима очи́ма за ні́сколько поприщ прови́дів, благода́рним со бра́тією на трапе́зі почти́л єси́ поклоне́нієм. Ми же, всегда́шняго тя о душа́х на́ших стяжа́вше моли́твенника і щедро́ти твоя́ ізчести́ не могу́ще, благода́рними се́рдцем і усти́ Бо́гу, тобо́ю ді́йствующему всім ісціле́нія, взива́єм: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельний світи́льник су́щим во тьмі ідолослуже́нія, о́тче Стефа́не, яви́лся єси́, і до конця́ па́ству твою́ бо́дренно упа́сл єси́, огражда́я новопросвіще́нния лю́ди свої́ми к Бо́гу моли́твами і поставля́я із них сами́х па́стирей і учи́телей Пе́рми; посе́м, скончава́я тече́ніє твоє́, о не́мже проро́чеськи предсказа́л єси́, мо́щі твоя́ многоціле́бния ца́рствующему гра́ду Москві́ в зало́г моли́тв твої́х і те́плаго хода́тайства дарова́л єси́, ду́хом же со а́нгельськими чи́ньми лику́єши. Сего́ ра́ди восхваля́юще тя, глаго́лем:","Ра́дуйся, ду́хом везді́ ві́рния посіща́яй;","ра́дуйся, от а́дськия поги́белі ізимаяй.","Ра́дуйся, от сіте́й льсти́ваго ізбавля́яй;","ра́дуйся, вмі́сто вре́менних ві́чная бла́га нам подава́яй.","Ра́дуйся, врачу́, ра́ни гріхо́вния ісціля́яй;","ра́дуйся, вмі́сто сме́рті живота́ ві́чнаго хода́таю.","Ра́дуйся, неду́жних ціли́телю;","ра́дуйся, особенний Россі́ї храни́телю.","Ра́дуйся, всім прибегающим к тебі́ крі́пкоє забра́ло;","ра́дуйся, ца́рствующаго гра́да украше́ніє.","Ра́дуйся, світи́ло всероссі́йськоє;","ра́дуйся, А́нгелов собесі́дниче.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть цільби́ стяжа́вшаго, вели́каго во святи́теліх Стефа́на почти́м се́рдцем і усти́; і да вя́щшеє благи́м єго́ по́двигом воздади́м чествова́ніє, потщі́мся всемі́рно подража́ти єго́ доброді́телем, да благоприя́тно Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́, Стефа́не святи́телю, о призива́ющих тя в по́мощ те́плоє предста́тельство і от враго́во ви́димих і неви́димих ско́роє заступле́ніє, хва́лим тя всі, равноапостольний богопропові́дниче, і ві́руєм, я́ко Госпо́дь і Бог, пропові́данний тобо́ю в Пе́рми і прославля́ємий в тілесі́ твоє́м, моли́твами твої́ми вся нам да́рствуєть. Ті́мже вопіє́м ті:","Ра́дуйся, нището́ю духо́вною Ца́рство Небе́сноє получи́вий;","ра́дуйся, покая́нія і умиле́нія слеза́ми утіше́ніє ві́чноє прия́вий.","Ра́дуйся, кро́тостію землі́ но́вия наслі́діє прия́вий;","ра́дуйся, алкавий і жаждавий пра́вди, ни́ні насищаяйся.","Ра́дуйся, ми́лостинями обріти́й поми́лованіє;","ра́дуйся, чистото́ю се́рдця сподо́бивийся зрі́ти Бо́га.","Ра́дуйся, миротворе́нії Бо́гу усиновивийся;","ра́дуйся, терпі́нієм пра́вди ра́ди Ца́рство Небе́сноє стяжа́вий.","Ра́дуйся, поноше́ньми і претерпі́нієм всіх зол Христа́ ра́ди ублаживийся;","ра́дуйся, твої́м приме́ром нам путь ко спасе́нію откри́вий.","Ра́дуйся, моли́твами твої́ми труди́ і по́двиги облегчаяй;","ра́дуйся, предста́тельством твої́м у Христа́ Бо́га ві́чноє спасе́ніє нам подава́яй.","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий святи́телю, равноапостольний Стефа́не, ма́лоє сіє́ моле́ніє на́ше приє́м, умоли́ Подвигополо́жника і Соверши́теля Ісу́са, да ізба́вить ца́рствующий град і вся́кий град і страну́ христия́нськую от нахожде́нія іноплеме́нних, от єресе́й і раско́лов і от вся́кия напа́сти, і да і́зметь гряду́щия муки́ всіх, Єму́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськоє твоє́ во пло́ті житіє́ прови́дів всея́ тва́рі Созда́тель, от ю́ности твоєя́ угото́ва тя в сосу́д че́стен, ті́мже научи́ вопи́ти тебі́ си́це:","Ра́дуйся, трехлетней су́щей ма́тері твоє́й, блаже́нним Прокопієм святи́тель возвіще́нний;","ра́дуйся, пре́жде рожде́нія твоєго́ вели́ким прорече́нний.","Ра́дуйся, рожде́нієм свої́м роди́телей удиви́вий;","ра́дуйся, благочести́вих роди́телей богоприя́тноє іспрошеніє.","Ра́дуйся, от благочести́ваго ко́рене о́трасль святі́йшая;","ра́дуйся, в науче́нії кни́жнім па́че све́рстников просвіще́нний.","Ра́дуйся, в ю́ності ра́зум соверше́нний яви́вий;","ра́дуйся, ізмла́да Христа́ возлюбивший.","Ра́дуйся, яре́м Єго́ носи́вий;","ра́дуйся, мир і блага́я єго́ презрі́вий.","Ра́дуйся, плоть свою́ ду́хові покори́вий;","ра́дуйся, ізря́дноє благода́ті жили́ще."]},{"h":"Кондак 1","ps":["Возбра́нний святи́телю, учи́телю прему́дрий, равноапостольний Стефа́не, всім ві́рою к тебі́ прибегающим істоча́яй многоціле́бния да́ри, похва́льная воспису́єм ті любо́вію творя́щії па́м'ять твою́; ти же, імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, Стефа́не, вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О, Богоосвяще́нний і равноапостольний Стефа́не, но́вий богові́дінія пропові́дниче і просвіти́телю Креще́нієм святи́м великопе́рмських во ідолопокло́нстві живу́щих люде́й, ко і́стинному Єва́нгельському сві́ту путеводи́телю, па́стирю до́брий і учи́телю прему́дрий, Ду́ха Свята́го сосу́де ізбра́нний, Христоподража́тельний в Небе́сний Сіо́н наста́вниче і руководи́телю, о́браз благонра́вія всім благоче́стно жи́ти жела́ющим, благоїску́сний ми́сленнаго корабля́, чрез мо́ре ми́ра сего́ к Небе́сному приста́нищу пла́вающаго, прави́телю, ди́вний во ієра́рсіх, увінча́нний Боже́ственною благода́тію, всероссі́йський світи́льниче, вели́кий чудотво́рче і моли́твенниче те́плий! К тебі́ во умиле́нії душі́ і сокруше́нії се́рдця моєго́, аз окая́нний і грі́шний благонаде́жно притека́ю і вопію́, прося́ смире́нно по́мощі твоєя́ і те́плаго ко Преблаго́му Бо́гу хода́тайства, да твої́ми богоприя́тними моли́твами іспро́сиши мі от Него́ человіколю́бную ми́лость, оставле́ніє мно́гих мої́х согріше́ній, душі́ і тілесі́ здра́віє со спасе́нієм; і, я́ко Благ і Человіколю́бець, да благоволи́ть безбі́дно в ми́рі сем ходи́ти мі до сконча́нія живота́ моєго́, во вре́м'я же разлуче́нія моєго́ от жи́зні сея́ дух мой в покая́нії і ми́ре А́нгелом Свої́м святи́м ми́лостивно прия́ти, і да дасть мі ми́мо мра́чних і злокова́рних і лю́тих духо́в де́монських на возду́сі проіти́ невозбра́нно і к Нему́ непости́дно предста́ти поклони́тися, і безсме́ртния і блаже́нния жи́зні сподо́битися со всі́ми святи́ми во ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О, равноапостольний святи́телю Христо́в Стефа́не! К тебі́ ми, окая́ннії, благонаде́жно притека́єм і пред святи́м твої́м о́бразом вопіє́м, прося́ще по́мощі твоєя́ і к Бо́гу хода́тайства, да твої́ми моли́твами іспро́сиши нам, раба́м Бо́жиїм (імена́), от Него́ ми́лость: оставле́ніє мно́гих на́ших согріше́ній, душа́м і тілесе́м здра́віє со спасе́нієм; да благоволи́ть же Госпо́дь твої́ми моли́твами безбі́дно в ми́рі сем ходи́ти нам до сконча́нія житія́ на́шего, во вре́м'я же разлуче́нія на́шего от жи́зні сея́ дух наш А́нгели Свої́ми в покая́нії і ми́ре ми́лостивно да при́йметь, я́ко да от мра́чних і злокова́рних і лю́тих духо́в де́монських на возду́сі проше́дше невозбра́нно, к Нему́ непости́дно предста́нем і поклоні́мся, і безсме́ртния і блаже́нния жи́зні сподо́бимся, со всі́ми святи́ми, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Боже́ственним жела́нієм / от ю́наго во́зраста, Стефа́не прему́дре, разже́гся, / яре́м Христо́во взял єси́ / і люде́й олядені́вшая дре́вле неві́рієм сердца́, / Боже́ственноє сі́м'я в них сі́яв, / єва́нгельськи духо́вні породи́л єси́. / Ті́мже пресла́вную твою́ па́м'ять почита́юще, мо́лим тя: / моли́, Єго́же пропові́дал єси́, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Самозва́нен не і́щущим тебі́, святи́телю, обрі́лся єси́, / лю́ди, от і́дольськия ле́сти свободи́в, ко Христо́ві ві́рі приве́л єси́ / і волхва́ пансо́тника посрами́л єси́, / ті́мже і пе́рвий єпи́скоп і учи́тель Пе́рми бил єси́. / Сего́ ра́ди духо́вная твоя́ ча́да, / я́ко тобо́ю ізба́вльшеся от і́дол, благода́рная тебі́ возопіє́м: // ра́дуйся, Стефа́не, учи́телю прему́дрий."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Стефа́не, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Корнилію, ігумену Комельському","e":"Akathist to our Venerable Father Cornelius, Abbot of Komel","secs":[{"h":"Кондак 1","ps":["Ізбра́нний воєво́до, Бо́гом вруче́ннаго тебі́ полка́ во́їнов духо́вних, і преди́вний в чудесі́х, преподо́бне о́тче наш Корни́ліє! Восхваля́єм по́двиги твоя́ в пі́сніх хвалебних, і мо́лим ті ся приле́жно: я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся ви́ну о спасе́нії нас грі́шних, і моли́твами твої́ми богоприя́тними, от вся́ких нас бід, вре́менних і ві́чних, свободи́, да зове́м ті:","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела земна́го і челові́ка небе́снаго, яви́ нам тебе́ всея́ тва́рі Зижди́тель, преподо́бне о́тче Корни́ліє: прови́дів бо благопло́діє душі́ твоєя́, от ю́них літ ізбра́ тя служи́ти Єму́ в преподо́бії і чистоті́, нам же, чту́щим тя, внуша́єть вопи́ти к тебі́:","Ра́дуйся, благоро́дних роди́телей си́не боголюбе́зний.","Ра́дуйся, благочести́вия чети́ прозябе́ніє благода́тноє.","Ра́дуйся, от младе́нчества на слу́жбу Бо́гові освяще́нний.","Ра́дуйся, от ю́ности на по́двиги духо́вния предизбранний.","Ра́дуйся, сві́тлость са́на болярськаго Христа́ ра́ди презрі́вий.","Ра́дуйся, служи́ти Царю́ Небе́сному преі́скренні восхоті́вий.","Ра́дуйся, сего́ ра́ди слу́жбу царю́ земно́му оста́вивий.","Ра́дуйся, на по́двиги поста́ і моли́тви ре́вностно потекий.","Ра́дуйся, в оби́телі преподо́бнаго Кири́лла во і́ночество постриженний.","Ра́дуйся, в послуша́нії ста́рцю твоєму́ зіло́ преуспі́вий.","Ра́дуйся, труди́ вели́кия в хлебні нелі́ностно соверши́вий.","Ра́дуйся, вери́ги тя́жкия на ті́лі твоє́м носи́вий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дів Госпо́дь твоя́ по́двиги, бді́нія, сухояде́нія і моли́тви, преподо́бне о́тче, осіни́ тя боже́ственною благода́тію, і дарова́ ті си́лу і крі́пость, труди́тися в послушаніїх монасти́рських сугу́бо проти́ву други́х бра́тій, ї́хже не́мощі с любо́вію носи́л єси́, і уроки їм да́нния в рабо́тах за них ісполня́л єси́, нощі́ же в моли́твах коленопреклоненних провожда́л єси́, зови́й немо́лчно Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум духо́вний тебі́ сви́ше дарова́ Бог, досточу́дне о́тче, і́мже до́брі разсужда́л єси́, что єсть во́ля Бо́жия і что во́ля челові́чеськая; пе́рвій у́бо всеці́ло повину́л єси́, втори́я же вся́чеськи ізбегал єси́ послу́шати, і бил єси́ і́стинний уго́дник Бо́жий, досто́йний нелестних похва́л такови́х:","Ра́дуйся, чудоточнаго дре́ва преподо́бнаго Кири́лла о́трасле благопло́дная.","Ра́дуйся, оби́телі єго́ святи́я питомиче Бо́гом просла́вленний.","Ра́дуйся, і́ноче богоуго́дний, Бо́гу, а не челові́ком угождавий.","Ра́дуйся, смире́нієм висо́кая стяжа́вий.","Ра́дуйся, Писа́ній боже́ственних нелі́ностний ізучителю.","Ра́дуйся, книг душеспаси́тельних трудолюби́вий списа́телю.","Ра́дуйся, в снисканії му́дрости духо́вния с любо́вію подвиза́вийся.","Ра́дуйся, доброді́телі дре́вніх богоно́сних оте́ць себі́ усво́ївий.","Ра́дуйся, словеса́ і уче́нія їх в се́рдці твоє́м запечатлі́вий.","Ра́дуйся, я́ко пчела́ мед неги́блющий богому́дренно собиравий.","Ра́дуйся, бразду́ душе́вную до́брі возделавий.","Ра́дуйся, слеза́ми моли́твенними ни́ву серде́чную уплодоносивий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю руководи́мий, оста́вил єси́, о́тче Корни́ліє, оби́тель, тебі́ духо́вно воспита́вшую, і я́ко муж соверше́н, по́двиг стра́нничества Бо́га ра́ди на ся восприя́л єси́, оби́телі і́ночеськия обходя́, і в них житію́ духо́вному поуча́яся, да возмо́жеши се́рдцем і усти́ благоприя́тно воспіва́ти Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист і непоро́чную ду́шу, преподо́бне о́тче, вся до́брая і душеполе́зная, в стра́нствії твоє́м ви́дінная і слишанная, слагал єси́ в се́рдці твоє́м, і ті́ми поуча́лся єси́ богоугожде́нію і́стинному, єго́же верх — свята́я люби́. Сію́ у́бо себі́ усво́їв па́че іни́х доброді́телей, ві́рний подража́тель Христо́в бил єси́, і не́мощі немощни́х любвеобильно носи́л єси́, во є́же всім зва́ти тебі́:","Ра́дуйся, богому́дрий стра́нниче.","Ра́дуйся, Христо́в ізбра́нниче.","Ра́дуйся, кра́снії но́зі твої́ в путь спаси́тельний напра́вивий.","Ра́дуйся, стра́нствіє воі́стину душеполе́зноє соверши́вий.","Ра́дуйся, от Новоградськаго святи́теля Генна́дія любо́вію о Христі́ почте́нний.","Ра́дуйся, превозноше́нія челові́чеськаго ізбегавий.","Ра́дуйся, в пусти́ню от по́честей земни́х сокривийся.","Ра́дуйся, в мі́ста неудобопроходимая удали́вийся.","Ра́дуйся, смире́нія стяжа́телю.","Ра́дуйся, кри́не пусти́ннаго прозябе́нія.","Ра́дуйся, ма́слино небе́снаго насажде́нія.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю скорбе́й пусти́нних му́жественно претерпі́л єси́, подви́жниче Бо́жий, і преходя́ от мі́ста к мі́сту, Комельськия пусти́ні дости́гл єси́, іді́же в обита́лищі разбо́йников небоя́зненно всели́лся єси́, мі́сто, беззако́нії оскверне́нноє очи́стив і освяти́в, на не́мже денноно́щно возноси́л єси́ хвали́ Бо́гу, і піл єси́ Єму́ во умиле́нії глубо́цім: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше разбо́йници твоє́ їм ізобличеніє, і ви́дівше небоя́зненноє му́жество душі́ твоєя́, я́ко преще́нія їх не устраши́лся єси́, гото́в сий смерть прия́ти от рук їх ра́достно, оста́виша тя в поко́ї, служи́ти Бо́гу на ізбранном ті мі́сті, іді́же ни́ні честву́єм тя, взива́юще тебі́ си́це:","Ра́дуйся, пусти́нниче, земни́х пристра́стій чужди́й.","Ра́дуйся, по́стниче, умертви́вий стра́сті воздержа́нієм.","Ра́дуйся, му́жество крі́пкоє о Христі́ яви́вий.","Ра́дуйся, враги́ неви́димия до конця́ побіди́вий.","Ра́дуйся, разбо́йничеськоє жили́ще в селе́ніє Бо́жиє претвори́вий.","Ра́дуйся, разбо́йников преще́нія ні во что же вміни́вий.","Ра́дуйся, любо́вію зло́бу побіди́вий.","Ра́дуйся, смире́нієм не́нависть укроти́вий.","Ра́дуйся, разбо́йников, ограбивших тя, вразуми́вий чуде́сно.","Ра́дуйся, кни́ги твоя́, і́ми похищенния, возврати́вий пресла́вно.","Ра́дуйся, учи́телю благоче́стія.","Ра́дуйся, наста́вниче богому́дрія.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Боготечноє світи́ло бив, сія́нієм доброді́тельнаго житія́ твоєго́ привле́кл єси́ в пусти́ню Комельськую пустиннолюбивия і́ноки, сожи́тельствовати тебі́, преподо́бне о́тче: ти же по глаго́лу Христо́ву, гряду́щих к тебі́ не ізгонял єси́, но с любо́вію прийма́л єси́; і та́ко в пусти́ні твоє́й устро́їся оби́тель свята́я, в не́йже і́ноков лик, тобо́ю управля́ємий, поя́ше Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя ученици́ твої́ богоно́сна і равноа́нгельна житіє́м, возжелаша сооруди́ти храм Бо́жий на мі́сті по́двигов твої́х пусти́нних, преподо́бне о́тче, ї́хже жела́ніє ісполня́я, храм пе́рвий, во і́м'я Богома́тере, в пусти́ні твоє́й построїл єси́, свої́ма рука́ма в ді́лі построєнія єго́ тружда́яся. Сія́ труди́ твоя́ воспомина́юще, свя́тче Бо́жий, прино́сим ті пі́ніє таково́є:","Ра́дуйся, подви́жниче соверше́нний.","Ра́дуйся, трудолю́бче нелицемі́рний.","Ра́дуйся, усе́рдний слуго́ Ма́тере Го́спода на́шего.","Ра́дуйся, во і́м'я Єя́ свято́є храм Бо́жий в оби́телі твоє́й сооруди́вий.","Ра́дуйся, Єя́ покро́ву благода́тному оби́тель твою́ препоручивий.","Ра́дуйся, помо́щницю Ю во всем всегда́ імі́вий.","Ра́дуйся, пусти́нний жи́телю, гра́ди і ве́сі іспо́лнивий сла́вою до́брих діл твої́х.","Ра́дуйся, селе́ніє разбо́йников наполнивий подви́жники благоче́стія.","Ра́дуйся, пусти́ню в град претвори́вий.","Ра́дуйся, дебр неудобопроходимую іноками населивий.","Ра́дуйся, мно́гі ско́рби і біє́нія от разбо́йников претерпі́вий.","Ра́дуйся, нищету́ духо́вную зіло́ возлюби́вий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник Бо́жий бил єси́ бра́тії твоє́й, о́тче преподо́бне: рукоположе́ніє бо свяще́нноє восприє́м от митрополи́та Си́мона, олтарю́ Госпо́дню благогові́йно служи́л єси́, і та́їн Христо́вих соверши́тель непоро́чен бил єси́, поуча́я нелі́ностно ученики́ твоя́, сло́вом і приме́ром твої́м, богоугожде́нію і́стинному і пі́нію хвалебному Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в пусти́ні Комельськой сві́том до́брих діл твої́х, блаже́нне о́тче, о ни́хже прославля́шеся на землі́ Оте́ць Небе́сний – Бог наш: ни́щия пита́л єси́, стра́нники упокоєва́л єси́, больни́я врачева́л єси́, і вся́кому просившему у тебе́ в ну́жді, доброхотен да́тель бил єси́. Ті́мже сли́шиши благохвале́нія сицева́я:","Ра́дуйся, Авраа́мле страннолю́біє возлюби́вий.","Ра́дуйся, апо́стольськоє нищелю́біє себі́ усво́ївий.","Ра́дуйся, всім бі́дствующим усе́рден помо́щник би́вий.","Ра́дуйся, хліб твой с убо́гими разделявий.","Ра́дуйся, странноприї́мницю і больни́цю в оби́телі твоє́й устро́ївий.","Ра́дуйся, чин і уста́в общежительний ученико́м твої́м начерта́вий.","Ра́дуйся, Анто́нія Вели́каго по́двигом пусти́нним подража́вий.","Ра́дуйся, во і́м'я єго́ храм в оби́телі твоє́й сооруди́вий.","Ра́дуйся, виді́нієм єго́ чуде́сним уті́шенний.","Ра́дуйся, обітова́нія блага́я от уст єго́ усли́шавий.","Ра́дуйся, молчаливая уста́ імі́вий.","Ра́дуйся, псалмопі́нію всегда́ прилежавий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Хоті́ніє імі́л єси́, преподо́бне, в безмо́лвії ненарушимом рабо́тати Христу́ Бо́гу: сего́ ра́ди с люби́мим ученико́м твої́м преподо́бним Генна́дієм удали́лся єси́ в пусти́ню на є́зеро Сурськоє, на мі́сто безмо́лвноє і удаленноє от жили́щ челові́чеських, іді́же в по́двизіх отшельничеських до́брі подвиза́лся єси́, зови́й немо́лчно Спа́су Христу́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вим по́двигом духо́вним вдал єси́ себе́, уго́дниче Бо́жий, в пусти́ні Сурстей, і труди́ ко трудо́м прилага́л єси́, удруча́я плоть твою́ посто́м, бді́нієм, колінопреклоне́нієм, до́лу лега́нієм і моли́твами непреста́нними, я́ко диви́тися ученику́ твоєму́ Генна́дію таково́му житію́ твоєму́ і ре́вности твоє́й о спасе́нії душе́внім, я́же і нас во удивле́ніє приво́дять і подвиза́ють зва́ти тебі́:","Ра́дуйся, пусти́ннаго безмо́лвія возжелі́вий.","Ра́дуйся, молви́ челові́чеськія уклони́вийся.","Ра́дуйся, проро́ку Бо́жию Ілії́ по́двиги пусти́нними подража́вий.","Ра́дуйся, Предте́чі Госпо́дню Іоа́нну житіє́м отшельничеським послі́довавий.","Ра́дуйся, мно́гі ча́да о Христі́ духо́вно воспита́вий.","Ра́дуйся, к богоугожде́нію і́стинному ученики́ твоя́ наста́вивий.","Ра́дуйся, преподо́бнаго Кири́лла Новоєзе́рськаго во і́ночество постригий.","Ра́дуйся, преподо́бнаго Генна́дія Любимогра́дськаго во а́нгельський о́браз облеки́й.","Ра́дуйся, і́ночества богоуго́днаго в преді́ліх Волого́дських распространителю.","Ра́дуйся, оби́телей пусти́нних основа́телю.","Ра́дуйся, звіздо́ пресві́тлая в ли́ці преподо́бних Россі́йських.","Ра́дуйся, благода́тная красото́ святи́я Христо́ви Це́ркве.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нствуя в пусти́ні Сурстей, преподо́бне о́тче, в сиротстві оста́вил єси́ оби́тель твою́ Комельськую, єя́же сиротство уви́дів вели́кий князь Васи́лій, сожале о ней і повелі́ тебі́ возврати́тися в ню на пре́жнєє твоє́ настоя́тельство, да управля́єши оби́телію, тобо́ю основанною і усовершенною: ти же послушли́в сий во́лі Бо́жієй, в повелі́нії благові́рнаго кня́зя тебі́ явле́нній, со усе́рдієм в оби́тель Комельськую возврати́лся єси́, і ра́дость ве́лію сим бра́тії твоє́й сотвори́л єси́, во є́же вопи́ти їм благода́рними гла́си ко Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив богоми́слієм моли́твенним непреста́нним, преподо́бне о́тче Корни́ліє, і бли́жніх твої́х о Бо́зі зіло́ возлюби́л єси́, найпа́че же ни́щих і стра́ждущих, ме́ньших о Христі́ бра́тій твої́х, ї́хже во вре́м'я гла́да щедродательно пита́л єси́, вся́кому нуждающемуся ми́лостиню неоску́дно подава́л єси́, і ма́лия ді́ти любвеобильно призревал єси́, как оте́ць чадолюби́вий. Ті́мже тебе́ подража́телю милосе́рдія Спасова, вопіє́м хвале́бно:","Ра́дуйся, преподо́бне, преподо́бієм христоподража́тельним украше́нний.","Ра́дуйся, богоно́сне, Бо́га і бли́жняго твоєго́ соверше́нно возлюби́вий.","Ра́дуйся, ни́щих пита́телю.","Ра́дуйся, стра́нних упокоїтелю.","Ра́дуйся, стра́ждущих уті́шителю.","Ра́дуйся, вдов і сиро́т защити́телю.","Ра́дуйся, всяк во́зраст ві́рних ми́лостинею твоє́ю снабдевавий.","Ра́дуйся, ма́лия ді́ти любо́вію твоє́ю о Христі́ взиска́вий.","Ра́дуйся, во дні гла́да от житниць твої́х мно́гія препита́вий.","Ра́дуйся, утро́бу щедро́т твої́х ску́постію не загради́вий.","Ра́дуйся, наде́жду несумні́нную на Бо́га возлагавий.","Ра́дуйся, по ві́рі і моли́тві твоє́й, от Бо́га препита́ніє неоску́дно получи́вий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Вся доброді́телі іспо́лнив і соверше́нно Бо́гу угоди́в, преблаже́нне о́тче, в ста́рости масти́тій сий, па́ки оста́вил єси́ жезл настоя́тельства в оби́телі твоє́й, і на поко́й отше́л єси́ в оби́тель Кириллову, да іді́же постри́жен бил єси́ в і́ночество, та́мо і сконча́єши по́двиг житія́ свята́го. Оба́че ученики́ твої́ми умоле́нний, і́же не терп'я́ху ско́рби разлуче́нія с тобо́ю, к ним возврати́лся єси́ в оби́тель Комельськую, і в ней в безмо́лвії келейном пребива́л єси́, благоприя́тно поя́ Бо́гу піснь хвали́ і благодаре́нія: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть ко ізглаголанію мно́гих по́двигов богоуго́днаго равноа́нгельнаго житія́ твоєго́, преподо́бне о́тче Корни́ліє: в ста́рости глубо́цій неосла́бно і нелі́ностно подвиза́лся єси́ в моли́твах, бді́ніїх і поще́ніїх, гото́в'яся ко ісхо́ду твоєму́ і преселе́нію во вечность. Сего́ ра́ди тебе́, до́брому подви́жнику Христо́ву, смиренному́дренно прино́сим сія́ пі́сні хвале́бния:","Ра́дуйся, і́стинний уго́дниче Бо́жий, ві́ру до конця́ сохрани́вий.","Ра́дуйся, ізбра́нний слуго́ Госпо́день, наде́жду несумне́нну стяжа́вий.","Ра́дуйся, равноа́нгельний челові́че, любо́в святу́ю себі́ усво́ївий.","Ра́дуйся, послі́дователю єва́нгельськаго уче́нія, вся за́повіді єго́ соверши́вий.","Ра́дуйся, в ста́рости масти́тій ю́ность духо́вную проявивий.","Ра́дуйся, в безмо́лвії моли́твенном духо́вно созревий.","Ра́дуйся, к ісхо́ду сме́ртному до́брі себі́ приуготовивий.","Ра́дуйся, с горя́щим світи́льником до́брих діл Жениха́ Небе́снаго срі́сти гото́вий.","Ра́дуйся, свято́є і́м'я Го́спода Ісу́са в се́рдці і усті́х твої́х всегда́ імі́вий.","Ра́дуйся, І́менем тім Боже́ственним ісціле́нія боля́щих соверша́вий.","Ра́дуйся, благода́тію целебною сви́ше обогащенний.","Ра́дуйся, да́ром прозорли́вства от Го́спода одаренний.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спасе́нія душе́внаго во упова́нії бив, свя́тче Бо́жий, ми́рно і ра́достно возлежал єси́ на одрі́ сме́ртнім, послі́днєє цілова́ніє і благослове́ніє подава́я бра́тії твоє́й, і́же го́рко пла́каху о разлуче́нії с тобо́ю: ти же плач їх утоля́я, і по сме́рті обіща́лся єси́ ду́хом твої́м не разлуча́тися с ни́ми, і не оставля́ти оби́тель твою́, а́ще то́кмо соблюду́ть за́повіді твоя́ і уста́в тобо́ю їм оста́вленний, в не́мже поуча́єши благоугожда́ти Бо́гу і досто́йно возноси́ти Єму́ трисвяту́ю піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ Бо́га раб би́вий, преподо́бне о́тче, в ру́ці Єго́ Святи́я ми́рно і безм'яте́жно пре́дал єси́ чи́стую твою́ ду́шу, ті́ло же твоє́ многоподвижноє, в наслі́діє целебноє оби́телі твоє́й оста́вил єси́, в не́йже о́но че́стно погребе́ся, і то́ки чуде́с істоча́єть от ра́ки твоєя́. Покланя́ющеся мі́сту посмертнаго поко́я твоєго́, свя́те, умиле́нно тебі́ вопіє́м:","Ра́дуйся, кончи́ну пра́ведную получи́вий.","Ра́дуйся, непости́дно і свя́то тече́ніє твоє́ сконча́вий.","Ра́дуйся, во благоуха́нії святи́ні сном сме́ртним опочивий.","Ра́дуйся, со слеза́ми мно́гими от них погребе́нний.","Ра́дуйся, в хра́мі Богома́тере, тобо́ю созда́нном, положе́нний.","Ра́дуйся, под кро́вом Цари́ці Небе́сния посмертний поко́й ті́лу твоєму́ обріти́й.","Ра́дуйся, душе́ю твоє́ю свято́ю в оби́телі ра́йськия к Ней воспаривий.","Ра́дуйся, от Си́на Єя́ і Бо́га вінце́м безсме́ртния жи́зні почте́нний.","Ра́дуйся, лико́м святи́х, Престо́лу Єго́ предстоя́щих, сопричтенний.","Ра́дуйся, чудеси́ мно́гими по сме́рті свя́тость твою́ ознаменовавий.","Ра́дуйся, от ра́ки твоєя́ честни́я ісціле́нія благода́тния істочи́вий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє, у свята́го гро́ба твоєго́ соверша́ємоє, уго́дниче Бо́жий, ми́лостивно приє́млеши, і с ві́рою приходя́щим на поклоне́ніє многоціле́бним моще́м твої́м да́ри благода́тними воздає́ши, больни́м ісціле́ніє, скорб'я́щим утіше́ніє, бі́дствующим вспоможе́ніє да́руя, моли́твенним предста́тельством твої́м у Престо́ла Го́спода Сла́ви, Єму́же со святи́ми поє́ши: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с твої́х, преподо́бне о́тче Корни́ліє, оби́тель твою́ просвіща́єши, і всю страну́ Россі́йськую благода́тно озаря́єши, я́ко сла́вити тя бли́жнім і да́льним, пресла́внаго чудотво́рця. Ті́мже і ми грі́шнії, заступле́нія моли́твеннаго твоєго́ прося́ще, с ві́рою і любо́вію прославля́єм тя по до́лгу благохвале́нії си́ми:","Ра́дуйся, ціле́бниче безме́здний неду́гов душе́вних і тіле́сних.","Ра́дуйся, помо́щниче ско́рий і преди́вний на по́мощ тя призива́ющим.","Ра́дуйся, сліпи́м прозрі́ніє ми́лостивий пода́телю.","Ра́дуйся, разсла́бленних ті́лом благода́тний укріпи́телю.","Ра́дуйся, в со́ніїх і виді́ніїх ві́рния посіща́яй.","Ра́дуйся, боля́щим здра́віє явле́нієм твої́м подава́яй.","Ра́дуйся, неду́жнаго боля́рина Симео́на пред мно́гими пресла́вно ісціли́вий.","Ра́дуйся, свіщу́ у гро́ба твоєго́ чуде́сно воспламенивий.","Ра́дуйся, лю́ті страда́вшаго і́нока Корни́лія от мучительнаго неду́га ізба́вивий.","Ра́дуйся, нога́ми болезновавшаго Мокі́я пра́во ходи́ти устро́ївий.","Ра́дуйся, бесноватаго Проко́пія от дия́вольськаго муче́нія свободи́вий.","Ра́дуйся, ізступленнаго умо́м Се́ргія здра́вим сми́слом одаривий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть мно́гих чуде́с, от Бо́га тебе́ дарова́нную, преподо́бне уго́дниче Христо́в, сли́шав святі́йший патріа́рх Всероссі́йський І́ов, собо́рні установі пра́здновати святу́ю па́м'ять твою́ во всей Правосла́вной Всероссійськой Це́ркві, я́ко воі́стину Бо́гом просла́вленнаго чудотво́рця. Таково́є прославле́ніє твоє́ в ли́ці святи́х со утіше́нієм воспомина́юще, благода́рственно вопіє́м Ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м мно́гая і пресла́вная чудотворе́нія твоя́, преподо́бне о́тче Корни́ліє, в ни́хже ви́дим вели́кую ми́лость Бо́жию к страні́ Росси́йстій, такова́го чудотво́рця возрасти́вшей, і усе́рдно благодари́м благи́х пода́теля Го́спода, си́це благоді́ющаго Оте́чествію на́шему, тебі́ же, небе́сному засту́пнику на́шему, уми́льно глаго́лем:","Ра́дуйся, дру́же Христо́в, до конця́ ві́рен преби́вий.","Ра́дуйся, сожи́телю святи́х, при́сний Бо́гу.","Ра́дуйся, таї́нниче Пресвяти́я Тро́йці.","Ра́дуйся, ізбра́нний слуго́ Пресвяти́я Богоро́диці.","Ра́дуйся, а́нгельських во́їнств собесі́дниче.","Ра́дуйся, преподо́бних украше́ніє.","Ра́дуйся, сосу́де боже́ственния благода́ті.","Ра́дуйся, сокровищнице даро́в Свята́го Ду́ха.","Ра́дуйся, чуде́с ріко́ приснотеку́щая.","Ра́дуйся, сосу́де ми́ра целебнаго преіспо́лненний.","Ра́дуйся, тіле́с на́ших врачу́ Бо́гом дарова́нний.","Ра́дуйся, о душа́х на́ших моли́твенниче богоприя́тний.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий і пресла́вний чудотво́рче, преподо́бне о́тче Корни́ліє! При́зри от го́рних висо́т оби́телей ра́йських на нас земни́х і грі́шних, і усли́ши ма́лоє сіє́ моле́ніє на́ше, в похвалу́ тебі́ приноси́моє от і́стиннаго усе́рдія: є́же ми́лостивно приє́м, умоли́ Созда́теля на́шего Го́спода, ізба́вити нас геє́нни о́гненния і муче́ній ві́чних, і сподо́бити Ца́рствія Небе́снаго і блаже́нства святи́х, да с тобо́ю воспоє́м Єму́ во ві́ки: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела земна́го і челові́ка небе́снаго, яви́ нам тебе́ всея́ тва́рі Зижди́тель, преподо́бне о́тче Корни́ліє: прови́дів бо благопло́діє душі́ твоєя́, от ю́них літ ізбра́ тя служи́ти Єму́ в преподо́бії і чистоті́, нам же, чту́щим тя, внуша́єть вопи́ти к тебі́:","Ра́дуйся, благоро́дних роди́телей си́не боголюбе́зний.","Ра́дуйся, благочести́вия чети́ прозябе́ніє благода́тноє.","Ра́дуйся, от младе́нчества на слу́жбу Бо́гові освяще́нний.","Ра́дуйся, от ю́ности на по́двиги духо́вния предизбранний.","Ра́дуйся, сві́тлость са́на болярськаго Христа́ ра́ди презрі́вий.","Ра́дуйся, служи́ти Царю́ Небе́сному преі́скренні восхоті́вий.","Ра́дуйся, сего́ ра́ди слу́жбу царю́ земно́му оста́вивий.","Ра́дуйся, на по́двиги поста́ і моли́тви ре́вностно потекий.","Ра́дуйся, в оби́телі преподо́бнаго Кири́лла во і́ночество постриженний.","Ра́дуйся, в послуша́нії ста́рцю твоєму́ зіло́ преуспі́вий.","Ра́дуйся, труди́ вели́кия в хлебні нелі́ностно соверши́вий.","Ра́дуйся, вери́ги тя́жкия на ті́лі твоє́м носи́вий.","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний воєво́до, Бо́гом вруче́ннаго тебі́ полка́ во́їнов духо́вних, і преди́вний в чудесі́х, преподо́бне о́тче наш Корни́ліє! Восхваля́єм по́двиги твоя́ в пі́сніх хвалебних, і мо́лим ті ся приле́жно: я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся ви́ну о спасе́нії нас грі́шних, і моли́твами твої́ми богоприя́тними, от вся́ких нас бід, вре́менних і ві́чних, свободи́, да зове́м ті:","Ра́дуйся, Корни́ліє, вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О, свяще́нная главо́, земни́й А́нгеле, Небе́сний челові́че, вели́кий чудотво́рче, преподо́бне о́тче Корни́ліє! К тебі́ с ві́рою і любо́вію усе́рдно прибіга́юще, умиле́нно про́сим тя, Небе́снаго предста́теля на́шего: яви́ нам, смире́нним і грі́шним, любо́в твою́ оте́чеськую і многомо́щноє твоє́ заступле́ніє, се бо гріх ра́ди на́ших не дерза́єм, с свобо́дою чад Бо́жиїх, проси́ти Го́спода і Влади́ку на́шего о ну́жних нам на потре́бу, но тебі́, моли́твенника к Нему́ благоприя́тнаго, предлага́єм, ві́рующе несомні́нно, я́ко вся блага́я мо́жеши нам іспроси́ти у бла́гости Єго́, а́ще то́кмо восхо́щеши. Іспроси́ у́бо нам, уго́дниче Бо́жий, у Всеще́драго і Человіколю́бця Бо́га, ві́ру пра́ву, благоче́стіє непоколеби́моє, покая́ніє соверше́нноє, житія́ ісправле́ніє ріши́тельноє, да про́чеє не прогнівля́єм Го́спода наруше́нієм святи́х Єго́ за́повідей і сподо́бимся проще́ніє гріхо́в на́ших от Него́ получи́ти. Умоли́, чудотво́рче святи́й, Царя́ ца́рствующих і Го́спода госпо́дствующих дарова́ти мир і благостроє́ніє страні́ на́шей, я́ко да позна́ють всі противля́ющіїся єй, я́ко с на́ми Бог і святі́ї уго́дниці Єго́. Сохрани́, свя́тче Бо́жий, моли́твами твої́ми Це́рков Христо́ву от єресе́й і раско́лов, суєві́рія і неві́рія челові́чеськаго, да цвіте́ть в ней свято́є Правосла́віє во всей си́лі і прино́сить плоди́ спаси́тельния душа́м. Соблюди́ от вся́каго зла і оби́тель, тобо́ю созда́нную, і вся живу́щия і подвиза́ющіїся в ней по твої́м уста́вом, да ці́ли і невреди́ми пребу́дуть от іскуше́ній врага́ спасе́нія челові́чеськаго. При́зри ми́лостивно і на предстоя́щия тебі́ і моля́щіяся лю́ди, і́же в оби́тель твою́ прихо́дять на поклоне́ніє, і вся проше́нія їх во бла́го іспо́лни: боля́щим ісціле́ніє, скорб'я́щим утіше́ніє, бе́дствующим вспоможе́ніє ско́ро пода́ждь. Всім же нам здра́віє душе́вноє і тіле́сноє, землі́ плодоно́сіє, ти́хоє і богоуго́дноє житіє́, благу́ю христия́нськую кончи́ну і до́брий отві́т на Стра́шнім Суді́ Христо́вом у Всеми́лостиваго Бо́га ісхода́тайствуй, я́ко воі́стину імі́яй ве́ліє к Нему́ дерзнове́ніє. Єй, о́тче! Ві́ми, я́ко мно́го мо́жеть моли́тва твоя́ пред лице́м Вседержи́теля Го́спода, сего́ ра́ди крі́пко на тя упова́єм і на твоя́ святи́я моли́тви зіло́ наді́ємся, я́ко ти приведе́ши нас предста́тельством твої́м в небу́рноє приста́нище спасе́нія і наслі́дники пока́жеши нас всесві́тлаго Ца́рствія Христо́ва. Не посрами́ же, свя́тче о́тче наш, упова́нія на́шего і сподо́би нас вку́пі с тобо́ю блаже́нства ра́йськаго наслажда́тися, да сла́вим, хва́лим і велича́єм вели́кую ми́лость к нам Человіколю́бця Бо́га, Отця́, і Си́на, і Свята́го Ду́ха, і твоє́ благо́є оте́чеськоє заступле́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности горя́щим жела́нієм Боже́ственния любве́ разжига́єм, / жите́йськія молви́ оста́вил єси́, преподо́бне, / ревни́тель Анто́нію Ве́ликому бив, / безмо́лвієм і жесто́ким пребива́нієм послі́дуя Христу́, / бді́нієм і моли́твами і посто́м о́браз бив свої́м ученико́м. / Ті́мже моли́ся Го́сподеві, Корни́ліє блаже́нне, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Го́сподеві, от Святи́я Ді́ви возсія́вшу ми́рові, / і Тому́ ізмла́да, я́ко А́нгел, послужи́л єси́, блаже́нне, / і си́лою Єго́ пусти́ню, я́ко град, сотвори́л єси́, / мно́жество же учени́к в ней собра́л єси́, / ї́хже Богодухнове́нними уче́ньми просвіти́л єси́. / Тім вопіє́м ті: // ра́дуйся, о́тче наш Корни́ліє, і́ноком Боже́ственноє удобре́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Корни́ліє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Кирилу, ігумену Білозерському","e":"Akathist to our Venerable Father Cyril, Abbot of Beloozero","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Царя́ сил Го́спода Ісу́са, во́їне духо́вний і чудотво́рче преди́вний, преподо́бне О́тче наш Кири́лле, восхваля́єм Тя любо́вію в пі́сніх духо́вних, свята́го засту́пника на́шего, ти же, я́ко імі́яй благосе́рдіє мно́гоє, преклони́ся ми́лостивне к нам воспіва́ющим тя, і предста́тельством твої́м ко Го́споду, от вся́ких бід свободи́ зову́щих ті ра́достно:","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний воі́стину бил єси́, О́тче преподо́бне, от у́тра жи́зні твоєя́ до глубо́каго ве́чера сме́ртнаго, нелі́ностно рабо́тавий Го́сподеві в преподо́бії і святи́ні, нам же оста́вивий в примі́р подража́нія житіє́ твоє́ равноа́нгельноє, єму́же чудя́щеся, і чудеси́ твої́ми просвіща́ємі зове́м Ті гла́си хвале́бними си́це:","Ра́дуйся, роди́телей благочести́вих плод боголюбе́зний;","ра́дуйся, первопрестольного гра́да Москви́ прозябе́ніє свято́є.","Ра́дуйся, сиротствовавий в ю́ности твоєя́;","ра́дуйся, в сиротстві твоє́м Бо́га любо́вію усе́рдною взиска́вий.","Ра́дуйся, в синовство́ Бо́жиє сви́ше сопричтенний;","ра́дуйся, вся бога́тства ми́ра сего́ Христа́ ра́ди презрі́вий.","Ра́дуйся, ра́дости і уті́хи земниє ні во что же вміни́вий;","ра́дуйся, єди́но тща́ніє імі́вий, є́же єди́ному Бо́гу благоугожда́ти.","Ра́дуйся, чте́нієм писа́ній боже́ственних ду́шу твою́ напита́вий;","ра́дуйся, слеза́ми моли́твенними се́рдце твоє́ уплодоносивий.","Ра́дуйся, чистоту́ душе́вную і тіле́сную непоро́чно сохрани́вий;","ра́дуйся, посто́м і воздержа́нієм стра́сті юношескиє обузда́вий.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 2","ps":["Ви́дів сро́дник твой, іменитий болярин Самоде́ржця Россі́йськаго, благонра́віє душі́ твоєя́, О́тче преблаже́нне, возлюби́ тя і поста́ви строї́телем до́ма своєго́, да пече́шися о потре́бах єго́, ти же молва́ми жите́йськими обурева́ємий, зіло́ болі́зновал єси́ душе́ю твоє́ю і те́плі моли́лся єси́ ко Го́споду, да сподо́бит тя вні ми́ра і єго́ сує́ть, в безмо́лвії Єму́ служи́ти і невозбра́нно воспіва́ти а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним позна́ благопло́діє душі́ твоєя́ преподо́бний Стефа́н, ігу́мен оби́телі, і́же на Махрі, єгда́ при́йде во град Москву́ і позна́ся с тобо́ю, Свя́тче Бо́жий, єму́же ти со слеза́ми жела́ніє се́рдця твоєго́ іспові́дал єси́, я́ко хо́щеши і́нок би́ти, і от него́ обруче́ніє а́нгельськаго о́браза восприя́л єси́. Помина́я у́бо такову́ю ре́вность твою́ к по́двигом духо́вним, ублажа́єм тя, я́ко ізбра́нника Бо́жия, і умиле́нно глаго́лем:","Ра́дуйся, кро́ткий і незло́бивий послі́дователю Христо́в;","ра́дуйся, за́повіді Євангельскиє сами́м ді́лом соверши́вий.","Ра́дуйся, самоотверже́ніє ди́вноє по глаго́лу Го́спода твоєго́ яви́вий;","ра́дуйся, знатность ро́да і по́чести мирскиє, Христа́ ра́ди оста́вивий.","Ра́дуйся, вмі́сто риз златотканних, ру́бища і́ночеськая возлюби́вий;","ра́дуйся, крест Христо́в со усе́рдієм на ра́мо твоє́ восприя́вий.","Ра́дуйся, в душі́ твоє́й доброді́телі висо́кия насади́вий;","ра́дуйся, вся́коє пристра́стіє су́єтноє в себі́ іскорени́вий.","Ра́дуйся, проти́ву ми́ра, пло́ті і дия́вола крі́пко вооружи́вийся;","ра́дуйся, си́лою Бо́жиєю побіди́вий вся їх прило́ги.","Ра́дуйся, би́вий сосу́д непоро́чен Бо́жия благода́ті;","ра́дуйся, соделавийся стра́шен і непристу́пен враго́м неви́димим.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 3","ps":["Си́лою Бо́жієй укрепленний, не убоя́лся єси́, преподо́бне, гневавшагося на тя сро́дника твоєго́, і́ночествовати тебі́ возбранявшаго, но от руки́ свяще́ннаго Фео́дора, архімандрі́та Си́монова монастиря́, соверше́нноє постриже́ніє во а́нгельський о́браз восприя́л єси́, і в стіна́х оби́телі єго́ ти́хоє приста́нище спасе́нія себі́ обрі́л єси́, труди́ к трудо́м прилага́я, і в моли́твах деннонощних сла́дці воспіва́я спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я послуша́ніє от настоя́теля, є́же труди́тися в хлебні і поварне, О́тче досточу́дне, не дал єси́ сна очи́ма твої́ма, ні ві́ждом дрема́нія, но нелі́ностно труди́лся єси́, днем дрова́ сіки́й, огнь возжигаяй, хлі́би і пи́щу бра́тії приготовляяй, но́щію же в моли́твах, псалмопеніїх і колінопреклоне́ніїх бо́дренно пребива́яй, бил єси́ до́брий ді́латель Ца́рствія Небе́снаго, по степе́нем доброді́телей восходивий к соверше́нству духо́вному. Ті́мже восхваля́єм тя си́це:","Ра́дуйся, і́ноче Богоуго́дний, іночествовавий нелицемі́рно от і́скреннія душі́;","ра́дуйся, послу́шниче соверше́нний, сло́во велі́нія сами́м ді́лом предварявий.","Ра́дуйся, сле́зний іска́телю блаже́нства ві́чнаго;","ра́дуйся, моли́твенний воздеятелю рук преподо́бних го́ре ко Го́споду.","Ра́дуйся, огне́м пе́щним в хлебні і поварне, огнь муче́нія ві́чнаго себі́ напоминавий;","ра́дуйся, послуша́нієм поваренним умиле́нія глубину́ стяжа́вий.","Ра́дуйся, хліб той слеза́ми любве́ ко Го́споду орошавий;","ра́дуйся, питіє́ твоє́ пла́чем покая́нним растворявий.","Ра́дуйся, пре́жде всіх обретавийся в хра́мі на слу́жбах Боже́ственних;","ра́дуйся, возлюби́вий примета́тися к до́му Бо́га твоєго́.","Ра́дуйся, поста́ суровство́м умертви́вий плоть твою́, да не возоблада́єть она́ ду́хом;","ра́дуйся, чрез два і три дня пи́щу ску́дную вкушавий.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 4","ps":["Бу́ря страсте́й і тяжелоно́сния іскуше́ній во́лни, а́ще і прирази́шася к тебі́ в новоначалії і́ночеськом, уго́дниче Бо́жий, оба́че не возмого́ша поколеба́ти крі́пость проізволе́нія твоєго́, є́же єди́ному благоугожда́ти Бо́гу. Ті́мже моли́твою, посто́м і послуша́нієм і́стинним вся стрі́ли вра́жія, на тя іспущенний, неді́йственни сотвори́л єси́ і сподо́бился єси́ єще́ во пло́ті, в безстра́стії глубо́цім, возноси́ти Творцю́ Серафи́мськую піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав о доброді́тельном житії́ твоє́м, вели́кий Се́ргій Радонежський, возлюби́ тя зіло́, О́тче Кири́лле. І єгда́ прихожда́ше от пусти́ні своєя́ в оби́тель Си́монову, пре́жде всіх посещаше тя, су́ща в по́двигах і́ночеськаго послуша́нія, предпочита́я тя ю́наго ста́рцем многолетнім, і тім во удивле́ніє приводя́ всю бра́тію, от єго́же уст святи́х мно́го слове́с душеполе́зних сли́шал єси́, і слага́я їх в се́рдці твоє́м, бил єси́ до́брий учени́к вели́каго учи́теля, воі́стину досто́йний благохваленій такови́х:","Ра́дуйся, богоно́снаго Се́ргия ізбра́нний дру́же і собесі́дниче;","ра́дуйся, любо́во ве́лію о Го́споді к нему́ стяжа́вий, і от него́ зіло́ возлю́бленний.","Ра́дуйся, во смире́нії твоє́м висо́кая дарова́нія духо́вная получи́вий;","ра́дуйся, уничиже́нно трудивийся в по́двигах послуша́нія і та́ко Сергієва посіще́нія сподобленний.","Ра́дуйся, при послушаніях твої́х нікогда́же возроптавий;","ра́дуйся, суд Бо́жий і муки́ ві́чния приснопам'ятовавий.","Ра́дуйся, по́честей су́єтних і сла́ви челові́чеськія ізбегавий;","ра́дуйся, юро́дство Христа́ ра́ди на ся восприя́вий от всіх уничиже́н бу́деши.","Ра́дуйся, от настоя́теля наказу́ємий, безче́стіє в по́честь себі́ вміни́вий;","ра́дуйся, худи́я і многошвенния ри́зи носи́вий.","Ра́дуйся, зимним хла́дом ті́ло твоє́ угнетавий;","ра́дуйся, поко́й тіле́сний возненави́дівий.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 5","ps":["Боготечноє світи́ло бив, на сві́щниці свяще́нства поста́вился єси́ во́лею настоя́теля твоєго́, О́тче Кири́лле, і я́ко непоро́чний олтаря́ Госпо́дня служи́тель, со стра́хом і благогові́нієм же́ртву безкро́вную приноси́л єси́ Бо́гу, і́же соді́ла тя тайнозрителем мно́гих вели́ких чуде́с, в та́їнстві євхари́стії сокритих і явля́ємих священнослужи́телем досто́йним, к ни́мже і ти сопричтен бил єси́, зови́й от любве́ те́плия пострада́вшему за нас Христу́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя бра́тія в оби́телі Симоновськия, богоно́сна і равноа́нгельна житіє́м, Кири́лле богоблаже́нне, ізбра́ша тя, а́ще і нехотяща, во Архімандрі́та оби́телі своєя́, ти же жезл настоятельський приє́м, не превозне́слся єси́ толи́каго са́на висото́ю, но сугу́бо во смире́нії преуспіва́л єси́ і бил єси́ о́браз преподо́бія слове́сному твоєму́ ста́ду, сло́вом і житіє́м поуча́я твоя́ ученики́, і́же і взива́ху к тебі́:","Ра́дуйся, боговіща́нний учи́телю благоче́стія і чистоти́;","ра́дуйся, умиле́нія преіспо́лненний пропові́дниче покая́нія.","Ра́дуйся, єго́же словеса́ би́ша во спасе́ніє мно́гим;","ра́дуйся, єго́же увіща́нія ум'ягчиша окамені́лая во грісі́х се́рдця.","Ра́дуйся, не сло́вом то́кмо, но і всім житіє́м, поучавий духо́вная твоя́ ча́да;","ра́дуйся, чесо́му учи́л єси́, та і сам твори́л єси́ нелі́ностно.","Ра́дуйся, князе́й богому́дрий советниче;","ра́дуйся, си́льних ми́ра сего́ нелицеприя́тний обличи́телю.","Ра́дуйся, ни́щих і убо́гих любвеобильний корми́телю;","ра́дуйся, єго́же любо́в к меньшим о Христі́ бра́тіям нікогда́же оскуді́.","Ра́дуйся, єго́же благодія́ніями наслади́шася мно́зі;","ра́дуйся, в не́мже прославля́шеся на землі́ Оте́ць Небе́сний.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 6","ps":["Пропові́дник смире́нія і́стиннаго яви́лся єси́, О́тче, єгда́, стужи́в сі сла́вою і молво́ю настоя́тельства в Си́монові, оста́вил єси́ настоя́тельство і удали́лся єси́ в безмо́лвіє келе́йноє, да єди́н єди́ному Бо́гу возмо́жеши рабо́тати невозбра́нно, оба́че і в безмо́лвії не оста́ви тя враг спасе́нія челові́чеськаго, вооружи́в на тя наста́вшаго по тебі́ настоя́теля, єго́же гні́ву мі́сто уступая, пресели́лся єси́ на староі Си́монові, і та́мо уєдине́нно пребива́я, немо́лчно воспіва́л єси́ піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ тебі́ світ небе́сний, єгда́ во ве́чер глубо́кий моли́лся єси́, преподо́бне, в келії твоє́й пред іко́ною Богома́тері, прося́ Ю дарова́ти тебі́ мі́сто удо́бноє к безмолвному житію́, і се а́біє усли́шал єси́ глас от іко́ни Єя́ Святи́я, си́це глаго́лющ: «Кири́лле, ізи́ди отсю́ду і іди́ на Белоєзеро: та́мо бо угото́вах ті мі́сто, на не́мже возмо́жеши спасти́ся», і с гла́сом вку́пі, луча́ світоза́рная от полу́нощния страни́ осія́ і ука́за мі́сто, сви́ше предизбранноє для твоєго́ вселе́нія, єго́же ра́достно созерца́л єси́ око́нцем твоєя́ келії. Тебе́ у́бо си́це обрадованному, і ми ра́достно восклиця́єм:","Ра́дуйся, вели́кий уго́дниче Бо́жий, єще́ на землі́ созерца́вий світ небе́сний;","ра́дуйся, ізбра́нний слуго́ Ма́тері Госпо́дні, возглаголавшей к тебі́ от іко́ни Своєя́ Святи́я.","Ра́дуйся, благоволе́нієм Влади́чиці ми́ра облагода́тствованний;","ра́дуйся, проше́нія твоєго́ ісполне́нія от Нея́ приє́мий.","Ра́дуйся, я́ко моли́тва твоя́ усли́шана бисть заступницею ро́да христия́нськаго;","ра́дуйся, я́ко нощ просвіти́ся тебі́ сія́нієм Боже́ственния сла́ви.","Ра́дуйся, я́ко дале́че отстоя́щеє мі́сто, близь показа́ся тебі́ судьба́ми Бо́жиїми ди́вними;","ра́дуйся, я́ко сви́ше дарова́ся тебі́ мі́сто поко́я духо́внаго.","Ра́дуйся, ра́дости і утіше́нія о сем преіспо́лненний;","ра́дуйся, сле́зи те́плия благодаре́нія і хвале́нія пред Бо́гом ізливавий.","Ра́дуйся, моли́тв благово́нноє кади́ло;","ра́дуйся, псалмопі́нія орга́не ізя́щний.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 7","ps":["Ди́вноє виді́ніє і глас от іко́ни Богома́тере би́вший, пові́дал єси́, преподо́бне О́тче, спостнику твоєму́ і дру́гу, преподо́бному Ферапо́нту, і с ним вку́пі оста́вил єси́ град оте́чествія твоєго́, і поте́кл єси́ в пусти́ню непроходи́мую на Белоєзеро, іща́ Бо́гом указаннаго ті мі́ста, є́же обрі́т, зіло́ возра́довался єси́, і на нем в пеще́рі всели́лся єси́, во освяще́ніє же мі́сту, честни́й Крест, свої́ма рука́ма соорудив, та́мо поста́вил єси́, зови́й распе́ншемуся на кресті́ і попра́вшему си́лу а́дову, Царю́ сла́ви Христу́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вим по́двигом духо́вним вдал єси́ себе́, богоблаже́нне О́тче, в пусти́ні уєдине́нно пребива́я в моли́твах, поще́ніїх і труді́х непреста́нних, і́же ви́дя Всеви́дець Госпо́дь, собра́ к тебі́ па́ству і́ноков пустиннолюбивих, і́же хотя́ху жи́ти с тобо́ю, і назида́тися от тебе́ во спасе́ніє: і та́ко устро́їл єси́ оби́тель святу́ю, я́ко крин в пусти́ні процві́тшую духо́вно, в не́йже до днесь прославля́ється і́м'я твоє́ си́ми достодо́лжними похвали́:","Ра́дуйся, преподо́бне, свя́тостію і чистото́ю сві́тло украше́нний;","ра́дуйся, богоно́сне, дара́ми Боже́ственними сви́ше одаренний.","Ра́дуйся, па́стирю до́брий тобо́ю собра́ннаго стада́ слове́сних ове́ць;","ра́дуйся, строї́телю богому́дрий общижитія і́ночеськаго.","Ра́дуйся, пусти́ню непроходи́мую во вертогра́д духо́вний труда́ми твої́ми претвори́вий;","ра́дуйся, вся страхова́нія і привиді́нія вра́жия моли́твами твої́ми посрами́вий.","Ра́дуйся, несомні́нною наде́ждою на Бо́га оби́тель твою́ созидавий;","ра́дуйся, слеза́ми моли́твенними основа́ніє єя́ ороси́вий.","Ра́дуйся, ни́щий ду́хом, но мно́гі богатящий;","ра́дуйся, руко́ю Всеви́шняго держа́вно охраняємий.","Ра́дуйся, от напра́сния сме́рті ди́вно ізба́вленний;","ра́дуйся, от запале́нія о́гненнаго неви́димо защищенний.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 8","ps":["Стра́нноє виді́ніє бисть разбо́йником, оби́тель твою́ ограбити умислившим, Свя́тче Бо́жий, і́же прише́дше к ней но́щію, ви́діша ра́тних люде́й мно́жество, на стра́жі вокру́г оби́телі стоя́щих, і ограбити ю непопускающих, єгдаже уві́діша, я́ко никотория стра́жи не бисть во оби́телі тоя́ нощі́, позна́ша Бо́жию тя защищающую си́лу, і с раскаянієм прите́кше к тебі́, іспові́даху виді́ніє чуде́сноє, о не́мже ра́дуяся, воспі́л єси́ со ученики́ твої́ми, спаса́ющему тя Бо́гу, благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Богі бив, упова́ніє крі́пкоє на Бо́га возложи́л єси́, О́тче преподо́бне, я́ко си́лен єсть препита́ти тя со ученики́ твої́ми, в пусти́нном мі́сті пребива́ющими. Ті́мже подая́нія проси́ти ні ко кому́же посила́л єси́, ві́руя несомні́нно, я́ко вся к житію́ потре́бная от руки́ Бо́жия получи́ши: і по ві́рі твоє́й і моли́тві, от боголю́бцев вся сія́ і без проше́нія твоєго́ получал єси́, удивля́я ча́да твоя́ си́лою ві́ри творящиє чудеса́, і подвиза́я зва́ти тебі́:","Ра́дуйся, безмо́лвія рачи́телю, молву́ су́єтную возненави́дівий;","ра́дуйся, богоми́слія висото́, попече́нії жите́йськими недосяга́ємая.","Ра́дуйся, воздержа́нія в пи́щі і питії́ пра́вило ізві́стноє;","ра́дуйся, нетрезвеннаго питія́ во оби́телі твоє́й імі́ти возбранивий.","Ра́дуйся, законоположе́нія святи́х Оте́ць неізмі́нно сохрани́вий;","ра́дуйся, к по́двигом висо́ким ученики́ твоя́ руководи́вий.","Ра́дуйся, достигни в мі́ру соверше́нства о Христі́;","ра́дуйся, прия́вий власть на ду́хи нечи́стая.","Ра́дуйся, чудотворе́нія да́ром обогащенний;","ра́дуйся, си́лою боже́ственною преіспо́лненний.","Ра́дуйся, прозорли́вость благода́тную проявивий;","ра́дуйся, по́мощ ціле́бную немздоприїмно подава́вий.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 9","ps":["Всі і́ноці оби́телі твоєя́, Преподо́бне О́тче, я́ко А́нгела Бо́жия тя почита́ху, і́бо воі́стину ангелоподобнії нра́ви явля́л єси́ їм в житії́ твоє́м свято́м, і́же все бисть посвящено богоугожде́нію непреста́нному. Ті́мже ди́вния чудеса́ твори́ти дарова́ тебі́ Бог: неду́жния ісціля́л єси́, бесноватая от муче́нія дия́вольськаго свобожда́л єси́, бу́дущая прорицял єси́, єще́ же і сами́х мертвецов воскрешал єси́ моли́твою твоє́ю, во є́же пі́ти о тебі́ бли́жнім і да́льним, хвале́бную піснь верхо́вному чуде́с творцю́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не мо́жеть ізрещи́ вели́чіє чуде́с твої́х, уго́дниче Бо́жий, О́тче Кири́лле, і́миже житіє́ твоє́ земно́є, я́ко цвіта́ми благово́нними, духо́вно благоукраси́ся, облагоуха́я душі́ ві́рних сла́достію преподо́бія і святи́ні, і приводя́ їх к славосло́вію Бо́га, си́це просла́вльшаго тя своєго́ ізбра́нника, нам же внуша́ющаго взива́ти к тебі́:","Ра́дуйся, боля́щих до́брий ціле́бниче;","ра́дуйся, разсла́бленних благосе́рдий укріпи́телю.","Ра́дуйся, сліпи́м зрі́ніє мно́гажди дарова́вий.","Ра́дуйся, бесноватих от наси́лія дия́вольськаго освободивий.","Ра́дуйся, боля́рина Рома́на от одра́ сме́ртнаго здра́ва возста́вивий;","ра́дуйся, уме́ршаго і́нока Далма́та на покая́ніє воскреси́вий.","Ра́дуйся, оскуді́вшеє во оби́телі твоє́й вино́ для Литургі́ї святи́я чуде́сно умно́живий;","ра́дуйся, во вре́м'я гла́да опусті́вшую жи́тницю хлі́бом наполнивий.","Ра́дуйся, о́ним хлі́бом гла́дния лю́ди ми́лостивно препита́вий;","ра́дуйся, я́ко хліб той, тобо́ю раздава́ємий, в жи́тниці не оскудіва́ше, но па́че умножа́шеся.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 10","ps":["Спасе́ніє ві́чноє унаслі́довал єси́, уго́дниче Бо́жий, і кончи́ну пра́ведную, я́ко віне́ць по́двигом твої́м, получи́л єси́, неболі́зненно і ми́рно преше́д от земни́х к обителям небе́сним, іді́же свята́я твоя́ душа́, воздая́ніє прия́ от руки́ Вседержи́теля Бо́га, і со А́нгельськими во́їнстви предстої́ть престо́лу Єго́ Боже́ственному, воспіва́я немо́лчную Єму́ піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго ра́бе благи́й і ві́рний, да́нний тебі́ тала́нт не сокри́вий, но трудолю́бно єго́ усугубивий, і мно́гу ку́плю духо́вную їм сотвори́вий, О́тче Кири́лле, помози́ і нам, земни́м і пе́рстним, подража́ти житію́ твоєму́ свято́му, і стяжа́ти при ісхо́ді на́шем благу́ю наде́жду спасе́нія, да поє́м тебе́ умиле́нними гла́си:","Ра́дуйся, Свя́тче Бо́жий, свя́то і непоро́чно сконча́вий жизнь земну́ю;","ра́дуйся, Ізбра́нниче Христо́в, безболі́зненно і ми́рно преда́вий дух твой в ру́ці Бо́жії.","Ра́дуйся, я́ко смерть твоя́ честна́ пред Го́сподем, і успе́ніє со Святи́ми;","ра́дуйся, я́ко па́м'ять твоя́ с похвала́ми почита́ється во Святі́й Це́ркві.","Ра́дуйся, я́ко пресели́вся в небе́сния оби́телі, і земни́х не оставля́єши;","ра́дуйся, я́ко от го́рних висо́т благосе́рдієм твої́м к земноро́дним проникаєши.","Ра́дуйся, чудотво́рець би́вий при жи́зні, такови́м же яви́вийся і по сме́рті;","ра́дуйся, оби́тель твою́ і по сконча́нії твоє́м сохрани́вий.","Ра́дуйся, ча́да твоя́ духо́вная і по сме́рті твоє́й не заби́вий;","ра́дуйся, во утіше́ніє їм ціле́бния мо́щи твоя́ оста́вивий.","Ра́дуйся, чту́щим тя ско́рий предста́телю;","ра́дуйся, усе́рдний всіх прибіга́ющих к тебі́ засту́пниче.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє прино́ситься ві́рними у ра́ки святи́х моще́й твої́х, Кири́лле богоно́сне, і́же а́ще і в ні́драх земни́х почива́ють, оба́че лучи́ мно́гих чуде́с іспуща́ють, озаря́я душі́ і се́рдця і́щущих с ві́рою твоєго́ заступле́нія, єго́же сподо́би і нас, смире́нних, сія́ пі́сненния хвали́ тебі́ вознося́щих, і Бо́гу благода́рно зову́щих: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник Бо́жия благода́ті, озаря́яй полу́нощную страну́ Россі́йськаго Ца́рства, яви́лся єси́, преподо́бне і досточу́дне О́тче Кири́лле, духо́вним сія́нієм твої́х по́двигов і чуде́с просвіти́вий пусти́ню, і в ней оби́тель і́ноком устро́ївий, іді́же по́стников ли́ки ти́хоє приста́нище спасе́нія обріта́ють, і тя, первонача́льника своєго́, любо́вію велича́юще, пі́сненно тебі́ вопію́ть:","Ра́дуйся, великоімени́тий і многославний в чудесах подви́жниче;","ра́дуйся, ангелонравний челові́че.","Ра́дуйся, оте́чества твоєго́ благода́тноє утіше́ніє;","ра́дуйся, оби́телі твоєя́ при́сноє ра́дованіє.","Ра́дуйся, моща́ми твої́ми пресла́вно в ней чудоді́йствуя;","ра́дуйся, моли́тви і проше́нія на́ша во бла́го ісполня́яй.","Ра́дуйся, смире́ніє при жи́зні і по сме́рті возлюби́вий;","ра́дуйся, смире́нно моща́м твої́м в ні́драх земни́х почива́ти восхоті́вий.","Ра́дуйся, я́ко ра́ка твоя́ честна́я враче́бниця яви́ся неду́гом челові́чеським;","ра́дуйся, я́ко от нея́ всяк с ві́рою приходя́й да́ри ціле́бний приє́млеть.","Ра́дуйся, ріко́ чуде́с приснотеку́щая;","ра́дуйся, істо́чниче ісціле́ній нікогда́же оскудевающий.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия сві́тлоє жили́ще бив при жи́зні, Уго́дниче Бо́жий, і по сме́рті твоє́й благода́ті прича́стну соді́лал єси́ ра́ку моще́й твої́х, чудеси́ пресла́вними увіря́я нас, я́ко вели́к єси́ пред Го́сподем, і я́ко мно́го мо́жеть моли́тва твоя́ пред бла́гостію Єго́. Яви́ у́бо і нам, недосто́йним, щедро́ти твоя́ моли́твенния, і предста́тельством твої́м те́плим окорми́ нас ко приста́нищу спасе́нія, да поє́м на землі́ живи́х, при́сно живи́ми і ме́ртвими облада́ющему Влади́ці Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая і пресла́вная чудеса́ твоя́, преподо́бне О́тче Кири́лле, смире́нно про́сим тя, небе́снаго засту́пника на́шего: в час гро́зний сме́ртний, єгда́ убо́гая душа́ на́ша к ісхо́ду своєму́ прибли́житься, покажи́ нам многомо́щноє твоє́ заступле́ніє, і ізба́ви нас предста́тельством твої́м от вла́сті сил те́мних, оби́кших прегражда́ти душе́ челові́честій восхо́д в го́рнія оби́телі, ї́хже дости́гнути сподо́би нас моли́твами твої́ми, да зове́м тебі́ благода́рними гла́си:","Ра́дуйся, пресвяти́й єдиносущниє Тро́йці усе́рдний служи́телю;","ра́дуйся, Пресвяти́я Влади́чиці Богоро́диці досто́йний ізбра́нниче.","Ра́дуйся, А́нгельських сил сві́тлий собесі́дниче;","ра́дуйся, Предте́чі Госпо́дня пустиннолюбивий подража́телю.","Ра́дуйся, Проро́ков Бо́жиїх прозорливй подо́бниче;","ра́дуйся, Апо́столов Христо́вих єдинонра́вний послі́дователю.","Ра́дуйся, му́чеником добропобедним сравнивийся в по́двизіх терпі́нієм;","ра́дуйся, Святи́телєм богому́дрим соревновавий душеспасительним уче́нієм.","Ра́дуйся, сія́ющая звіздо́ в ли́ці Преподо́бних;","ра́дуйся, блаже́нний сожи́телю Пра́ведних і всіх Святи́х.","Ра́дуйся, о не́мже ра́дуються і Бо́га хва́лять челові́ци;","ра́дуйся, єго́же трепе́щуть темниє а́дськия си́ли.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 13","ps":["О, вели́кий уго́дниче Бо́жий і Чудотво́рче, преподо́бне О́тче Кири́лле! Ти го́ре на небесі́, ми до́лу на землі́, удале́ннії от тебе́ не толи́ко мі́стом, коли́ко гріха́ми на́шими: оба́че дерза́єм приноси́ти тебі́ сіє́ ма́лоє похва́льноє пі́ніє, є́же ми́лостивно приє́мши, умоли́ милосе́рдаго Творця́, поми́ловати нас і ізба́вити геє́нни о́гненния і муче́ній а́дських, да сподо́бимся вку́пі с тобо́ю, в Ца́рствії Небе́снім, пі́ти Єму́ ві́чно ра́достную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний воі́стину бил єси́, О́тче преподо́бне, от у́тра жи́зні твоєя́ до глубо́каго ве́чера сме́ртнаго, нелі́ностно рабо́тавий Го́сподеві в преподо́бії і святи́ні, нам же оста́вивий в примі́р подража́нія житіє́ твоє́ равноа́нгельноє, єму́же чудя́щеся, і чудеси́ твої́ми просвіща́ємі зове́м Ті гла́си хвале́бними си́це:","Ра́дуйся, роди́телей благочести́вих плод боголюбе́зний;","ра́дуйся, первопрестольного гра́да Москви́ прозябе́ніє свято́є.","Ра́дуйся, сиротствовавий в ю́ности твоєя́;","ра́дуйся, в сиротстві твоє́м Бо́га любо́вію усе́рдною взиска́вий.","Ра́дуйся, в синовство́ Бо́жиє сви́ше сопричтенний;","ра́дуйся, вся бога́тства ми́ра сего́ Христа́ ра́ди презрі́вий.","Ра́дуйся, ра́дости і уті́хи земниє ні во что же вміни́вий;","ра́дуйся, єди́но тща́ніє імі́вий, є́же єди́ному Бо́гу благоугожда́ти.","Ра́дуйся, чте́нієм писа́ній боже́ственних ду́шу твою́ напита́вий;","ра́дуйся, слеза́ми моли́твенними се́рдце твоє́ уплодоносивий.","Ра́дуйся, чистоту́ душе́вную і тіле́сную непоро́чно сохрани́вий;","ра́дуйся, посто́м і воздержа́нієм стра́сті юношескиє обузда́вий.","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Кондак 1","ps":["Ізбра́нний от Царя́ сил Го́спода Ісу́са, во́їне духо́вний і чудотво́рче преди́вний, преподо́бне О́тче наш Кири́лле, восхваля́єм Тя любо́вію в пі́сніх духо́вних, свята́го засту́пника на́шего, ти же, я́ко імі́яй благосе́рдіє мно́гоє, преклони́ся ми́лостивне к нам воспіва́ющим тя, і предста́тельством твої́м ко Го́споду, от вся́ких бід свободи́ зову́щих ті ра́достно:","Ра́дуйся, Кири́лле, вели́кий Чудотво́рче!"]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне і Богоно́сне о́тче Кири́лле! Припа́даєм к тебі́ с ві́рою і любо́вію, і про́сим тя, Небе́снаго засту́пника на́шего: яви́ ве́ліє милосе́рдіє твоє́ нам, смире́нним і грі́шним, і проле́й те́плия моли́тви твоя́ о нас ко Го́споду Бо́гу. Сво́йственно єсть тебі́ благосе́рдіє, свя́тче Бо́жий, і́бо, живу́щу ті на землі́, єди́но бисть у тебе́ попече́ніє, є́же спаса́ти от поги́белі ду́ші челові́чеськія, і вся твоя́ жизнь свята́я зерца́ло до́брих діл яви́ся, о ни́хже прославля́шеся в тебі́ Оте́ць Небе́сний. К Тому́ ве́ліє дерзнове́ніє стяжа́в, іспроси́ нам у бла́гости Єго́ ві́ру пра́вую, благоче́стіє нелицемі́рноє, покая́ніє і́стинноє, братолю́біє соверше́нноє і преуспія́ніє во всіх благи́х ді́ліх. Ісхода́тайствуй нам здра́віє душе́вноє і тіле́сноє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, ми́рноє і безм'яте́жноє житіє́, непости́дную христия́нськую кончи́ну і до́брий отві́т на стра́шнім Суді́ Христо́ві. Сохрани́ Це́рков святу́ю і держа́ву Россі́йськую от бра́ней і нестроє́ній. Огради́ оби́тель твою́ честну́ю от вся́каго зла, і вся правові́рния лю́ди, к тебі́ приходя́щия і моще́м твої́м покланя́ющіяся, осіни́ Небе́сним твої́м благослове́нієм, і вся проше́нія їх во бла́го іспо́лни. Єй, о́тче, не пре́зри моли́тв на́ших, со умиле́нієм тебі́ возноси́мих, но бу́ди о нас те́плий предста́тель ко Го́споду, і сподо́би нас по́мощію твоє́ю спасе́ніє ві́чноє получи́ти і Ца́рствіє Небе́сноє унаслі́довати, да славосло́вим ве́лія щедро́ти і неізрече́нния ми́лости Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га, і твоє́ оте́чеськоє заступле́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Я́ко крин в пусти́ні дави́дськи процві́л єси́, о́тче Кири́лле, / злостра́стія те́рніє іскореня́я, / і собра́л єси́ в ней учени́к мно́жество, / стра́хом Бо́жиїм і уче́нієм твої́м наставля́ємих, / ї́хже і до конця́ я́ко чадолюби́вий оте́ць / не оста́вил єси́ посіща́я, да всі вопіє́м: / сла́ва Да́вшему ті крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 8","ps":["Я́ко преоби́дів тлі́нная і до́лу влеку́щая мудрова́нія, о́тче, / к Ви́шнему тече́нію ра́достно устреми́лся єси́, / і та́мо со святи́ми Пресвяті́й Тро́йце предстоя́, / моли́ от враг сохрани́тися ста́ду твоєму́, / я́ко да, свято́є твоє́ успе́ніє пра́зднующе, вопіє́м: // ра́дуйся, преблаже́нне Кири́лле, о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Кири́лле, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст рівноапостольній Феклі Іконійській, первомучениці","e":"Akathist to the Equal-to-the-Apostles Thecla of Iconium, Protomartyr","secs":[{"h":"Кондак 1","ps":["Ізбра́нную Христо́м неві́сту богозва́нную, свята́го Па́вла учени́цю ві́рную і му́друю, земна́го жениха́ і мир презревшую і в по́двизіх пресві́тло просія́вшую, тя, Фе́кло, му́ченице пе́рвая, восхва́лим. Ти же, я́ко у Бо́га дерзнове́ніє обрі́тшая, от па́губи страсте́й і бід покри́й зову́щих ті:","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Ікос 1","ps":["А́нгели на Небесі́х удиви́шася, узрі́вше душі́ твоєя́ си́лу і проізволе́ніє: му́жеськими бо труди́ врага́ посрами́вши, ти, а́гниць чи́стих свяще́нная похвало́, пе́рвая в свещеноснем їх со́нме дости́гла єси́ Черто́га Преві́чнаго Жениха́, іді́же ни́ні ублажа́єма та́ко:","Ра́дуйся, красото́ му́чеников;","ра́дуйся, ра́дованіє дів і жен.","Ра́дуйся, пе́рвих пустинножи́телей о́бразе;","ра́дуйся, подви́жников благоче́стія пра́вило.","Ра́дуйся, Апо́стола верхо́внаго дщи предо́брая;","ра́дуйся, ма́ти і́ночествующих пресла́вная.","Ра́дуйся, жениха́ земна́го до́брі бежавшая;","ра́дуйся, к Жениху́ Небе́сному прекра́сно прите́кшая.","Ра́дуйся, а́гнице Христо́ва пренепоро́чная;","ра́дуйся, свіще́ Госпо́дня светлосіянная.","Ра́дуйся, є́юже ві́рнії утвержда́ються;","ра́дуйся, є́юже сопроти́внії низлага́ються.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 2","ps":["Ви́дящи у́мнима очи́ма твої́ма, Фе́кло, світ любве́ Бо́жия в душі́ твоє́й, єгда́ стріла́ми благові́стія, от честни́х уст Па́влових іспущенними, сла́дці уязви́ся, за ни Расп'я́тому воззвала́ єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Небе́сних та́їн дарова́ся ті, Феоклії о́трасле, Фе́кло прехва́льная, єгда́ вслід Христа́ устреми́вшися, презрі́ла єси́ добро́ту лиця́ твоєго́, па́че же лі́поту ю́ности. Ті́мже ми, чту́ще тя, я́ко вертогра́д чистоти́, прино́сим ті пі́ніє таково́є:","Ра́дуйся, украше́ніє чи́стих дів;","ра́дуйся, печа́те ли́ка апо́столов.","Ра́дуйся, ра́зума духо́внаго світи́льниче;","ра́дуйся, по́двига страда́льчеськаго кра́ю.","Ра́дуйся, мечу́, стремле́нія страсте́й посіця́яй;","ра́дуйся, путю́, в Небе́сний Град востекаяй.","Ра́дуйся, сподви́жнице муже́й апо́стольських;","ра́дуйся, ві́тве і ро́ждіє Лози́, Христа́.","Ра́дуйся, сві́щнице трезві́нія і му́дрости;","ра́дуйся, огню́ духо́вния любве́.","Ра́дуйся, грозо на я́рость вра́жию;","ра́дуйся, мо́лніє на сопроти́внаго.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго осіня́єма і Ду́хом Бо́жиїм напая́єма, Фе́кло, благода́ті ро́су в се́рдці твоє́м собра́вши, живоно́сний кла́дезь показа́лася єси́, іспо́лнь даро́в Уті́шителя, істоча́яй же словеса́ от Сло́ва Преві́чнаго, і́миже орошаємії сла́в'ять Святу́ю Тро́йцю: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи, ді́во, се́рдце, возжженноє пла́менем любве́ Жениха́ твоєго́, Христа́, обру́чника своєго́ Фами́ра а́біє отрекла́ся єси́, житія́ равноа́нгельнаго возжелі́вши і вся, я́же суть в ми́рі, во уме́ти вміни́вши, я́коже Па́вел тебі́ о́браз подража́нія подаде́. Сему́ див'я́щеся, та́ко тя велича́єм:","Ра́дуйся, щиті́ воздержа́нія;","ра́дуйся, две́ре благоче́стія.","Ра́дуйся, мрак страсте́й на землі́ разгнавшая;","ра́дуйся, бога́тство на Небесі́ стяжа́вшая.","Ра́дуйся, хра́мі свяще́нія світови́днійший;","ра́дуйся, ски́ніє житія́ добронравнаго.","Ра́дуйся, я́ко сло́вом твої́м се́рдця утучняються;","ра́дуйся, я́ко тобо́ю пото́ци греховнії ізсушаються.","Ра́дуйся, упова́ніє кро́тких а́гниць;","ра́дуйся, ві́нче преподо́бних дів.","Ра́дуйся, істо́чниче струй благода́тних;","ра́дуйся, ве́рті цветосажденій Ра́йських.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 4","ps":["Бу́ря тягостних іскуше́ній возста́ на храм душі́ твоєя́, о Фе́кло мужему́дренная; ти же, ре́вность іму́щи Боже́ственную, от Па́вла уві́дівши во узи́лищі о Ка́мені краєуго́льнім, Христе́, на о́наго іспові́данії утверди́ла єси́ ски́нію се́рдця, в не́йже воспі́ла єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Слу́шающи отця́ твоєго́ по ду́ху, Па́вла апо́стола, сподо́билася єси́ во о́бразі того́ узрі́ти укрепляющего тебе́ Христа́, Єго́же во́лею пла́мень тя я́ко черто́г окружи́, єгда́ введе́на била́ єси́ во огнь ве́лій; і о́блак, води́ і гра́да іспо́лнь, ізлія́ся. Чу́до же сіє́ ві́дяще, науча́ємся ті зва́ти, добропобі́дная Фе́кло, си́це:","Ра́дуйся, нра́вов благи́х сокровищнице;","ра́дуйся, І́стини первосвидетельнице.","Ра́дуйся, бога́тство цілому́дрія неоску́дноє;","ра́дуйся, стра́же Іконі́ї неусипа́яй.","Ра́дуйся, я́ко тобо́ю Христо́с возвели́чися;","ра́дуйся, я́ко тобо́ю враг посрами́ся.","Ра́дуйся, сто́лпе чистоти́, до Небе́с досязаяй;","ра́дуйся, сві́те любве́, вся конці́ просвіща́яй.","Ра́дуйся, копіє́, закала́ющеє вся́кую страсть;","ра́дуйся, ріко́, ороша́ющая зе́млю душ.","Ра́дуйся, гла́се Прему́дрости;","ра́дуйся, ізоби́льний кла́дезю ми́лости.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю те́мний мир осія́ла єси́, о пе́рвая страстоте́рпице Фе́кло, я́ко адама́нт я́вльшися во страда́ніїх мно́гих і о́браз би́вши до́браго іспові́данія. Тобо́ю бо луча́ Со́лнця Пра́вди, Христа́, возсія́, нощ гріха́ разгоня́ющая і пі́ти с тобо́ю Тому́ воздвиза́ющая: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів благолі́піє лиця́ твоєго́, о Фе́кло, Алекса́ндр зверонравний на честь твою́ пося́гнути уми́сли; ти же, ді́вство твоє́ положи́вши храни́ти, іспові́дала єси́ обруче́ніє своє́ Христу́. Того́ ра́ди, му́жество твоє́ помина́юще, та́ко пі́сньми немо́лчно тя ублажа́єм:","Ра́дуйся, луче́ сла́вних победоносцев;","ра́дуйся, крі́пкая побо́рнице ісповедниць.","Ра́дуйся, дохнове́нія Сви́ше мирополо́жнице;","ра́дуйся, Ца́рства Святи́я Тро́йці украше́ніє.","Ра́дуйся, ді́вство твоє́, я́ко дар, Христу́ прине́сшая;","ра́дуйся, сосу́д освяще́н Ду́ха Свята́го я́вльшаяся.","Ра́дуйся, злих челові́к попра́вшая лесть;","ра́дуйся, Живода́вця привлекшая благода́ть.","Ра́дуйся, зна́меніє любве́ Творця́;","ра́дуйся, возбране́ніє беззако́нія.","Ра́дуйся, пра́вило доблемисленних жен;","ра́дуйся, о́бразе му́жественнаго дерзнове́нія.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 6","ps":["Пропові́дницю сла́ви Трієди́наго Бо́га себі́ показа́ла єси́, о Фе́кло прехва́льная, єгда́ си́лу богобо́рця, і́же во Антіохі́ї, богоуго́дним противле́нієм побіди́ла єси́. Звіре́м же ди́віїм би́вши пре́дана на сніде́ніє, неврежде́нна сохрани́лася си́лою Жениха́ твоєго́; Єму́же, красні́йшему па́че всіх челові́к, воспі́ла єси́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий в се́рдці твоє́м Христо́с, Світ І́стинний, богодейственною десни́цею Своє́ю я́рость звіре́й уста́ви; і па́ки, тебі́ нау́тріє вданней львом і медведем, нрав їх на ти́хость і целому́дріє преложи́, львицю же защища́ти тя, ді́во чи́стая, научи́. Всі зря́щії о сем ужаса́хуся; ми же, ві́рнії, вопіє́м ті:","Ра́дуйся, І́стини благові́стіє;","ра́дуйся, богосло́вія уста́.","Ра́дуйся, ла́стовице, возлетевшая от дія́нія к созерца́нію;","ра́дуйся, славію, вдохновленний на́йтієм Ду́ха.","Ра́дуйся, цветоплетенний подви́жников ві́нче;","ра́дуйся, преізоби́льний уче́ній пото́че.","Ра́дуйся, я́ко уста́ звіре́й затворяєши;","ра́дуйся, я́ко Го́рнюю Ски́нію украша́єши.","Ра́дуйся, утвержде́ніє Ви́шнія сві́тлости;","ра́дуйся, основа́ніє тве́рдаго благоче́стія.","Ра́дуйся, сві́тлаго черто́га наслі́днице;","ра́дуйся, кри́на чистоти́ насадительнице.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 7","ps":["Хотя́щи Трифе́ну вдови́цю во ві́рі наста́вити, той сло́во Жи́зні благовествовала єси́, она́ же, о воскресе́нії ме́ртвих уві́дівши, моли́тв іспроси́ о усопшей дще́ри своє́й. І а́біє ти пла́менні возопи́ла єси́: Ісу́се мой, Си́не Ви́шняго, пом'яни́ ду́шу преста́вльшіяся Фалконилли, да воспоє́ть Тебі́ ви́ну піснь на землі́ живи́х: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до смотре́нія Своєго́ яви́ Госпо́дь, єгда́ жени́ богому́дрия вверго́ша во є́зеро со звірми́ благово́нния нард, амом і касію, во о́браз ми́ра благоуха́ннаго, і́мже запечатлі́ся ба́ня пакирожде́нія твоєго́. Тогда́ бо о́блак о́гненний ті́ло твоє́ сокри́, га́ди же о́ния умертви́, во є́же взива́ти всім:","Ра́дуйся, Ісу́сово многоці́нноє ми́ро;","ра́дуйся, Уті́шителев несокруши́мий сосу́де.","Ра́дуйся, невеще́ственних А́нгелов общнице;","ра́дуйся, подвизающимся челові́ком наста́внице.","Ра́дуйся, висото́ доброді́телей пренебе́сних;","ра́дуйся, ра́зума глубино́ дів прему́дрих.","Ра́дуйся, богоми́слієм себі́ укріпи́вшая;","ра́дуйся, благода́тію зві́ри лю́тия укроти́вшая.","Ра́дуйся, душетлі́нних страсте́й істребле́ніє;","ра́дуйся, нра́вов благи́х насажде́ніє.","Ра́дуйся, за немощству́ющих к Бо́гу хода́тайство;","ра́дуйся, во іскуше́ніїх су́щих предста́тельство.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 8","ps":["Стра́нноє чу́до, ді́во богохрани́мая, мучи́теліє твой і лю́діє всі узрі́ша, єгда́ прив'язанней ті раз'яренним тельце́м, о́них свирі́пая устремле́нія укроти́шася, на тебі́ почивающею Бо́жиєю благода́тію, єя́же ді́йствієм уверовавшії воспі́ша вся содержа́щему в дла́ни Своє́й Творцю́: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся осіянна била́ єси́ сві́том Фаворським, Фе́кло, Сія́нія О́тча свята́я ізбраннице; ті́мже у́бо безлунний мрак ідолобі́сія, безбо́жия же і упорства іуде́йськаго расточи́ла єси́, конці́ вся просвіща́ющи і наставля́ющи вопи́ти тебі́ си́це:","Ра́дуйся, буєсло́вних паде́ніє;","ра́дуйся, безмо́лвствующих умудреніє.","Ра́дуйся, Сві́та немерца́ющаго прича́стнице;","ра́дуйся, ра́дости неотьемлемия таї́ннице.","Ра́дуйся, дияди́мо досто́йних жен;","ра́дуйся, тайнозрительнице сла́ви дів.","Ра́дуйся, киво́те Бо́жиїх даро́в;","ра́дуйся, ковче́же благ Небе́сних.","Ра́дуйся, го́рлице чи́стая і нескве́рная;","ра́дуйся, світи́ло ді́вства і цілому́дрія.","Ра́дуйся, звіздо́ у́мнаго благомо́щія;","ра́дуйся, цельбо душе́внаго нераде́нія.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє возра́довася о челові́ціх, уві́ровати іму́щих, єгда́ ти, Фе́кло богопросвіще́нная, благода́ті і си́ли Ду́ха Свя́та іспо́лненная, Па́вла вели́каго благи́м повелі́нієм возврати́лася єси́ в зе́млю оте́чествія твоєго́, науча́ющи пі́ти немо́лчно Христу́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії ніка́коже мо́гуть по достоя́нію восхвали́ти діла́ твоя́, Фе́кло: ти бо Трифене, во Єва́нгеліє уверовавшей, висо́кий о́браз любве́ показа́ла єси́, ту научи́вши бога́тство своє́ расточи́ти боля́щим, сирота́м, убо́гим і неімущим, і́же, прия́вше дая́нія, а́біє те́плі воззва́ша:","Ра́дуйся, а́лчущих ізоби́ліє;","ра́дуйся, злоскорб'ящих весе́ліє.","Ра́дуйся, бога́тство житія́ светоявленнаго;","ра́дуйся, глави́зно воспита́нія богоуго́днаго.","Ра́дуйся, ма́нно с Небесе́, наситившая нищія;","ра́дуйся, ра́йський нектаре, возставля́яй па́дшия.","Ра́дуйся, напая́ющая та́їнственними ороше́ньми;","ра́дуйся, просвіща́ющая Боже́ственними озаре́ньми.","Ра́дуйся, а́гнице, Па́стирем знаменованная;","ра́дуйся, ді́во му́драя, Царе́м ізбра́нная.","Ра́дуйся, дерзнове́нія о Христі́ одія́ніє златошвенноє;","ра́дуйся, Єва́нгельськия любве́ ізлія́ніє светлоструйноє.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 10","ps":["Спасти́ хотя́ чрез тебі́ челові́к мно́жество, путеводительним о́блаком приведе́ тя Госпо́дь в пеще́ру Селевкійськия гори́ Каламон, іді́же пребива́ти тебі́, подви́жнице, ука́за; ти же та́мо посто́м, бді́нієм і моли́твою неісче́тная іскуше́нія препобедивши, воспі́ла єси́ Ди́вному во святи́х Свої́х: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і град тверд єси́, доброді́во, всім призива́ющим тя христия́ном, тебі́ бо благода́тію Ви́шняго даде́ся си́ла твори́ти многоразли́чная чудеса́: разсла́бленния укріпля́ти, сліпи́м очеса́ отверза́ти, де́монов от бісну́ющихся отгоня́ти; сего́ ра́ди зря́щії зна́менія сія́ взива́ху:","Ра́дуйся, чуде́с неісчерпа́ємая пучи́но;","ра́дуйся, даро́в звездосіятельная тве́рді.","Ра́дуйся, нечи́стих духо́в ізгна́ніє;","ра́дуйся, разсла́бленних возставле́ніє.","Ра́дуйся, корми́ло ві́рноє си́ли душе́вния;","ра́дуйся, фіяле злати́й моли́тви умносердечния.","Ра́дуйся, я́ко лю́ті стра́ждущих гла́си сли́шиши;","ра́дуйся, я́ко су́щим в біда́х предста́тельство показу́єши.","Ра́дуйся, є́юже дре́вній змій попира́ється;","ра́дуйся, є́юже пре́лесть облича́ється.","Ра́дуйся, ізсуше́ніє пло́ті богоуго́дноє;","ра́дуйся, утучненіє ни́ви Єва́нгельськия.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 11","ps":["Пі́ніє ті богокрасноє подоба́єть, о Фе́кло, воі́стину ревни́тельнице Апо́столов су́щей: ти бо тіх стезя́м послі́довала єси́ на землі́ і мно́гия лю́ди, в сі́ні сме́ртній сідя́щия, благові́стієм Жи́зні Ві́чния огласи́вши, научи́ла єси́ Христу́, Восто́ку восто́ков, взива́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ свята́го ді́вства твоєго́ негаси́му, о Фе́кло, сохрани́ти і́щущи от зло́би безстуднейшаго умишле́нія, умоли́ла єси́ Творця́, да разсіче́ться скала́, во о́браз Богозда́нния ра́ки ті́лу твоєму́, облече́нному снігосві́тлою ми́лотію чистоти́. Сіє́ чу́до воспомина́юще, тя ві́рою сла́вим:","Ра́дуйся, Це́ркве Христо́ви ка́меню;","ра́дуйся, низпроверженіє безбо́жия.","Ра́дуйся, основа́ніє благоче́стія неколеблемоє;","ра́дуйся, милоте цілому́дрія нерастерзная.","Ра́дуйся, я́ко тобо́ю уязви́ся челові́ков враг;","ра́дуйся, я́ко тобо́ю побіжде́н бисть лука́вий;","Ра́дуйся, вскрай мо́ря житія́ небу́рноє приста́нище;","ра́дуйся, по о́ному пловцем огню́ путеводи́тельний.","Ра́дуйся, Небе́снаго неві́стника преддве́ріє;","ра́дуйся, ра́йськія пи́щі предвкушеніє.","Ра́дуйся, Богосажде́ннаго Еде́ма сла́досте;","ра́дуйся, забве́ніє мирськи́я горечі.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 12","ps":["Благода́тію Нетлі́ннаго Жениха́ твоєго́, от Гро́ба, і́же бі в ка́мені, тридне́вно возставшаго, боголепний твой о́браз преди́вно ка́мень сокри́, да смотре́нієм Бо́жиїм утаї́ться до вре́мене дарова́нний Це́ркві світи́льник святи́я любве́, є́юже воскриля́ємі, Херуви́ми при́сно пою́ть: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще тебі́, о Фе́кло прехва́льная, піснь, є́йже досто́яше би от А́нгелов приноси́тися, велича́єм твоя́ по́двиги, почита́єм твої́х страда́ній мно́жество, хва́лим до́блеє твоє́ о Го́споді свиді́тельство, ублажа́єм же болі́зні і труди́ апо́стольськія і диві́мся си́лі є́же ко Христу́ раче́нія твоєго́, і́мже і нас восперя́єши ті восклицяти:","Ра́дуйся, крі́посте і́ноков;","ра́дуйся, си́ло пропові́дников.","Ра́дуйся, многоплете́нних посіче́ніє гріхо́в;","ра́дуйся, многообра́зних доброді́телей воня́.","Ра́дуйся, благовкусная корице житія́ чи́стаго;","ра́дуйся, лучеза́рноє зерца́ло Живота́ Ві́чнаго.","Ра́дуйся, я́ко ти лиці́ му́ченик увеселя́єши;","ра́дуйся, я́ко ти сми́сли ві́рних просвіща́єши.","Ра́дуйся, Креста́ си́лу явля́ющая;","ра́дуйся, врага́ Тім сокруша́ющая.","Ра́дуйся, добро́то всіх родо́в;","ра́дуйся, душ на́ших ра́досте.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 13","ps":["О всечестна́я первому́ченице Фе́кло, святи́м апо́столом ра́вная! Ни́нішнєє на́ше прийми́ приноше́ніє і богоприя́тним твої́м хода́тайством укріпи́ нас в до́брім по́двизі ві́ри, милосе́рдія і цілому́дрія, да с тобо́ю в Жи́зні несконча́ємій воспіва́єм Жизнода́вцю Го́споду: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́х удиви́шася, узрі́вше душі́ твоєя́ си́лу і проізволе́ніє: му́жеськими бо труди́ врага́ посрами́вши, ти, а́гниць чи́стих свяще́нная похвало́, пе́рвая в свещеноснем їх со́нме дости́гла єси́ Черто́га Преві́чнаго Жениха́, іді́же ни́ні ублажа́єма та́ко:","Ра́дуйся, красото́ му́чеников;","ра́дуйся, ра́дованіє дів і жен.","Ра́дуйся, пе́рвих пустинножи́телей о́бразе;","ра́дуйся, подви́жников благоче́стія пра́вило.","Ра́дуйся, Апо́стола верхо́внаго дщи предо́брая;","ра́дуйся, ма́ти і́ночествующих пресла́вная.","Ра́дуйся, жениха́ земна́го до́брі бежавшая;","ра́дуйся, к Жениху́ Небе́сному прекра́сно прите́кшая.","Ра́дуйся, а́гнице Христо́ва пренепоро́чная;","ра́дуйся, свіще́ Госпо́дня светлосіянная.","Ра́дуйся, є́юже ві́рнії утвержда́ються;","ра́дуйся, є́юже сопроти́внії низлага́ються.","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Кондак 1","ps":["Ізбра́нную Христо́м неві́сту богозва́нную, свята́го Па́вла учени́цю ві́рную і му́друю, земна́го жениха́ і мир презревшую і в по́двизіх пресві́тло просія́вшую, тя, Фе́кло, му́ченице пе́рвая, восхва́лим. Ти же, я́ко у Бо́га дерзнове́ніє обрі́тшая, от па́губи страсте́й і бід покри́й зову́щих ті:","Ра́дуйся, неві́сто Христо́ва, Фе́кло первострада́льная!"]},{"h":"Молитва","ps":["О ра́йський цві́те цілому́дрія, о му́чениці пе́рвійшая Заві́та Но́ваго, о Фе́кло, неві́сто Христо́ва равноа́нгельная, в страда́нії очище́нная і про́повідію апо́стольською напоє́нная, чистоти́ кри́не осія́нний, по́двиги мно́гими процвіти́й і чудеси́ пресла́вними облагоухаяй!","Кому́ уподо́бим тебі́, богозва́нная, вся́коє душепагубноє прельще́ніє попра́вшая, Ду́ха Свята́го іспо́лнь сосу́де, прему́дрости кла́дезю, цільби́ істо́чниче, і́же вся́кия стра́сти пла́мень остужаяй! Я́ко о́блак сві́тлий, прийди́ і оми́й нас дожде́м моли́тви твоєя́ от скверн душе́вних і тіле́сних. Я́коже огнь любве́ разжже́ний, уцілому́дри се́рдця на́ша і воспламени́ я ко Христу́ любо́вію. Я́ко зна́меніє му́жества в страда́ніїх непреклоннаго, укріпи́ коле́блемая се́рдця на́ша спаси́тельною си́лою Креста́ Госпо́дня; я́ко крі́пкая побо́рнице на́ша проти́ву ви́ну вражду́ющих на ни, немощни́я, бу́ди нам щит огнезра́чний необори́м, да біжа́ть от нас безсту́днії де́мони, опаля́ємії твої́ми моли́твами, да тілеса́ на́ша я́ко хра́ми Свята́го Ду́ха бу́дуть.","Єй, Фе́кло, доброді́во прему́драя, отврати́ о́чі на́ша от по́хотей ми́ра сего́, да обручимся Христу́ непоро́чною со́вістію; іспо́лни світи́льници на́ша єле́ом цілому́дрія, зане́ тя́жці согріши́ли єсьми́, ві́рности Жениху́ Христу́ не сохрани́вше, і сего́ ра́ди Черто́га Брачнаго вні затвори́тися і́мами. Оба́че не отри́ни ча́да твоя́, тебі́ моля́щаяся, но, я́ко благосе́рдая помо́щнице, облеки ни в ри́зи я́же о ві́рі крі́пости, препоя́ши чре́сла на́ша чистото́ю во умерщвле́ніє страсте́й і обновле́ніє ду́ха; па́че же і душі́ на́ша кро́тостію і смире́нієм украси́, да я́ко ча́да Бо́жії, я́коже а́гнці і овча́та Христо́ви невозбра́нно про́йдем іскуше́нія нечести́ваго ми́ра сего́, і вожделі́ннаго Черто́га Ра́йськаго да дости́гнем, іді́же вся му́дрия ді́ви Престо́лу Жениха́ Христа́ предстоя́ть, воспіва́юще достопокланя́ємоє І́м'я Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і в безконе́чния ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О богоблаже́нная свята́я первому́ченице, равноапо́стольная ді́во, Фе́кло прехва́льная, і́стинная неві́сто Христо́ва, красото́ тве́рди церко́вния, ми́сленнаго Не́ба у́тренняя звіздо́, пресві́тлий би́сере чистоти́ і цілому́дрія, са́да ра́йськаго благоуха́нний цві́те!","Ти, па́че всіх благ і са́мия жи́зні єди́наго Го́спода возлюби́вшая, до́брі за І́м'я Єго́ пострада́вшая, вінці́ ді́вства, му́ченичества і апо́стольства преди́вно от Него́ увінча́нная, лико́м Небе́сним сопричте́нная, а́ще і ра́дуєшися ни́ні во сла́ві ві́чній, но не оставлявши і нас, чту́щих тя, я́ко неуси́пную пред Бо́гом хода́таїцю і милосе́рдую на́шу предста́тельницю.","І я́коже дарова́ тебі́ ве́лію благода́ть Жени́х твой, сладча́йший Ісу́с, смире́нно мо́лим тя: воньми́ проше́нієм на́шим серде́чним, не оста́ви нас в ми́рі сем си́рих; посіти́ ни, в темни́ці гріха́ су́щия, на покая́ніє бо́дренноє ско́ро возста́ви, душі́ і ті́ла научи́ блюсти́ чистоту́, на путь доброделанія напра́ви, к єва́нгельському жи́тельству усе́рдіє вдохни́, моли́тви огнь святи́й воспламени́ і возведи́ к любві́ Боже́ственній.","Єй, добропобі́дная первострадальнице, поне́же мно́гая на по́льзу іспроси́ти мо́жеши у Многоми́лостиваго Ісу́са Спа́са на́шего, помо́щниця ско́рая в сей жи́зні бу́ди. А́нгельськоє охране́ніє нам ісхода́тайствуй, ра́ни і я́зви боля́щих уврачу́й, скорб'я́щим благода́тную отра́ду низпосли́ ю́ность і о́трочество чистото́ю огради́, і́ноком в труді́х і послуша́нії посо́бствуй, супру́жества нерасторжима соблюди́, во́їни во бра́ніх неодолими сотвори́, враги́ же ві́ри і Святи́я Це́ркве расточи́.","Проле́й, нарече́нная ізбраннице Христо́ва, моле́ніє твоє́ за ни ко Го́споду, да да́руєть нам житія́ тече́ніє неукори́зненно, ста́рость неболі́зненну, безбедну, ми́рну; кончи́ну же непости́дну, Та́їн Пресвяти́х, Ті́ла і Кро́ве Єго́ Боже́ственних, прича́стну, во є́же Ца́рствіє Небе́сноє нам улучи́ти і с чи́ньми А́нгельськими та́мо пребива́ти, і со святи́ми ку́пно воспіва́ти в Тро́йці сла́вимаго Бо́га, Отця́, і Си́на, і Свята́го Ду́ха, в безконе́чния ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Словесе́м Па́вловим научи́вшися, богоневі́стная Фе́кло, / і ві́рою утверди́вшися от Петра́, богозва́нная, / первому́чениця яви́лася єси́ і первострада́льниця в жена́х; / возшла́ єси́ на пла́мень, я́ко на мі́сто благоцвіту́щеє, / зві́ри і юнці́ устраши́шася тебі́, вооружи́ся бо Кресто́м. / Тім моли́, всехва́льная, Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Ді́вства добро́тою просія́ла єси́, / і му́ченичества вінце́м украси́лася єси́, / апо́стольству ввіря́єшися, ді́во, я́ко пресла́вная; / і огня́ у́бо пла́мень в росу́ преложи́ла єси́, / юнця́ же я́рость моли́твою твоє́ю укроти́ла єси́, // я́ко первострада́льная."]}],"notes":[]}];
export default D;
